module.exports = {"rq01-1":{"costText":"动一下脑子。","gainText":"减少「我对他那么好他却……」这类落差，判断更快。","gainTrimmed":false,"remark":"圈子会变。同事可以变成朋友，亲戚也可能疏远，按现在的关系办事，不按名分办事。","source":"费孝通《乡土中国》（1948），「差序格局」：以自己为中心，像石子投入水中形成的一圈圈波纹，越往外越疏。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-2":{"costText":"不花什么。","gainText":"知道什么能让、什么不能让，不为排场去做丢人品的事。","gainTrimmed":false,"remark":"为了面子借钱撑场面、为了面子不肯认错，代价往往远大于丢一点面子。","source":"Hu Hsien Chin (1944). The Chinese concepts of \"face\". American Anthropologist, 46(1), 45–64.（区分「脸」与「面子」两个概念。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-3":{"costText":"记得别人帮过你什么。","gainText":"想维持的关系维持得住，不想维持的关系退得干净。","gainTrimmed":false,"remark":"「欠着」只适用于互相信任的人。对不熟或有利益冲突的人，长期欠人情容易变成被要挟的把柄。","source":"阎云翔《礼物的流动：一个中国村庄中的互惠原则与社会网络》；Gouldner, A. W. (1960). The norm of reciprocity. American Sociological Review, 25(2), 161–178.","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-4":{"costText":"偶尔要顶住「不给面子」的压力。","gainText":"既不得罪人，也不替别人的事背法律责任。","gainTrimmed":false,"remark":"违规的事不因为「是熟人」就不违规，出了事追责的是经手人，见第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个忙按规定我真帮不了，换个我能做的，你看行不行？」","links":[],"evType":"经验共识"},"rq01-5":{"costText":"调整预期。","gainText":"把熟人用在刀刃上，不把人情和自己都搭进去。","gainTrimmed":false,"remark":"打听流程、咨询经验是正常的人情往来；用钱物换违规结果就越界了。","source":"《中华人民共和国刑法》第三百八十五条（受贿罪）、第三百八十九条（行贿罪）：为谋取不正当利益给予国家工作人员财物的，构成行贿罪。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-6":{"costText":"习惯用合同、聊天记录、收据办事。","gainText":"该讲情的时候讲情，该讲证据的时候有证据。","gainTrimmed":false,"remark":"哪怕是熟人之间，涉及大额钱款的事也建议留书面凭证，见第 6 章、第 12 章。","source":"费孝通《乡土中国》中关于「礼治秩序」与「法治秩序」的讨论；本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-7":{"costText":"说话时多绕半步。","gainText":"同样的意见，对方更容易接受，关系不受伤。","gainTrimmed":false,"remark":"留台阶不等于不说事实。原则问题、安全问题要说清楚，只是换个场合和语气。","source":"Goffman, E. (1955). On face-work. Psychiatry, 18(3), 213–231；Brown, P., & Levinson, S. C. (1987). Politeness: Some Universals in Language Usage. Cambridge University Press.","sourceTrimmed":false,"tip":"「你这个思路我理解，可能是我没说清楚，我们再对一下细节。」","links":[],"evType":"经验共识"},"rq01-8":{"costText":"多留一个心眼。","gainText":"享受正常的人情往来，不被「先给甜头再开口」套住。","gainTrimmed":false,"remark":"真心帮你、不图回报的人也很多，不必把所有好意都当套路，只在「回报要求远超所得」时警惕。","source":"Cialdini, R. B.《影响力》中的「互惠原理」；Regan, D. T. (1971). Effects of a favor and liking on compliance. Journal of Experimental Social Psychology, 7(6), 627–639.","sourceTrimmed":false,"tip":"「谢谢你的好意，这个我不能收，事情我们按正常流程来。」","links":[],"evType":"经验共识"},"rq01-9":{"costText":"忍住马上纠正对方的冲动。","gainText":"冲突降温快，后面的道理对方才听得进去。","gainTrimmed":false,"remark":"对方情绪失控、有暴力倾向时，先保证自己安全、离开现场，不必强行「接住」。","source":"经验共识，本书整理；与冲突沟通中「先共情、后解决」的常见建议一致。","sourceTrimmed":false,"tip":"「换我遇到这种事也会着急。你先说说具体是哪一步出的问题？」","links":[],"evType":"经验共识"},"rq01-10":{"costText":"想清楚谁更重要，并接受和一部分人慢慢变淡。","gainText":"重要的关系更深，不重要的应酬更少。","gainTrimmed":false,"remark":"邓巴数是对人类群体规模的估计，不是精确的上限，不必拿来机械套用。","source":"Dunbar, R. I. M. (1992). Neocortex size as a constraint on group size in primates. Journal of Human Evolution, 22(6), 469–493.（「邓巴数」：人能维持稳定社会关系的数量约为 150，亲密关系的圈子更小。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-11":{"costText":"偶尔和点头之交打个招呼、帮个小忙。","gainText":"找工作、换行业、办陌生的事时，多一条路。","gainTrimmed":false,"remark":"弱关系的价值在于信息和机会，不要指望弱关系替你担保、借钱或办难事。","source":"Granovetter, M. S. (1973). The strength of weak ties. American Journal of Sociology, 78(6), 1360–1380；Rajkumar, K., et al. (2022). A causal test of the strength of weak ties. Scien…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq01-12":{"costText":"开口时的一点不好意思。","gainText":"少自己硬扛，事情办得更快。","gainTrimmed":false,"remark":"请求要具体、有边界，见第 5 章；对方明确拒绝后不要反复纠缠。","source":"Flynn, F. J., & Lake, V. K. B. (2008). \"If you need help, just ask\": Underestimating compliance with direct requests for help. Journal of Personality and Social Psychology, 95(1), …","sourceTrimmed":true,"tip":"「想请教你一件事，大概占用你十分钟，你看什么时候方便？」","links":[],"evType":"经验共识"},"rq01-13":{"costText":"答应之前多想一下，答应之后不打折。","gainText":"时间越长，别人越愿意把事交给你。","gainTrimmed":false,"remark":"答应了却做不到时，越早告诉对方越好，见第 5 章。","source":"Mayer, R. C., Davis, J. H., & Schoorman, F. D. (1995). An integrative model of organizational trust. Academy of Management Review, 20(3), 709–734.（信任的三个来源：能力、善意、诚信。）","sourceTrimmed":false,"tip":"「这件事我能保证做到哪一步，后面那部分我不确定，先不跟你打包票。」","links":[],"evType":"经验共识"},"rq01-14":{"costText":"有时显得不够「讲情面」。","gainText":"不因为人情把职业前途搭进去。","gainTrimmed":false,"remark":"在企业里同样适用：用公司资源办私事、给熟人违规让利，可能构成职务侵占或非国家工作人员受贿，见第 29 章。","source":"《中华人民共和国公职人员政务处分法》；《中华人民共和国刑法》第三百八十二条（贪污罪）、第三百八十四条（挪用公款罪）、第三百九十七条（滥用职权罪、玩忽职守罪）。","sourceTrimmed":false,"tip":"「咱俩关系归关系，这个流程我得按规定走，你理解一下。」","links":[],"evType":"经验共识"},"rq01-15":{"costText":"多一点察言观色。","gainText":"不因为当真而失望，也不因为不当真而错过真心的邀请。","gainTrimmed":false,"remark":"长辈、领导说的「有事找我」，在你真遇到难处时往往是认真的，可以有分寸地试一次。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「好啊，那下周四晚上你方便吗？」（想推进时）／「好嘞，有机会一定。」（不想推进时）","links":[],"evType":"经验共识"},"rq01-16":{"costText":"观察时间。","gainText":"把信任给对的人，少交学费。","gainTrimmed":false,"remark":"观察不等于猜忌，日常交往照常真诚，只是把「交底」放慢一点。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-17":{"costText":"在「随大流」和「守本心」之间做选择。","gainText":"既能在复杂的环境里活得舒服，也能晚上睡得踏实。","gainTrimmed":false,"remark":"本书讲操控、PUA、行贿这些黑套路（第 29、30 章），只为识别和自保。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-18":{"costText":"承认自己不可能照顾到所有人。","gainText":"把钱和时间花在值得的人身上。","gainTrimmed":false,"remark":"亲情和友情不是投资，不必每笔都要回报；算账是为了避免被消耗，不是为了斤斤计较。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq01-19":{"costText":"可能被说「不合群」，失去一些机会。","gainText":"精力留给真正在乎的人和事。","gainTrimmed":false,"remark":"工作上必须参与的场合（比如部门例会、重要客户接待），不去的代价要先想清楚。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「最近手头事多，这次我就不去了，你们玩得开心。」","links":[],"evType":"经验共识"},"rq01-20":{"costText":"放下「一定要证明我对」的执念。","gainText":"事情推进得动，关系也保得住。","gainTrimmed":false,"remark":"涉及安全、合规、你自己的合法权益时，该争就要争，并且留下书面记录。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我们先不争谁对，看看怎么做能把这件事办成。」","links":[],"evType":"经验共识"},"rq01-21":{"costText":"少说几句「你应该」。","gainText":"对方觉得被理解，关系更近。","gainTrimmed":false,"remark":"对方提到想伤害自己时，不要只是倾听，要陪他寻求专业帮助，可拨打全国心理援助热线 12356。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「你是想让我帮你出出主意，还是想先吐吐槽？我都在。」","links":[],"evType":"经验共识"},"rq01-22":{"costText":"在压力面前守住线。","gainText":"做选择时有一把尺子。","gainTrimmed":false,"remark":"三条线发生冲突时，法律底线优先。","source":"本书的编写原则。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-1":{"costText":"不当真、不追问。","gainText":"不让对方尴尬，也给自己留了以后再开口的余地。","gainTrimmed":false,"remark":"工作上的关键事项不要靠猜，可以换成书面方式确认：「为了不耽误进度，想跟您确认一下，这件事这周先不推进，对吗？」","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「好的，那您先忙，有需要随时找我。」","links":[],"evType":"经验共识"},"rq02-2":{"costText":"多问一句、多准备一个方案。","gainText":"既体现了主动性，又不会办完被说「我不是这个意思」。","gainTrimmed":false,"remark":"确认可以是一条消息，不必搞得很正式；但重要事项最好有文字记录。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那我打算这样处理：……您看可以吗？没问题我就按这个办。」","links":[],"evType":"经验共识"},"rq02-3":{"costText":"多观察一点细节。","gainText":"夸得少，但每次都被记住。","gainTrimmed":false,"remark":"当着别人的面夸一个人，要注意别冷落在场的其他人。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「你刚才那个比方特别好，客户一下就听懂了。」","links":[],"evType":"经验共识"},"rq02-4":{"costText":"克制当场发火。","gainText":"对方愿意改，也不会记恨你。","gainTrimmed":false,"remark":"安全事故、违规问题需要及时制止，不必等到私下。","source":"Brown, P., & Levinson, S. C. (1987). Politeness: Some Universals in Language Usage.（批评属于「威胁面子的行为」，降低威胁的方式包括委婉、给理由、私下进行。）","sourceTrimmed":false,"tip":"「这次的问题主要在核对环节，下次发出去前我们一起过一遍，好吗？」","links":[],"evType":"经验共识"},"rq02-5":{"costText":"管住好奇心。","gainText":"别人和你聊天时放松，不怕被「审问」。","gainTrimmed":false,"remark":"被别人问到这类问题时怎么接，见第 11 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-6":{"costText":"一点临场反应。","gainText":"保护隐私，也不让场面冷下来。","gainTrimmed":false,"remark":"对方反复追问，可以温和但明确地说：「这个我不太想聊，换个话题吧。」","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「够花，饿不着。您最近身体怎么样？」／「还在看机会，定了第一时间告诉您。」","links":[],"evType":"经验共识"},"rq02-7":{"costText":"替对方多想一步。","gainText":"对方更容易答应，答应了也更痛快。","gainTrimmed":false,"remark":"怎么把求助信息写完整，见第 5 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「材料我都整理好了，你只要帮忙看一下第二部分，十分钟就够。」","links":[],"evType":"经验共识"},"rq02-8":{"costText":"放下「必须马上回答」的压力。","gainText":"少说错话，少背锅。","gainTrimmed":false,"remark":"说了「确认一下」就要给时间点，并且按时回复，否则就成了推脱。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个数据我想再核对一下，今天下班前回复您。」","links":[],"evType":"经验共识"},"rq02-9":{"costText":"放下面子承认错误。","gainText":"对方更容易原谅，信任修复得更快。","gainTrimmed":false,"remark":"涉及赔偿、法律责任的事，口头道歉前先想清楚边界，书面承诺可能被当作证据。","source":"Lewicki, R. J., Polin, B., & Lount, R. B. (2016). An exploration of the structure of effective apologies. Negotiation and Conflict Management Research, 9(2), 177–196.（六个道歉要素中，…","sourceTrimmed":true,"tip":"「是我没核对清楚，导致你白跑一趟。我已经改好了，明天我直接给你送过去。」","links":[],"evType":"经验共识"},"rq02-10":{"costText":"换一种说法。","gainText":"同样的关心，对方更容易接受。","gainTrimmed":false,"remark":"长辈对你说这句话时，可以理解为表达关心的方式，不必逐字较真。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我看你最近总加班到很晚，有点担心你身体，要不要我帮你分担点？」","links":[],"evType":"经验共识"},"rq02-11":{"costText":"把话咽回去。","gainText":"别人愿意在你面前放松，因为知道你不会拿他开刀。","gainTrimmed":false,"remark":"被别人当众揭短时，可以一笑带过，事后私下告诉对方你不舒服。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-12":{"costText":"少几个「梗」。","gainText":"气氛轻松，不得罪人。","gainTrimmed":false,"remark":"对方明确表示不舒服时，立刻停下并道歉，不要说「你怎么这么开不起玩笑」。涉及性别、身体的「玩笑」在职场可能构成性骚扰，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-13":{"costText":"多说一句话。","gainText":"意见更容易被采纳，也不伤和气。","gainTrimmed":false,"remark":"对方是领导时，反对意见尽量在决策前提，决策后再提要更谨慎，见第 18 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我理解您是想先上线再优化，这样能抢时间。我担心的是支付那块没测完，万一出问题影响大。能不能先上其他模块，支付晚两天？」","links":[],"evType":"经验共识"},"rq02-14":{"costText":"多问一句偏好。","gainText":"既尊重对方，又不会买了不喜欢的东西。","gainTrimmed":false,"remark":"长辈说「不要花钱」时，往往是真心心疼你；买一点实用的、不贵的东西，比买贵的更让他们安心。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那我订那家粤菜或者那家本帮菜，您更想吃哪个？」","links":[],"evType":"经验共识"},"rq02-15":{"costText":"改改口头禅。","gainText":"对方更愿意面对问题本身。","gainTrimmed":false,"remark":"对外承诺时也一样，「肯定没问题」比「我尽力，有风险会提前告诉你」更容易让你失信。","source":"Gottman, J. M., & Silver, N.《幸福的婚姻》（The Seven Principles for Making Marriage Work）中关于「批评」与「抱怨」的区分：针对具体行为的抱怨比针对人格的批评更不容易引发冲突升级。","sourceTrimmed":false,"tip":"「这周三次约好的时间你都晚了半小时，我有点着急。」","links":[],"evType":"经验共识"},"rq02-16":{"costText":"多等两秒。","gainText":"对方愿意多说，你也能听到更多真实信息。","gainTrimmed":false,"remark":"会议时间有限、对方跑题很远时，可以礼貌打断：「抱歉打断一下，我们先把这个议题定下来。」","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-17":{"costText":"克制「添油加醋」的冲动。","gainText":"不当「传声筒」背锅，也不制造矛盾。","gainTrimmed":false,"remark":"如果有人让你传带有侮辱、威胁的话，可以拒绝转达。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总让我转告，方案周五前要定稿。具体修改意见他说会单独发给你。」","links":[],"evType":"经验共识"},"rq02-18":{"costText":"有意见当面说，承受一点尴尬。","gainText":"别人觉得你可靠，不会防着你。","gainTrimmed":false,"remark":"工作中遇到真实的违规、骚扰问题，通过正式渠道反映，不属于「背后说人」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-19":{"costText":"收起比较的冲动。","gainText":"对方愿意继续跟你说心里话。","gainTrimmed":false,"remark":"对方情绪持续低落、影响睡眠饮食两周以上，建议陪他去看精神心理科。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事搁谁身上都难受，你已经扛得很不错了。」","links":[],"evType":"经验共识"},"rq02-20":{"costText":"显得稍微拘谨。","gainText":"不因为「太自来熟」给人留下轻浮的印象。","gainTrimmed":false,"remark":"称呼的细节见第 3 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq02-21":{"costText":"把责任往自己这边拉一点。","gainText":"误会解开得快，不变成争吵。","gainTrimmed":false,"remark":"涉及责任认定、合同条款的误会，要以书面文字为准，不要为了客气承认自己没有说过的话。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「可能是我刚才没说清楚，我的意思是……」","links":[],"evType":"经验共识"},"rq02-22":{"costText":"多一句缓冲。","gainText":"拒绝了事，没拒绝人。","gainTrimmed":false,"remark":"对方的需求本身不合理、不合法时，不必先说「是」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「你想周末前拿到我理解，这周我实在排不开，周一上午可以吗？」","links":[],"evType":"经验共识"},"rq03-1":{"costText":"多留意一下。","gainText":"开口就不失礼。","gainTrimmed":false,"remark":"对方纠正你的称呼时，马上改口并道个谢，不必过度道歉。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-2":{"costText":"区分场合。","gainText":"口头上照顾对方面子，书面上不出错。","gainTrimmed":false,"remark":"正职和副职同时在场时，当面也尽量叫准，避免场面尴尬。","source":"经验共识，本书整理；公文中职务表述以《党政机关公文处理工作条例》等规范为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-3":{"costText":"开口前问一句。","gainText":"长辈觉得你懂事，不闹笑话。","gainTrimmed":false,"remark":"实在叫不出，用「您」加笑脸，比叫错强。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「妈，待会儿那位我该叫什么？」","links":[],"evType":"经验共识"},"rq03-4":{"costText":"记住一个顺序。","gainText":"双方很快进入状态，你也显得周到。","gainTrimmed":false,"remark":"非正式场合不必拘泥，介绍清楚比顺序更重要。","source":"通行商务礼仪做法，常见于国内商务礼仪教材（如金正昆《商务礼仪教程》）。","sourceTrimmed":false,"tip":"「张总，这是我们部门的小李，负责这次项目的落地。小李，这位是客户方的张总。」","links":[],"evType":"经验共识"},"rq03-5":{"costText":"提前想好。","gainText":"对方愿意继续聊，也记得住你。","gainTrimmed":false,"remark":"饭局、聚会里的自我介绍可以更轻松，加一点个人兴趣就够了。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师您好，我是李明，在 X 公司做数据分析，上次听您讲座很受启发，想请教您一个关于调研方法的问题。」","links":[],"evType":"经验共识"},"rq03-6":{"costText":"一点刻意练习。","gainText":"别人觉得被重视，关系起点更高。","gainTrimmed":false,"remark":"真的忘了名字，可以坦白：「抱歉，我记性不好，您贵姓来着？」比含糊过去好。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-7":{"costText":"慢半拍。","gainText":"细节到位，给人稳重的印象。","gainTrimmed":false,"remark":"疫情后不少人习惯点头或拱手代替握手，对方不伸手时不必勉强。","source":"通行商务礼仪做法，见国内商务礼仪教材。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-8":{"costText":"几秒钟。","gainText":"一个小动作就显得尊重对方。","gainTrimmed":false,"remark":"现在很多人直接加微信，同样适用：加完当面改好备注。","source":"通行商务礼仪做法，见国内商务礼仪教材。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-9":{"costText":"留出路上的余量。","gainText":"开局不被扣分。","gainTrimmed":false,"remark":"确实要迟到，提前告诉对方预计几点到，见面先道歉，不要找一堆理由。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-10":{"costText":"持续靠谱。","gainText":"既重视开局，也不因为开局没发挥好而放弃。","gainTrimmed":false,"remark":"反过来也成立：别只凭第一面就给别人下结论。","source":"Willis, J., & Todorov, A. (2006). First impressions: Making up your mind after a 100-ms exposure to a face. Psychological Science, 17(7), 592–598.","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-11":{"costText":"一身得体的衣服。","gainText":"不因为穿错衣服而在开场就落了下风。","gainTrimmed":false,"remark":"丧事、宗教场所有专门的着装禁忌，见第 27 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-12":{"costText":"十秒钟。","gainText":"不会对着头像发愣，也不会认错人说错话。","gainTrimmed":false,"remark":"备注里别写评价性的词，手机被别人看到会很尴尬。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-13":{"costText":"改改网络口头禅。","gainText":"不因为一个称呼被看轻。","gainTrimmed":false,"remark":"面对客户时，「亲」在电商客服场景是行业习惯，其他场合慎用。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-14":{"costText":"不花什么。","gainText":"减少「该叫什么」的尴尬。","gainTrimmed":false,"remark":"在政府机关、国企，通常还是称职务更合适。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-15":{"costText":"观察一两天。","gainText":"快速融入，不显得格格不入。","gainTrimmed":false,"remark":"对比你年轻的女性同事叫「姐」，有人会介意，拿不准就叫名字。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-16":{"costText":"一句话。","gainText":"既不让对方难堪，也不至于被叫错几年。","gainTrimmed":false,"remark":"正式文件、合同、证书上的名字写错，必须当场要求改正。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我叫李婷，女字旁的婷，很多人都会记成亭子的亭。」","links":[],"evType":"经验共识"},"rq03-17":{"costText":"一份不贵的见面礼。","gainText":"主人觉得你懂礼数。","gainTrimmed":false,"remark":"对方家里有孩子，带一份适合孩子的小礼物，常常比给大人的礼物更受欢迎。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq03-18":{"costText":"多两个字。","gainText":"一句话的开头就显得有教养。","gainTrimmed":false,"remark":"在群里发消息时，用 @ 加称呼，比没头没尾的一句话更清楚。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq04-1":{"costText":"顶住对方等你表态的那几秒。","gainText":"减少一时冲动的承诺，拒绝也更从容。","gainTrimmed":false,"remark":"说了晚上回就要晚上回；拖着不回，对方会觉得你在敷衍。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我得先看下这周的安排，晚上给你准信。」","links":[],"evType":"经验共识"},"rq04-2":{"costText":"说一句实话的不自在。","gainText":"拒绝得干脆，也不留后患。","gainTrimmed":false,"remark":"不想给理由也可以，「这个我帮不了」本身就是完整的回答。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这周我实在排不开，不是不想帮你。」","links":[],"evType":"经验共识"},"rq04-3":{"costText":"动脑子想一个你能做的事。","gainText":"既守住了自己的边界，又显得有诚意。","gainTrimmed":false,"remark":"替代方案也要是你真心愿意做的，别为了显得热情又给自己挖坑。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事我不熟，不过小王之前做过，我把他微信推给你？」","links":[],"evType":"经验共识"},"rq04-4":{"costText":"可能让对方不高兴。","gainText":"不被反复拉扯，也不让对方空等。","gainTrimmed":false,"remark":"决定要借的，写借条、走转账，见第 16 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次我手头真的不方便，帮不上你，别耽误你找别的办法。」","links":[],"evType":"经验共识"},"rq04-5":{"costText":"承受对方的情绪。","gainText":"不被情感绑架，也看清谁是真朋友。","gainTrimmed":false,"remark":"反复出现这种模式的关系，见第 30 章关于情感勒索的部分。","source":"Forward, S., & Frazier, D. (1997). Emotional Blackmail. HarperCollins.（情感勒索常用恐惧、义务、愧疚三种情绪迫使对方让步。）","sourceTrimmed":false,"tip":"「我们是朋友，所以我才跟你说实话：这件事我真的做不了。」","links":[],"evType":"经验共识"},"rq04-6":{"costText":"一次坦诚的沟通。","gainText":"不被无限加活，也不会被看成推诿。","gainTrimmed":false,"remark":"长期严重超时加班、被要求做违法违规的事，可以拒绝并保留证据，见第 21 章、第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我现在手上有 A 和 B，周五都要交。这个新任务要是更急，A 能不能往后推两天？」","links":[],"evType":"经验共识"},"rq04-7":{"costText":"一条消息。","gainText":"拒绝了邀请，没得罪组织者。","gainTrimmed":false,"remark":"重要的场合（比如领导组织的部门聚餐、亲友的婚宴）不去之前要想清楚代价。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那天我有安排，去不了，你们吃好喝好，下回我做东。」","links":[],"evType":"经验共识"},"rq04-8":{"costText":"顶着「你以前都帮的」那句话。","gainText":"一次帮忙不会变成长期负担。","gainTrimmed":false,"remark":"知道这个效应，不是让你拒绝一切小请求，而是在请求一步步加码时提醒自己停一下。","source":"Freedman, J. L., & Fraser, S. C. (1966). Compliance without pressure: The foot-in-the-door technique. Journal of Personality and Social Psychology, 4(2), 195–202.（先答应小请求的人，…","sourceTrimmed":true,"tip":"「上次是正好赶上了，以后这种事我真没办法每次都帮。」","links":[],"evType":"经验共识"},"rq04-9":{"costText":"多想一层。","gainText":"不被「让步」的错觉牵着走。","gainTrimmed":false,"remark":"推销、培训、理财产品里很常见；在正常的谈判里，双方互相让步本身没问题。","source":"Cialdini, R. B., et al. (1975). Reciprocal concessions procedure for inducing compliance: The door-in-the-face technique. Journal of Personality and Social Psychology, 31(2), 206–2…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq04-10":{"costText":"咽下失望。","gainText":"保住关系，也给下次留了余地。","gainTrimmed":false,"remark":"对方答应过、后来反悔并造成损失的，属于另一回事，可以就事实沟通。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「没事，理解，你也有你的难处。」","links":[],"evType":"经验共识"},"rq04-11":{"costText":"再开一次口。","gainText":"不因为一次拒绝放弃本来能办成的事。","gainTrimmed":false,"remark":"对方明确表示不希望再被联系时，尊重对方的意愿。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「好的，方便的话能告诉我哪里还不够吗？我改进一下。」","links":[],"evType":"经验共识"},"rq04-12":{"costText":"一点不好意思。","gainText":"守住钱包，也不被一次次追着问。","gainTrimmed":false,"remark":"要求你交钱入会、再拉人头才能赚钱的，可能涉嫌传销，见第 30 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我现在真不需要，你有其他事我能帮的再找我。」","links":[],"evType":"经验共识"},"rq04-13":{"costText":"一次难开口的对话。","gainText":"对方能早点放下，你也不必长期应付。","gainTrimmed":false,"remark":"被拒绝后仍持续纠缠、跟踪、威胁的，可以报警或申请人身安全保护令，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「谢谢你喜欢我，但我对你没有那种感觉，不想让你误会。」","links":[],"evType":"经验共识"},"rq04-14":{"costText":"可能被说「不孝」「不懂事」。","gainText":"既保住了长幼的面子，也没让自己担风险。","gainTrimmed":false,"remark":"担保尤其要谨慎，一旦签字就要承担还款责任，见第 16 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「舅舅，这事我真做不了主，也不想答应了办不好，耽误您。」","links":[],"evType":"经验共识"},"rq04-15":{"costText":"可能让提要求的人不痛快。","gainText":"守住底线，又不显得是在和对方作对。","gainTrimmed":false,"remark":"被上级施压时，尽量把要求留成文字（邮件、消息），见第 28 章。","source":"《中华人民共和国刑法》第二百二十九条（提供虚假证明文件罪）、第二百八十条（伪造、变造、买卖国家机关公文、证件、印章罪）等。","sourceTrimmed":false,"tip":"「这个签了字是要我个人负责的，出了问题我和您都说不清，我们按流程走吧。」","links":[],"evType":"法条"},"rq04-16":{"costText":"多发一条私信。","gainText":"不在众人面前让人下不来台。","gainTrimmed":false,"remark":"工作群里领导@你分配任务，要正面回复，见第 26 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（私聊）「群里那个我这次就不参与了哈，有别的事你再叫我。」","links":[],"evType":"经验共识"},"rq04-17":{"costText":"接受有人会觉得你变了。","gainText":"不被消耗，帮人时也更真心。","gainTrimmed":false,"remark":"长期因为不敢拒绝而焦虑、失眠，可以考虑心理咨询，学习自我肯定的表达方式。","source":"Grant, A.《沃顿商学院最受欢迎的成功课》（Give and Take, 2013）：给予者里最失败和最成功的都有，区别之一在于能否识别索取者、保护自己的时间。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq04-18":{"costText":"承认自己高估了能力或时间。","gainText":"失了一次约，没失掉信任。","gainTrimmed":false,"remark":"这类情况多了，说明你答应得太快，回到第 1 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「之前答应你周五给，我评估了一下大概要到下周二，你看来得及吗？不行我先把能用的部分发你。」","links":[],"evType":"经验共识"},"rq04-19":{"costText":"克制愧疚感。","gainText":"拒绝干净利落，关系照常。","gainTrimmed":false,"remark":"如果确实是你之前答应了又反悔，诚恳道歉并尽量补救，见第 2 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq04-20":{"costText":"改变心态。","gainText":"少一些内耗，人际关系更轻松。","gainTrimmed":false,"remark":"在需要承担法定或约定义务的场合（比如赡养、合同履行），不能以「拒绝的权利」为由逃避责任。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-1":{"costText":"开口前想五分钟。","gainText":"不让对方为难，也不浪费人情。","gainTrimmed":false,"remark":"请人帮忙做违规的事，是在拿对方的前途冒险，见第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-2":{"costText":"多写几句话。","gainText":"对方能快速判断帮不帮得了，答应率更高。","gainTrimmed":false,"remark":"微信上别只发「在吗」，直接把事情说出来，对方可以有空再回。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师好，我在准备一个调研报告，有个统计方法拿不准，想请您帮忙看一下第三页的分析是否合理，大概十分钟。您这周哪天方便？」","links":[],"evType":"经验共识"},"rq05-3":{"costText":"你自己多做准备。","gainText":"对方愿意帮，而且帮得快。","gainTrimmed":false,"remark":"对方提出修改意见后，按意见改好再反馈一次，让他知道自己的帮助有用。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-4":{"costText":"开口的不好意思。","gainText":"既把事办了，也加深了关系。","gainTrimmed":false,"remark":"前提是请求合理、对方力所能及；频繁索取、只求不还会适得其反。","source":"Jecker, J., & Landy, D. (1969). Liking a person as a function of doing him a favour. Human Relations, 22(4), 371–378.（俗称「富兰克林效应」。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-5":{"costText":"一条消息或一顿饭。","gainText":"对方觉得帮得值，下次还愿意帮你。","gainTrimmed":false,"remark":"事情没办成也要告诉对方，并感谢他的努力。","source":"Kumar, A., & Epley, N. (2018). Undervaluing gratitude: Expressers misunderstand the consequences of showing appreciation. Psychological Science, 29(9), 1423–1435.（表达感谢的人普遍低估了对方收到感谢…","sourceTrimmed":true,"tip":"「上次您帮我改的那版材料，评审都过了，尤其您建议加的那组数据，评委专门问到了。太感谢了！」","links":[],"evType":"经验共识"},"rq05-6":{"costText":"自己多跑几步。","gainText":"中间人愿意再帮你引荐。","gainTrimmed":false,"remark":"被引荐的人没帮上忙，不要回头抱怨中间人。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对中间人）「谢谢你帮我联系上李老师，后面我直接跟他对接，有结果第一时间告诉你。」","links":[],"evType":"经验共识"},"rq05-7":{"costText":"一次得体的答谢。","gainText":"表达了感谢，又不变味。","gainTrimmed":false,"remark":"私人朋友之间正常的人情往来不受影响，界线在于「给的是谁」和「换的是什么」。","source":"《中华人民共和国刑法》第三百八十九条（行贿罪）；《中国共产党纪律处分条例》关于收受可能影响公正执行公务的礼品、礼金的规定。","sourceTrimmed":false,"tip":"「这次真的多亏你，周末请你吃个饭，别推。」","links":[],"evType":"经验共识"},"rq05-8":{"costText":"一句提前说明。","gainText":"帮了忙，不背结果的锅。","gainTrimmed":false,"remark":"为别人做担保、作证明、签字，属于另一种层次的「帮忙」，要慎重得多。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我可以把你的简历转给他们 HR，能不能进还得看面试，我没法打包票。」","links":[],"evType":"经验共识"},"rq05-9":{"costText":"可能得罪想让你推荐的人。","gainText":"你的推荐有分量。","gainTrimmed":false,"remark":"内推、推荐信都不要替对方编造经历。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「他做事很踏实，数据分析是强项，带团队的经验还少一些。」","links":[],"evType":"经验共识"},"rq05-10":{"costText":"多想一层。","gainText":"分清楚是救急还是救穷。","gainTrimmed":false,"remark":"俗话说「救急不救穷」，意思是突发困难可以帮，长期的生活问题要对方自己解决。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-11":{"costText":"管住嘴。","gainText":"帮出去的人情更干净，关系更自然。","gainTrimmed":false,"remark":"涉及工作的帮助需要备案、报备的（比如回避制度、利益冲突申报），按规定说明，不属于邀功。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-12":{"costText":"自己先做功课。","gainText":"多数事情自己就能办，少欠人情。","gainTrimmed":false,"remark":"窗口工作人员没有一次性告知材料、反复让你跑的，可以投诉，见第 24 章。","source":"《优化营商环境条例》（2019）关于一次性告知、限时办结等要求；各地 12345 政务服务便民热线。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-13":{"costText":"放低预期。","gainText":"朋友愿意帮，你也不欠太多。","gainTrimmed":false,"remark":"帮你的人是专业的、并且本来就以此谋生，主动提出付费更体面。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「整体很好了，就是标题能不能再大一点？其他我都满意，辛苦你了。」","links":[],"evType":"经验共识"},"rq05-14":{"costText":"教比做更费时间。","gainText":"你省了以后的时间，对方也真的成长了。","gainTrimmed":false,"remark":"对方明显是在把自己的工作推给你，回到第 4 章的边界设定。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个步骤我写在文档里了，你照着走一遍，卡住了再叫我。」","links":[],"evType":"经验共识"},"rq05-15":{"costText":"耐心等一个人的结果。","gainText":"不浪费别人的人情。","gainTrimmed":false,"remark":"事情一旦有了着落，马上告诉其他帮忙的人，并表示感谢。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事我也问了另外两个朋友，你方便就帮我留意下，不用特意跑。」","links":[],"evType":"经验共识"},"rq05-16":{"costText":"一句话。","gainText":"保住这段关系。","gainTrimmed":false,"remark":"不要追问「是不是没尽力」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「没成也没关系，你为这事跑了好几趟，真的谢谢你。」","links":[],"evType":"经验共识"},"rq05-17":{"costText":"克服打电话的不自在。","gainText":"对方更容易答应，也更重视。","gainTrimmed":false,"remark":"对方很忙或明确偏好文字沟通的，尊重对方的习惯。","source":"Roghanizad, M. M., & Bohns, V. K. (2017). Ask in person: You're less persuasive than you think over email. Journal of Experimental Social Psychology, 69, 223–226.","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-18":{"costText":"先搜索五分钟。","gainText":"问题更好回答，对方也觉得你靠谱。","gainTrimmed":false,"remark":"新人刚入职时多问是正常的，但同一个问题尽量不问第二遍，见第 17 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我查了官网和几篇教程，都说要先备案，但我这个情况属于例外吗？」","links":[],"evType":"经验共识"},"rq05-19":{"costText":"可能得罪人。","gainText":"不因为别人的违规把自己卷进去。","gainTrimmed":false,"remark":"普通人际关系中的小事不必上纲上线，这条针对的是涉及职务和公共利益的请求。","source":"《中华人民共和国公职人员政务处分法》；各单位廉洁从业、利益冲突报告制度。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq05-20":{"costText":"自己多跑腿。","gainText":"关键时刻有人愿意帮。","gainTrimmed":false,"remark":"人情账怎么记、怎么还，见第 6 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-1":{"costText":"每次随礼、收礼后记一笔。","gainText":"回礼不失礼，不多不少。","gainTrimmed":false,"remark":"账本只给自己看，不要拿出来和别人对质。","source":"阎云翔《礼物的流动》中对村庄「礼单」的研究：很多家庭会保存礼单，作为日后回礼的依据。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-2":{"costText":"一份相当的礼金。","gainText":"往来平衡，关系稳定。","gainTrimmed":false,"remark":"对方家境明显困难的，可以适当多一点，但不要让对方觉得被施舍。","source":"经验共识，本书整理；各地习惯不同，以当地为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-3":{"costText":"留心对方需要什么。","gainText":"还了人情，关系也更近。","gainTrimmed":false,"remark":"对方是因为工作职责帮你办事的，用感谢信、好评、向其单位反馈表扬就够了，不必送钱物。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-4":{"costText":"一份及时的回礼。","gainText":"不被人情绑住。","gainTrimmed":false,"remark":"两清之后保持礼貌即可，不必刻意疏远。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-5":{"costText":"可能显得不近人情。","gainText":"不被提前「埋」下人情。","gainTrimmed":false,"remark":"国家工作人员收受下属、管理对象价值三万元以上财物，可能影响职权行使的，可被视为承诺为他人谋取利益，见第 29 章。","source":"《中华人民共和国刑法》第三百八十五条（受贿罪）；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释》（2016）关于「感情投资」型收受财物的规定。","sourceTrimmed":false,"tip":"「心意领了，东西真不能收，有什么事你直说就行。」","links":[],"evType":"经验共识"},"rq06-6":{"costText":"调整期待。","gainText":"少受伤，少被消耗。","gainTrimmed":false,"remark":"家人、病中的朋友、处境艰难的人，可以暂时不讲对等。","source":"Grant, A.《沃顿商学院最受欢迎的成功课》（Give and Take, 2013）中对「索取者」的描述。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-7":{"costText":"一句承诺和一份兑现。","gainText":"人情有来有往，关系越走越近。","gainTrimmed":false,"remark":"对方提出的请求违规或超出能力时，可以按第 4 章的方法拒绝，不算食言。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次真的多亏你，以后你那边有用得上我的，一定开口。」","links":[],"evType":"经验共识"},"rq06-8":{"costText":"一点额外的心意。","gainText":"下次真遇到难处，对方还愿意帮。","gainTrimmed":false,"remark":"对方主动说不用还的，要当作赠与认真道谢；有能力时仍可在对方需要时回报。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「钱给你转过去了，那会儿真是多亏你，改天我请你吃饭。」","links":[],"evType":"经验共识"},"rq06-9":{"costText":"开口谈钱的尴尬。","gainText":"不让一桩生意毁掉一段关系。","gainTrimmed":false,"remark":"熟人说「不要钱」时，可以用礼物或回请的方式补上，别真的白占。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「咱们亲兄弟明算账，你按正常价报，材料单子也给我一份，这样我心里踏实。」","links":[],"evType":"经验共识"},"rq06-10":{"costText":"逢年过节的一条问候、偶尔的一次拜访。","gainText":"感恩被看见，关系能走很久。","gainTrimmed":false,"remark":"问候要单独发、带称呼，群发的祝福基本等于没发，见第 26 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师，新年快乐！今年我换到了新岗位，挺顺利的，一直记着您当年的指点。」","links":[],"evType":"经验共识"},"rq06-11":{"costText":"咽下想提醒的话。","gainText":"保住你帮人时的那份体面。","gainTrimmed":false,"remark":"对方拿了钱物明确约定要还却赖账，属于债务问题，按第 16 章、第 28 章处理。","source":"Hwang, K.-K. (1987). Face and favor: The Chinese power game. American Journal of Sociology, 92(4), 944–974.（人情往来中，施恩方公开强调恩惠，会让受恩方陷入「欠情又丢面子」的处境。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-12":{"costText":"在别人疏远他时靠近他。","gainText":"人情还在最有分量的地方。","gainTrimmed":false,"remark":"探望病人有讲究，见第 31 章；对方因违纪违法落马的，不要为其奔走「疏通」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「听说你最近身体不太好，我明天过去看看你，需要带点什么吗？」","links":[],"evType":"经验共识"},"rq06-13":{"costText":"判断一下这段关系还剩多少。","gainText":"钱花在还会来往的人身上。","gainTrimmed":false,"remark":"对方以前给你随过礼的，按人情账回一份更妥当。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「恭喜恭喜！那天实在赶不过去，祝你们新婚快乐。」","links":[],"evType":"经验共识"},"rq06-14":{"costText":"认识父母的几位老朋友。","gainText":"父母晚年的人际圈不至于断掉，你也多一份可以依靠的关系。","gainTrimmed":false,"remark":"不用全盘接手，先问父母哪几家是真正的「老交情」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-15":{"costText":"可能被说「不会做人」。","gainText":"人情不再变成负担。","gainTrimmed":false,"remark":"各地都有遏制高额随礼、大操大办的移风易俗倡导，可以作为降低标准的理由。","source":"阎云翔《礼物的流动》中关于农村礼金负担与「人情压力」的研究；各地婚俗改革中关于遏制人情攀比的倡导。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-16":{"costText":"一条消息。","gainText":"对方的心意落了地，不留疙瘩。","gainTrimmed":false,"remark":"不该收的礼，退回时同样要客气，见第 7 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「东西收到了，特别喜欢，让你破费了！」","links":[],"evType":"经验共识"},"rq06-17":{"costText":"多一点宽容。","gainText":"不因为小事伤大情。","gainTrimmed":false,"remark":"不要在背后议论别人随了多少，这比少随更伤人。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq06-18":{"costText":"长期放在心上。","gainText":"做一个让人愿意在关键时刻帮的人。","gainTrimmed":false,"remark":"报恩也要守底线，对方要求你做违法的事，可以用别的方式回报。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-1":{"costText":"想明白再出手。","gainText":"分清界线，不糊里糊涂踩线。","gainTrimmed":false,"remark":"具体界线见第 29 章。","source":"《中华人民共和国刑法》第三百八十九条（行贿罪）、第一百六十四条（对非国家工作人员行贿罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-2":{"costText":"留心观察。","gainText":"礼物真的被用上，心意才被记住。","gainTrimmed":false,"remark":"可以问对方的家人或好友他最近缺什么，比自己猜准。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-3":{"costText":"克制「送贵点显得有诚意」的想法。","gainText":"对方收得自在，不因回礼发愁。","gainTrimmed":false,"remark":"对至亲、恩人在重要时刻送一份重礼，另当别论。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-4":{"costText":"送前想一想。","gainText":"不因为一个谐音让好心变尴尬。","gainTrimmed":false,"remark":"对方明确说喜欢某件东西（比如一块好表），就不必拘泥于忌讳。","source":"民间习俗，各地差异较大，本书整理；更多地方差异见第 27 章。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-5":{"costText":"一句话。","gainText":"礼送出去，人情不打折。","gainTrimmed":false,"remark":"用双手递，正对对方，比随手放在桌上更有礼貌。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「没什么贵重的，带了点老家的茶叶，您别嫌弃。」","links":[],"evType":"经验共识"},"rq07-6":{"costText":"读懂对方的态度。","gainText":"既尽了礼数，也不让对方左右为难。","gainTrimmed":false,"remark":"对方是公职人员、医生、老师并以规定为由拒绝时，立即收回，见本节第 9 至 11 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那我就不勉强了，心意您收下就好。」","links":[],"evType":"经验共识"},"rq07-7":{"costText":"一点表情管理。","gainText":"对方的心意得到回应。","gainTrimmed":false,"remark":"多人同时送礼的场合，避免当众比较谁送的更好。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个颜色正好是我想要的，你太懂我了！」","links":[],"evType":"经验共识"},"rq07-8":{"costText":"分寸的拿捏。","gainText":"人情到位，不惹是非。","gainTrimmed":false,"remark":"领导是国家工作人员，或者你要在他负责的评定、审批中得到照顾时，见第 29 章。","source":"经验共识，本书整理；以所在单位的廉洁从业制度为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-9":{"costText":"放弃「打点一下」的念头。","gainText":"不给自己和对方埋雷。","gainTrimmed":false,"remark":"亲友之间正常的人情往来不在此列，但价值明显超出正常往来、对方又能在你的事情上行使职权时，界线就模糊了，见第 29 章。","source":"中央八项规定及其实施细则（2012）；《中国共产党纪律处分条例》（2023 年修订）；《中华人民共和国刑法》第三百八十九条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-10":{"costText":"一张卡片或一段留言。","gainText":"老师收到真正的认可，孩子也学会感恩。","gainTrimmed":false,"remark":"老师明示或暗示索要财物的，可以向学校或当地教育部门反映。","source":"教育部《新时代中小学教师职业行为十项准则》（2018）第九条；《新时代幼儿园教师职业行为十项准则》（2018）。","sourceTrimmed":false,"tip":"「王老师，这学期孩子数学进步很大，谢谢您的耐心，孩子也特别喜欢您。」","links":[],"evType":"法条"},"rq07-11":{"costText":"打消「不送不放心」的顾虑。","gainText":"表达了感谢，不让医生为难。","gainTrimmed":false,"remark":"有人以「不给红包不安排手术」等方式索要的，可以向医院纪检部门或卫健委投诉。","source":"国家卫生健康委等《医疗机构工作人员廉洁从业九项准则》（2021）。","sourceTrimmed":false,"tip":"「李医生，这次手术多亏您，我们写了封感谢信交给科室了。」","links":[],"evType":"经验共识"},"rq07-12":{"costText":"一份不贵的零食。","gainText":"花小钱，攒人缘。","gainTrimmed":false,"remark":"注意同事的饮食禁忌（清真、过敏、控糖）。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这是那边的特色饼，放茶水间了，大家随便拿哈。」","links":[],"evType":"经验共识"},"rq07-13":{"costText":"问一句家属。","gainText":"东西有用，家属也感受到你的用心。","gainTrimmed":false,"remark":"探病的时间和说话分寸，见第 31 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「阿姨，叔叔现在饮食上有什么要注意的吗？我带点他能吃的。」","links":[],"evType":"经验共识"},"rq07-14":{"costText":"一次婉拒的沟通。","gainText":"干净，经得起查。","gainTrimmed":false,"remark":"两高 2007 年关于受贿案件的意见认为，收受财物后及时退还或上交的，不是受贿；为掩饰犯罪才退还的，不影响认定。所以退要及时。","source":"中共中央办公厅、国务院办公厅《关于对党和国家机关工作人员在国内交往中收受的礼品实行登记制度的规定》（1995）；《中国共产党纪律处分条例》（2023 年修订）。","sourceTrimmed":false,"tip":"「谢谢你的好意，单位规定这类东西我不能收，已经给你退回去了，事情我们按流程办。」","links":[],"evType":"官方文件"},"rq07-15":{"costText":"早安排几天。","gainText":"礼物用得上，心意更到位。","gainTrimmed":false,"remark":"寄之前发消息说一声，免得对方拒收或不知道是谁寄的。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-16":{"costText":"换一个思路。","gainText":"礼物里有关心，不只是面子。","gainTrimmed":false,"remark":"长辈确实爱喝、身体也允许的，少量好酒可以，别成箱送。","source":"世界卫生组织关于烟草与饮酒健康危害的事实说明；中国疾控中心关于控烟限酒的健康建议。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-17":{"costText":"多花一点钱买正品。","gainText":"不因为一件礼物丢了信誉。","gainTrimmed":false,"remark":"所谓「特供」「内供」商品多为假冒，本身就可能违法。","source":"《中华人民共和国商标法》关于假冒注册商标商品的规定；《中华人民共和国食品安全法》。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-18":{"costText":"记在心里。","gainText":"人情有来有往，又不显得刻意。","gainTrimmed":false,"remark":"对你有所求、你不想深交的人送的礼，见第 6 章，尽快两清更好。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-19":{"costText":"放弃「送个有纪念意义的东西」。","gainText":"不送出别人家里的「闲置」。","gainTrimmed":false,"remark":"关系很亲近、知道对方口味的，再考虑个性化的礼物。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-20":{"costText":"一张卡片或一条消息。","gainText":"心意不被「冒领」，也不让对方糊涂。","gainTrimmed":false,"remark":"托人转交现金的，最好改成直接转账，避免说不清。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-21":{"costText":"挑个合适的时机。","gainText":"不让收礼人在众人面前为难。","gainTrimmed":false,"remark":"私下送不等于偷偷送。需要偷偷送的礼，往往本身就不该送。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq07-22":{"costText":"写几行字。","gainText":"花不了多少钱，却很难被忘记。","gainTrimmed":false,"remark":"写给长辈、老师的卡片，语气庄重一点；写给朋友的可以轻松。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-1":{"costText":"一份礼金。","gainText":"随得不多不少，既不失礼也不吃亏。","gainTrimmed":false,"remark":"问行情时问同一层级的人，别拿领导、亲戚的标准套自己。","source":"经验共识，本书整理；各地行情差异很大，以当地为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-2":{"costText":"注意一下数字。","gainText":"数字上不犯忌讳。","gainTrimmed":false,"remark":"现在年轻人越来越不讲究，但给长辈家里随礼时，按老规矩更稳妥。","source":"民间习俗，各地差异较大，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-3":{"costText":"一支笔。","gainText":"主家记得你的心意，日后回礼不出错。","gainTrimmed":false,"remark":"白事的奠仪用白色或素色信封，写上「奠仪」和名字。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-4":{"costText":"一笔转账加一条消息。","gainText":"没到场，人情也到了。","gainTrimmed":false,"remark":"人不到时，礼金可以比到场时略少一点，各地习惯不同。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那天实在赶不回去，礼金先转给你，祝你们百年好合，回来一定补上喜酒！」","links":[],"evType":"经验共识"},"rq08-5":{"costText":"多出一些礼金。","gainText":"主家不为难，你也不显得占便宜。","gainTrimmed":false,"remark":"夫妻都和主家熟的，可以两人各随一份，也可以合随一份大一点的，看当地习惯。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「到时候我和爱人一起过去，没问题吧？」","links":[],"evType":"经验共识"},"rq08-6":{"costText":"一次庄重的出席。","gainText":"在别人最难的时候给出体面的支持。","gainTrimmed":false,"remark":"少数民族、宗教信仰不同的家庭有各自的仪轨，跟着主家的安排走。","source":"经验共识，本书整理；各地丧葬习俗差异见第 27 章。","sourceTrimmed":false,"tip":"「叔叔阿姨节哀，有什么要帮忙的随时叫我。」","links":[],"evType":"经验共识"},"rq08-7":{"costText":"一个红包或一份实用的礼。","gainText":"表达了祝福，没给人添乱。","gainTrimmed":false,"remark":"别对产妇的身材、母乳、喂养方式指指点点。","source":"世界卫生组织与国家卫健委关于新生儿护理、手卫生和预防感染的健康建议；看望礼节为经验共识。","sourceTrimmed":false,"tip":"「恭喜恭喜！孩子真可爱，你好好休息，我们就不多打扰了。」","links":[],"evType":"官方文件"},"rq08-8":{"costText":"一个红包。","gainText":"祝福送到，主家开心。","gainTrimmed":false,"remark":"金银首饰类礼物要真材实料，附上鉴定证书更好。","source":"经验共识，本书整理；金额看当地习惯。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-9":{"costText":"一个给孩子的红包。","gainText":"喜事不变成麻烦事。","gainTrimmed":false,"remark":"老师也不要参加家长付费的谢师宴，见第 7 章。","source":"中央八项规定及其实施细则；《中国共产党纪律处分条例》（2023 年修订）关于违规操办婚丧喜庆事宜、借机敛财的规定；各地纪委监委公开通报的典型问题。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-10":{"costText":"一份家用好物。","gainText":"礼物真能用上。","gainTrimmed":false,"remark":"去新房做客，进门先夸房子，别评价房价、户型的缺点。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「新家缺点啥不？我给你添一样。」","links":[],"evType":"经验共识"},"rq08-11":{"costText":"一个花篮或一份礼金。","gainText":"朋友创业时你在场，这份情他会记得。","gainTrimmed":false,"remark":"真有经营上的建议，私下找时间说。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-12":{"costText":"问一句话。","gainText":"随得合群，不尴尬。","gainTrimmed":false,"remark":"被要求「必须随礼」、随礼与考核挂钩的，属于不当摊派，可以婉拒或向上反映。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王姐，咱们部门这种情况一般大家随多少啊？」","links":[],"evType":"经验共识"},"rq08-13":{"costText":"随之前想清楚。","gainText":"不对份子钱抱不切实际的期待。","gainTrimmed":false,"remark":"附有明确条件的赠与、以欺诈手段骗取的「礼金」（比如假结婚骗份子钱），可以依法主张返还。","source":"《中华人民共和国民法典》第六百五十七条（赠与合同）、第六百五十八条（赠与人在财产权利转移之前可以撤销赠与）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-14":{"costText":"办得简朴一些。","gainText":"家里的喜事不变成仕途的坎。","gainTrimmed":false,"remark":"具体报告时限和规模要求各地各单位不同，办之前问一下单位纪检或组织部门。","source":"中央八项规定及其实施细则；《中国共产党纪律处分条例》（2023 年修订）关于违规操办婚丧喜庆事宜的规定；以所在单位的报告制度为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-15":{"costText":"承受一点「是不是小气」的担心。","gainText":"把钱用在值得的地方。","gainTrimmed":false,"remark":"对方以前随过你的，最好还是回一份，见第 6 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「恭喜恭喜，祝你们幸福！」","links":[],"evType":"经验共识"},"rq08-16":{"costText":"一份礼金。","gainText":"祝福送得体面。","gainTrimmed":false,"remark":"对方说明「不收礼金」的，就别硬塞，送一份小礼物表达心意。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-17":{"costText":"安排一个靠谱的人。","gainText":"不因为礼金账目闹出误会。","gainTrimmed":false,"remark":"礼单要妥善保存，这是日后回礼的依据。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-18":{"costText":"一晚上的消息。","gainText":"人情记在心里，也让对方知道你记得。","gainTrimmed":false,"remark":"白事之后也要答谢帮忙的人，很多地方有专门的答谢宴或回礼。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「李叔，谢谢您昨天专门赶过来，还帮着招呼客人，辛苦您了！」","links":[],"evType":"经验共识"},"rq08-19":{"costText":"多打几个电话。","gainText":"邀请显得真诚，不招人反感。","gainTrimmed":false,"remark":"被拉进这类群，可以只发祝福不随礼，见本节第 15 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq08-20":{"costText":"顶住「办得太寒酸」的议论。","gainText":"减轻双方的人情负担。","gainTrimmed":false,"remark":"长辈坚持要办的，可以商量在形式上从简、在心意上不减。","source":"民政部关于推进婚俗改革的指导意见；近年中央一号文件关于治理高额彩礼、大操大办等陈规陋习的要求；各地村规民约。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-1":{"costText":"赴约前问一句。","gainText":"不穿错、不说错、不带错人。","gainTrimmed":false,"remark":"对方没说可以带人，就不要临时带朋友、带家属。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-2":{"costText":"记住一个大致规则。","gainText":"坐对位置，场面就顺了。","gainTrimmed":false,"remark":"家宴里最重要的通常是长辈，让老人坐主位。","source":"商务礼仪通行做法，各地差异较大，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-3":{"costText":"在门口站一会儿。","gainText":"不因为一个座位显得不懂规矩。","gainTrimmed":false,"remark":"你是请客的主人时，要提前想好座位，客人一到就主动引导。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「您先坐，我坐哪都行。」","links":[],"evType":"经验共识"},"rq09-4":{"costText":"点菜前多问一句。","gainText":"客人吃得好，主人有面子。","gainTrimmed":false,"remark":"现在提倡光盘行动，量不要多到大量浪费。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「大家有没有什么不吃的？我先点几个，不够再加。」","links":[],"evType":"经验共识"},"rq09-5":{"costText":"放弃点一道想吃的大菜。","gainText":"给足主人面子，也不让自己显得挑剔。","gainTrimmed":false,"remark":"AA 制的聚餐不受这条限制，按自己口味点就好。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「那我点个清炒时蔬，其他您来安排。」","links":[],"evType":"经验共识"},"rq09-6":{"costText":"留意一下转盘。","gainText":"吃相得体，别人愿意和你同桌。","gainTrimmed":false,"remark":"用公筷公勺给别人夹菜，比用自己的筷子更卫生，也更受欢迎。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-7":{"costText":"找个借口离席几分钟。","gainText":"请客请得体面，客人也不必客套。","gainTrimmed":false,"remark":"晚辈、下属和长辈、领导吃饭，领导明确说「我来请」时，就别硬抢了，下次找机会回请。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-8":{"costText":"一顿饭的钱。","gainText":"饭局成为关系的纽带，而不是负担。","gainTrimmed":false,"remark":"领导请下属、长辈请晚辈，通常不要求等价回请，表达感谢即可。","source":"Gouldner, A. W. (1960). The norm of reciprocity. American Sociological Review, 25(2), 161–178.","sourceTrimmed":false,"tip":"「上次你请的，这次换我，下周找家好吃的？」","links":[],"evType":"经验共识"},"rq09-9":{"costText":"忍住刷手机。","gainText":"在场的人觉得被重视。","gainTrimmed":false,"remark":"饭局上拍照发朋友圈前，问一下同桌的人介不介意。","source":"Przybylski, A. K., & Weinstein, N. (2013). Can you connect with me now? How the presence of mobile communication technology influences face-to-face conversation quality. Journal of…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq09-10":{"costText":"管住几个话题。","gainText":"吃得开心，不惹是非。","gainTrimmed":false,"remark":"被别人拉进敏感话题，可以笑着转开：「这个我还真不懂，你们尝尝这道菜。」","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-11":{"costText":"多一点眼力见。","gainText":"一顿饭下来，大家都觉得你懂事、靠谱。","gainTrimmed":false,"remark":"别因为忙着照应而完全不吃，该吃的时候也要吃。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-12":{"costText":"一句话。","gainText":"走得体面，不留误会。","gainTrimmed":false,"remark":"主人敬酒、讲话的时候不要起身离开。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「不好意思，家里有点事我得先走，大家慢慢吃，改天我请。」","links":[],"evType":"经验共识"},"rq09-13":{"costText":"把谈判留到会议室。","gainText":"关系建立得稳，合作谈得顺。","gainTrimmed":false,"remark":"饭桌上的口头承诺很难作为依据，重要事项以书面合同为准，见第 22 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-14":{"costText":"控制场面。","gainText":"不让一个人的迟到拖垮整场。","gainTrimmed":false,"remark":"迟到入席后先向主人和大家道歉，别长篇解释原因。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「路上堵车，大概还要二十分钟，大家先吃，别等我。」","links":[],"evType":"经验共识"},"rq09-15":{"costText":"按标准安排。","gainText":"接待周到，也经得起检查。","gainTrimmed":false,"remark":"国有企业、事业单位也有各自的业务招待标准，以本单位规定为准。","source":"中共中央办公厅、国务院办公厅《党政机关国内公务接待管理规定》（2013）；中央八项规定及其实施细则。","sourceTrimmed":false,"tip":"","links":[],"evType":"官方文件"},"rq09-16":{"costText":"把话留到私下。","gainText":"饭局不变成「审判会」。","gainTrimmed":false,"remark":"同桌有人喝多了说过头话，别当场顶回去，等对方清醒了再说。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-17":{"costText":"多走几步。","gainText":"一顿饭从头到尾都让人舒服。","gainTrimmed":false,"remark":"喝了酒的客人坚持自己开车，要拦住，见第 10 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「到家了给我发个消息啊。」","links":[],"evType":"经验共识"},"rq09-18":{"costText":"开口问一句。","gainText":"既不浪费，也不失礼。","gainTrimmed":false,"remark":"主人点菜时按需点，本身就能减少剩菜。","source":"《中华人民共和国反食品浪费法》（2021）关于餐饮服务提供者提示消费者适量点餐、提供打包服务的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq09-19":{"costText":"一句解释。","gainText":"好意领了，身体也不受罪。","gainTrimmed":false,"remark":"你给别人夹菜前，先问对方吃不吃这个。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「谢谢阿姨，我对海鲜过敏，这个就不吃了，我多吃点别的。」","links":[],"evType":"经验共识"},"rq09-20":{"costText":"一条消息。","gainText":"主人有准备，场面不尴尬。","gainTrimmed":false,"remark":"商务饭局上带不相关的人，可能涉及商业信息泄露，更要谨慎。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「明天我能带个朋友一起吗？他也做这行，正好想认识一下大家。」","links":[],"evType":"经验共识"},"rq10-1":{"costText":"开场时一句说明。","gainText":"少被劝，场面也不僵。","gainTrimmed":false,"remark":"理由要真实，编的理由（比如假装吃药）被拆穿反而更尴尬。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「不好意思，我今天开车，以茶代酒敬大家。」","links":[],"evType":"经验共识"},"rq10-2":{"costText":"等一等，看一看。","gainText":"敬对了顺序，酒桌上就不会失礼。","gainTrimmed":false,"remark":"人多时，可以几个人一起去敬，节省时间，也减轻被敬者的负担。","source":"经验共识，本书整理；各地酒桌习俗差异很大。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq10-3":{"costText":"站起来走几步。","gainText":"敬得真诚，让人记得。","gainTrimmed":false,"remark":"「我干了，您随意」是常见的客气说法，但你自己喝不了就别说「我干了」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「张总，这次项目多亏您把关，我敬您一杯，您随意，我干了。」","links":[],"evType":"经验共识"},"rq10-4":{"costText":"放下「不喝就是不给面子」的想法。","gainText":"不因为一杯酒背上赔偿甚至更重的责任。","gainTrimmed":false,"remark":"作为组织者，安排人照看喝多的同事、联系家属、叫代驾，是实打实的保护。","source":"《中华人民共和国民法典》第一千一百六十五条（过错责任）；各地法院公开的劝酒致人死亡、受伤案件判决。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq10-5":{"costText":"代驾费或打车钱。","gainText":"保住驾照、工作和别人的安全。","gainTrimmed":false,"remark":"第二天早上酒精可能还没代谢完，前一晚喝得多的，早上也不要急着开车。","source":"《中华人民共和国道路交通安全法》第九十一条；《中华人民共和国刑法》第一百三十三条之一（危险驾驶罪）；国家标准 GB 19522《车辆驾驶人员血液、呼气酒精含量阈值与检验》。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq10-6":{"costText":"拒一杯酒。","gainText":"避免一场可能致命的反应。","gainTrimmed":false,"remark":"已经喝了出现上述症状，立即停止并拨打 120。","source":"头孢哌酮、甲硝唑等药品说明书中关于服药期间及停药后禁止饮酒的警示。","sourceTrimmed":false,"tip":"「我这两天在吃头孢，喝一口都可能出事，真不能喝。」","links":[],"evType":"经验共识"},"rq10-7":{"costText":"散场后多耽误一会儿。","gainText":"可能救下一条命，也免去同饮者的责任纠纷。","gainTrimmed":false,"remark":"不要给醉酒的人灌咖啡、浓茶或催吐药，也不要让他泡热水澡。","source":"中国红十字会等急救培训中关于昏迷者「复原卧位」的通行做法；同饮者照看义务见本节第 4 条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq10-8":{"costText":"改掉一个说法。","gainText":"不被说法误导，喝之前心里有数。","gainTrimmed":false,"remark":"空腹喝酒吸收更快，喝之前先吃点东西。","source":"Köchling, J., et al. (2019). Grape or grain but never the twain? A randomized controlled multiarm matched-triad crossover trial of beer and wine. The American Journal of Clinical N…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq10-9":{"costText":"少几杯。","gainText":"减少酒精对身体的长期伤害。","gainTrimmed":false,"remark":"已经有酒精依赖、戒断时出现手抖、出汗、幻觉的，不要自己硬戒，要去医院。","source":"World Health Organization Regional Office for Europe (2023). No level of alcohol consumption is safe for our health. 发表于 The Lancet Public Health 的相关声明。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq10-10":{"costText":"一点应变。","gainText":"既保住了面子，也保住了身体。","gainTrimmed":false,"remark":"任何时候都可以说「不」，你的身体比别人的面子重要。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我酒量真不行，这杯我抿一口，心意到了，您见谅。」","links":[],"evType":"经验共识"},"rq10-11":{"costText":"顶住场面上的压力。","gainText":"保护自己，也让骚扰者付出代价。","gainTrimmed":false,"remark":"被下药、意识不清时，同伴要立刻带离并报警，保留饮品，见第 28 章。","source":"《中华人民共和国民法典》第一千零一十条（性骚扰的民事责任与单位预防处置义务）；《中华人民共和国妇女权益保障法》（2022 年修订）第二十三条、第二十五条。","sourceTrimmed":false,"tip":"「请您把手拿开，我不喜欢这样。」","links":[],"evType":"法条"},"rq10-12":{"costText":"忍到第二天。","gainText":"少一些醒后追悔莫及的事。","gainTrimmed":false,"remark":"别人酒后的承诺，也别当真催着兑现，清醒后再正式确认。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq10-13":{"costText":"主动一点。","gainText":"不喝酒也不掉队。","gainTrimmed":false,"remark":"别人以茶代酒敬你时，不要追问「为什么不喝」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我以茶代酒，敬王总一杯，祝您身体健康。」","links":[],"evType":"经验共识"},"rq10-14":{"costText":"一点幽默感。","gainText":"不伤和气地守住底线。","gainTrimmed":false,"remark":"对方仍然不依不饶，就直接说明身体原因，然后坐下，不必再陪他纠缠。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「咱俩的感情哪是一杯酒能装下的？这杯我抿一口，剩下的留着下次。」","links":[],"evType":"经验共识"},"rq10-15":{"costText":"站起来。","gainText":"态度到位，身体也不受罪。","gainTrimmed":false,"remark":"领导明确要求「必须喝完」，你可以说明身体原因，事后不必为此焦虑。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「谢谢领导关心，我一定好好干。」","links":[],"evType":"经验共识"},"rq10-16":{"costText":"少说几句。","gainText":"敬酒受欢迎，不让人有压力。","gainTrimmed":false,"remark":"真有事相求，另找时间正式说。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq10-17":{"costText":"选正规渠道。","gainText":"喝得放心，场面体面。","gainTrimmed":false,"remark":"公务接待不得提供高档酒水，见第 9 章。","source":"《中华人民共和国食品安全法》；国家市场监管部门关于「特供」「专供」标识的禁止性规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"官方文件"},"rq10-18":{"costText":"换一种说法。","gainText":"对方更容易听进去。","gainTrimmed":false,"remark":"出现酒精依赖的迹象（早上要喝酒才能稳住、戒酒后手抖出汗），要陪他去医院精神心理科或成瘾医学科。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我是真担心你的身体，下次聚会我帮你挡，咱们少喝点。」","links":[],"evType":"经验共识"},"rq11-1":{"costText":"一次提前的商量。","gainText":"少吵一架，两边父母都觉得被尊重。","gainTrimmed":false,"remark":"一方父母身体不好或独居的，可以优先照顾，另一方要体谅。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「今年咱们在你家过三十，初二去我家，明年反过来，你看行吗？」","links":[],"evType":"经验共识"},"rq11-2":{"costText":"几天的走动。","gainText":"长辈觉得被惦记。","gainTrimmed":false,"remark":"有的地方忌讳初一去别人家拜年，或忌讳刚办过丧事的人家去拜年，提前问清楚。","source":"经验共识，本书整理；各地习俗差异见第 27 章。","sourceTrimmed":false,"tip":"「二姨，过年好！今年没能回去看您，给您拜个年，身体还好吧？」","links":[],"evType":"经验共识"},"rq11-3":{"costText":"一笔红包钱。","gainText":"亲戚之间不因为红包大小起疙瘩。","gainTrimmed":false,"remark":"已经工作的晚辈还给不给压岁钱，各家不同，跟着家里的习惯走。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-4":{"costText":"一个量力而行的红包。","gainText":"父母觉得欣慰，你也尽了孝心。","gainTrimmed":false,"remark":"手头紧的年份，不必为了面子硬撑，一份用心的小礼物同样珍贵。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「爸妈，这是我的一点心意，你们拿着买点喜欢的。」","links":[],"evType":"经验共识"},"rq11-5":{"costText":"提前想好说法。","gainText":"保护隐私，也不破坏过年的气氛。","gainTrimmed":false,"remark":"同一个亲戚反复追问、说难听话，可以平静地说「这是我自己的事，我有安排」，然后离开这个话题。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「在努力了，有好消息第一个告诉您！您家小明今年考得怎么样？」","links":[],"evType":"经验共识"},"rq11-6":{"costText":"咽下一口气。","gainText":"过年不吵架，也不憋屈太久。","gainTrimmed":false,"remark":"长期被比较、贬低造成心理负担的，可以减少和这类亲戚的接触。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-7":{"costText":"一个下午的帮忙。","gainText":"家里人不那么累，你也落个好人缘。","gainTrimmed":false,"remark":"家务长期压在某一个人身上，过年正好是重新分工的时候。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「阿姨，我来洗碗，您歇会儿。」","links":[],"evType":"经验共识"},"rq11-8":{"costText":"控制输赢的额度。","gainText":"娱乐归娱乐，不惹麻烦。","gainTrimmed":false,"remark":"「少量」没有全国统一的数额，各地公安有不同把握，宁可小一点。","source":"公安部《关于办理赌博违法案件适用法律若干问题的通知》（2005）；《中华人民共和国刑法》第三百零三条（赌博罪、开设赌场罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq11-9":{"costText":"一个晚上逐个发消息。","gainText":"祝福被看见，关系被记住。","gainTrimmed":false,"remark":"收到群发的祝福，回一句简单的「新年快乐」就好，不必较真。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「刘老师，新年好！今年您带我们做的那个课题我收获特别大，祝您新年身体健康、万事顺意。」","links":[],"evType":"经验共识"},"rq11-10":{"costText":"一份年货和一通长一点的视频。","gainText":"人不在，心意在。","gainTrimmed":false,"remark":"父母年纪大、身体不好的，尽量想办法回去。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「爸妈，今年单位值班回不去了，年货给你们寄了，三十晚上我们视频一起吃年夜饭。」","links":[],"evType":"经验共识"},"rq11-11":{"costText":"一路上盯着孩子。","gainText":"孩子懂礼貌，大人也有面子。","gainTrimmed":false,"remark":"孩子收到的红包，回家后和孩子一起记下来是谁给的，方便日后回礼。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-12":{"costText":"先忍几天。","gainText":"过年就是过年，不变成「审判日」。","gainTrimmed":false,"remark":"如果有家庭成员动手、威胁，不必忍到节后，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-13":{"costText":"查一下当地规定。","gainText":"热闹不变成事故和罚单。","gainTrimmed":false,"remark":"燃放后的纸屑残骸，自己清理干净，别留给邻居和保洁。","source":"《烟花爆竹安全管理条例》；各地烟花爆竹燃放管理规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-14":{"costText":"一点小钱。","gainText":"热闹归热闹，不越界。","gainTrimmed":false,"remark":"领导在部门群发红包活跃气氛是常见做法，下属跟着抢一点没问题。","source":"中央八项规定及其实施细则；《中国共产党纪律处分条例》（2023 年修订）关于收受礼金、消费卡等的规定（电子红包同样适用）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-15":{"costText":"一份年货。","gainText":"长辈觉得你懂礼数、有心。","gainTrimmed":false,"remark":"礼物的选法见第 7 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq11-16":{"costText":"临走前的一点时间。","gainText":"父母安心，你也走得踏实。","gainTrimmed":false,"remark":"回到工作地后，给父母报个平安。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「妈，我五一再回来看你们，有啥事随时给我打电话。」","links":[],"evType":"经验共识"},"rq11-17":{"costText":"先拖一拖。","gainText":"不在情面最重的时候仓促答应。","gainTrimmed":false,"remark":"说了节后回话，就要真的回，哪怕是拒绝。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事我得跟家里商量一下，过完年我给你回话。」","links":[],"evType":"经验共识"},"rq11-18":{"costText":"一句问候或一点心意。","gainText":"值班的人觉得付出被看见。","gainTrimmed":false,"remark":"春节法定节假日加班，单位应依法支付加班工资，不能只用调休代替。","source":"《全国年节及纪念日放假办法》；《中华人民共和国劳动法》第四十四条（法定休假日安排工作的，支付不低于工资的百分之三百的工资报酬）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq12-1":{"costText":"问一句「用在哪」的不好意思。","gainText":"钱帮在真正需要的地方。","gainTrimmed":false,"remark":"对方不愿说用途、说法前后矛盾的，要更加谨慎。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「借钱没问题，你跟我说说是遇到啥事了，我看看怎么帮最合适。」","links":[],"evType":"经验共识"},"rq12-2":{"costText":"控制借出的额度。","gainText":"即使要不回来，也不至于伤筋动骨。","gainTrimmed":false,"remark":"夫妻共同财产借给自家亲戚，最好先和伴侣商量，见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-3":{"costText":"开口要借条的尴尬。","gainText":"万一要走法律途径，有据可查。","gainTrimmed":false,"remark":"借条只写了金额、没有转账记录的大额现金借款，法院会审查是否真实交付，转账更稳妥。","source":"《中华人民共和国民法典》第六百六十八条、第六百七十九条（自然人之间的借款合同自贷款人提供借款时成立）；最高人民法院《关于审理民间借贷案件适用法律若干问题的规定》（2020 年修正）。","sourceTrimmed":false,"tip":"「咱们写个条，不是信不过你，是怕以后家里人说不清。」","links":[],"evType":"经验共识"},"rq12-4":{"costText":"在借条里写清楚。","gainText":"不因为利息问题再起纠纷。","gainTrimmed":false,"remark":"以借款为名、实为高利放贷牟利的，可能构成违法犯罪。","source":"《中华人民共和国民法典》第六百八十条；最高人民法院《关于审理民间借贷案件适用法律若干问题的规定》（2020 年修正）第二十五条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq12-5":{"costText":"拒绝一个很难拒绝的请求。","gainText":"不为别人的债务背锅。","gainTrimmed":false,"remark":"合同里没约定保证方式或约定不明确的，按一般保证处理，保证人有先诉抗辩权；但很多贷款合同会明确写连带责任，签之前看清楚。","source":"《中华人民共和国民法典》第六百八十一条、第六百八十六条至第六百八十八条（一般保证与连带责任保证）。","sourceTrimmed":false,"tip":"「借钱我可以考虑借一部分，担保这个我家里定过规矩，谁都不签。」","links":[],"evType":"经验共识"},"rq12-6":{"costText":"开口催钱的难受。","gainText":"不因为不好意思催而让钱真的要不回来。","gainTrimmed":false,"remark":"催款时只说事实，不辱骂、不威胁、不去对方单位闹，否则可能反而违法。","source":"《中华人民共和国民法典》第一百八十八条（三年诉讼时效）、第一百九十五条（权利人提出履行请求，诉讼时效中断）。","sourceTrimmed":false,"tip":"「之前借你的那笔钱到期了，你看什么时候方便还？我这边也有用处。」","links":[],"evType":"经验共识"},"rq12-7":{"costText":"说清楚你能做的范围。","gainText":"帮了忙，不背结果的锅。","gainTrimmed":false,"remark":"托人违规安排进编制、走后门的，见第 29 章，这种忙不能帮。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我们公司在招人，我可以帮他内推，面试得靠他自己，我也左右不了结果。」","links":[],"evType":"经验共识"},"rq12-8":{"costText":"一次提前的沟通。","gainText":"帮了亲戚，也保住自己家的生活。","gainTrimmed":false,"remark":"已婚的，借住这件事要先和伴侣商量好，见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「来住没问题，就是家里地方小，住个一周左右，之后我帮你在附近找个合适的地方。」","links":[],"evType":"经验共识"},"rq12-9":{"costText":"请人起草一份协议。","gainText":"生意做不好，至少亲戚还能做。","gainTrimmed":false,"remark":"注册公司的，按《公司法》在章程和股东协议里约定，见第 22 章。","source":"《中华人民共和国民法典》第九百六十七条至第九百七十八条（合伙合同）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-10":{"costText":"多想一层。","gainText":"不被亲情牵着掉进坑里。","gainTrimmed":false,"remark":"判断传销和非法集资的特征，见第 30 章。","source":"《中华人民共和国刑法》第二百二十四条之一（组织、领导传销活动罪）、第一百七十六条（非法吸收公众存款罪）；《防范和处置非法集资条例》（2021）。","sourceTrimmed":false,"tip":"「我最近手头紧，不考虑这些，你自己也要多留个心眼。」","links":[],"evType":"经验共识"},"rq12-11":{"costText":"放低一点姿态。","gainText":"亲戚关系有机会修复，不必闹上法庭。","gainTrimmed":false,"remark":"涉及大额财产的，调解达成的协议可以申请法院司法确认，执行更有保障。","source":"《中华人民共和国人民调解法》（2010）关于人民调解委员会调解民间纠纷、调解协议效力的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-12":{"costText":"了解规则，必要时请律师。","gainText":"分得清楚，少一场亲人间的官司。","gainTrimmed":false,"remark":"父母在世时可以早做安排，比如立一份形式合法的遗嘱，见第 13 章。","source":"《中华人民共和国民法典》第一千一百二十七条、第一千一百三十条、第一千一百三十四条至第一千一百三十九条、第一千一百四十二条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-13":{"costText":"一次全家人的商量。","gainText":"父母有人照顾，兄弟姐妹不互相埋怨。","gainTrimmed":false,"remark":"分工协议可以写下来，大家签字，有变化再调整。","source":"《中华人民共和国民法典》第一千零六十七条；《中华人民共和国老年人权益保障法》第十四条、第十九条（赡养人不得以放弃继承权或者其他理由拒绝履行赡养义务）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq12-14":{"costText":"一笔生活费和日常的感谢。","gainText":"帮忙的人不寒心，孩子也被照顾得好。","gainTrimmed":false,"remark":"育儿观念冲突的处理，见第 13 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「妈，这是孩子这个月的开销，您带孩子太辛苦了，周末我来带，您歇两天。」","links":[],"evType":"经验共识"},"rq12-15":{"costText":"开口谈钱。","gainText":"人情归人情，钱是钱。","gainTrimmed":false,"remark":"多次大量代购用于销售的，可能构成走私，不要帮。","source":"《中华人民共和国海关法》；海关总署关于进境居民旅客携带个人自用物品免税限额的规定。","sourceTrimmed":false,"tip":"「这个包大概一万二，你先转我，我到了就去买，小票也给你。」","links":[],"evType":"经验共识"},"rq12-16":{"costText":"下一次直接拒绝。","gainText":"不再吃亏，也不让整个家族为难。","gainTrimmed":false,"remark":"欠款数额大、对方有能力还而不还的，可以按第 28 章的方法依法追讨。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-17":{"costText":"说话低调一点。","gainText":"少一些麻烦，多一些清净。","gainTrimmed":false,"remark":"长辈真心为你高兴时，分享一点好消息无妨。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq12-18":{"costText":"承受一些议论。","gainText":"亲戚关系不再是压力源。","gainTrimmed":false,"remark":"赡养父母等法定义务，不因为和其他亲戚疏远而改变。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-1":{"costText":"多一点耐心。","gainText":"一次唠叨不变成一场争吵。","gainTrimmed":false,"remark":"父母的担心变成控制，比如逼你辞职、逼你分手，回到本节第 3 条和第 11 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我知道您是担心我身体，我最近都尽量十二点前睡，周末也去游泳了。」","links":[],"evType":"经验共识"},"rq13-2":{"costText":"每周半小时。","gainText":"父母安心，你也知道家里的情况。","gainTrimmed":false,"remark":"父母年纪大了不会用视频的，教他们一次，或者给他们设置成一键拨打。","source":"《中华人民共和国老年人权益保障法》第十八条（与老年人分开居住的家庭成员，应当经常看望或者问候老年人）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq13-3":{"costText":"一次可能不愉快的谈话。","gainText":"父母觉得被尊重，你也不被他们的焦虑左右。","gainTrimmed":false,"remark":"「先斩后奏」会让父母觉得被排除在外，除非你已预料到对方会强烈干涉。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事我想了挺久，跟您说说我的打算。您有啥担心的，我听听。」","links":[],"evType":"经验共识"},"rq13-4":{"costText":"一次推心置腹的谈话。","gainText":"减轻父母的压力，也减轻你的压力。","gainTrimmed":false,"remark":"父母安排的相亲，不想去可以婉拒，去了就礼貌对待对方。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我不是不想结，是想找个合适的。亲戚问起来，您就说我在忙工作、在留意，别的我来应付。」","links":[],"evType":"经验共识"},"rq13-5":{"costText":"反复解释的耐心。","gainText":"保住父母的钱，更保住他们的健康。","gainTrimmed":false,"remark":"已经被骗交了大额钱款的，保留票据和宣传材料，向 12315 投诉或报警。","source":"国家市场监督管理总局《保健食品标注警示用语指南》（2019），要求标注「保健食品不是药物，不能代替药物治疗疾病」。","sourceTrimmed":false,"tip":"「妈，您看这上面写着不能代替药物，您的降压药千万别停。这东西要真那么神，医院早就用了。」","links":[],"evType":"经验共识"},"rq13-6":{"costText":"一次上门设置。","gainText":"在骗子和父母之间加一道闸。","gainTrimmed":false,"remark":"常见骗局的识别方法见第 30 章；接到可疑电话可拨打 96110 咨询。","source":"《中华人民共和国反电信网络诈骗法》（2022）；全国打击整治养老诈骗专项行动（2022）公开的典型骗局类型。","sourceTrimmed":false,"tip":"「爸，以后不管谁打电话让您转钱，哪怕说是我，您都先挂了，再打我这个号码确认。」","links":[],"evType":"经验共识"},"rq13-7":{"costText":"几个周末的耐心。","gainText":"父母在数字时代不被落下，也少一些被骗的风险。","gainTrimmed":false,"remark":"手机字体调大、常用功能放在首页，能帮老人省很多事。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-8":{"costText":"多花一点心思。","gainText":"钱真正变成了父母的生活质量。","gainTrimmed":false,"remark":"老人跌倒是常见的伤害原因，家里的防滑和照明值得优先投入。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-9":{"costText":"每年一次的体检安排。","gainText":"早发现、早治疗，少一些突然的坏消息。","gainTrimmed":false,"remark":"父母讳疾忌医时，可以说「我单位给家属的体检名额」，让他们更容易接受。","source":"国家基本公共卫生服务规范中关于 65 岁及以上老年人每年一次健康管理服务的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-10":{"costText":"一次耐心的倾听。","gainText":"父母放心一些，你也不必在愧疚里做选择。","gainTrimmed":false,"remark":"父母年迈需要照顾时，可以重新评估，回老家也不等于失败。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我明白你们是想让我稳当点，我也想过，在这边发展机会多，我每年都会多回来几趟。」","links":[],"evType":"经验共识"},"rq13-11":{"costText":"可能让父母觉得被「疏远」。","gainText":"既保持亲近，又不被过度干涉。","gainTrimmed":false,"remark":"婚后和双方父母的边界，见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「妈，我知道您是关心我，工资我自己管，有需要我肯定跟您商量。」","links":[],"evType":"经验共识"},"rq13-12":{"costText":"一次难开口的谈话。","gainText":"减少积压的委屈，也给父母一个调整的机会。","gainTrimmed":false,"remark":"涉及遗产分配不公的，见第 12 章；父母有权处分自己的财产。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-13":{"costText":"一次「不吉利」的谈话。","gainText":"真到那一天，全家不至于慌乱和争吵。","gainTrimmed":false,"remark":"意定监护协议、遗嘱可以到公证机构办理，更不容易引起争议。","source":"《中华人民共和国民法典》第三十三条（意定监护）、第一千一百三十四条至第一千一百三十九条（遗嘱形式）。","sourceTrimmed":false,"tip":"「爸，咱们把这些事提前理一理，不是咒您，是怕万一哪天我们手忙脚乱。」","links":[],"evType":"法条"},"rq13-14":{"costText":"放下「家散了」「不体面」的念头。","gainText":"父母晚年不孤单，家里也少一场冲突。","gainTrimmed":false,"remark":"子女的赡养义务不因父母再婚而消除。","source":"《中华人民共和国老年人权益保障法》第二十一条；《中华人民共和国民法典》第一千零六十五条（夫妻财产约定）。","sourceTrimmed":false,"tip":"「您开心最重要。财产上咱们按规矩做个约定，对谁都好。」","links":[],"evType":"法条"},"rq13-15":{"costText":"分清哪些必须坚持。","gainText":"孩子的关键问题有保障，老人也不觉得被全盘否定。","gainTrimmed":false,"remark":"老人带孩子很辛苦，提意见前先表达感谢。","source":"经验共识，本书整理；用药和护理问题以医生意见为准。","sourceTrimmed":false,"tip":"「妈，医生说孩子发烧不能捂汗，咱们按医生说的来。其他的您看着办就行。」","links":[],"evType":"经验共识"},"rq13-16":{"costText":"前几周的陪伴和引导。","gainText":"父母在城里过得开心，你也少一些愧疚。","gainTrimmed":false,"remark":"医保异地就医要提前备案，见当地医保部门的规定。","source":"Holt-Lunstad, J., Smith, T. B., & Layton, J. B. (2010). Social relationships and mortality risk: A meta-analytic review. PLoS Medicine, 7(7), e1000316.（社会关系薄弱与死亡风险升高相关，…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq13-17":{"costText":"把话留到没人的时候。","gainText":"父母更愿意接受，你们的关系也不受伤。","gainTrimmed":false,"remark":"被骗的老人常常自责，别再说「我早就告诉过你」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-18":{"costText":"克服一点不好意思。","gainText":"不留「来不及说」的遗憾。","gainTrimmed":false,"remark":"当面说不出口的，可以写在生日卡片或一封信里。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq13-19":{"costText":"可能面对「不孝」的指责。","gainText":"先让自己好起来，再决定怎样和父母相处。","gainTrimmed":false,"remark":"疏远不免除法定的赡养义务，父母缺乏劳动能力或生活困难时，仍需依法给付赡养费。","source":"Felitti, V. J., et al. (1998). Relationship of childhood abuse and household dysfunction to many of the leading causes of death in adults: The Adverse Childhood Experiences (ACE) S…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq13-20":{"costText":"时间。","gainText":"父母晚年有温度，你也少一些后悔。","gainTrimmed":false,"remark":"父母出现记性明显变差、迷路、性格突变的，带他们去医院记忆门诊排查认知障碍。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-1":{"costText":"多观察一段时间。","gainText":"在投入更多之前，看清一个人。","gainTrimmed":false,"remark":"对你和对别人反差极大、在你面前完美但对外人刻薄的，要格外留心。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-2":{"costText":"一份见面礼和一天的表现。","gainText":"留下一个靠谱、懂事的第一印象。","gainTrimmed":false,"remark":"被问到工作、收入、家庭情况，如实回答，别夸大也别过分谦虚。","source":"经验共识，本书整理；各地见家长的习俗差异见第 27 章。","sourceTrimmed":false,"tip":"「叔叔阿姨好，第一次来，给您二老带了点茶叶，听说叔叔爱喝茶。」","links":[],"evType":"经验共识"},"rq14-3":{"costText":"一次或几次可能尴尬的谈话。","gainText":"婚还没结，两家先建立了信任。","gainTrimmed":false,"remark":"谈彩礼时，把「这笔钱以后怎么用」也一起说清楚。","source":"《中华人民共和国民法典》第一千零四十二条（禁止借婚姻索取财物）；近年中央一号文件关于治理高额彩礼的要求。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-4":{"costText":"了解规则。","gainText":"知道彩礼不是「给了就是对方的」，也不是「分手就能全要回来」。","gainTrimmed":false,"remark":"给付彩礼最好走银行转账并备注「彩礼」，保留双方协商的聊天记录。","source":"最高人民法院《关于审理涉彩礼纠纷案件适用法律若干问题的规定》（2024 年 2 月 1 日起施行）第五条、第六条；最高人民法院《关于适用〈中华人民共和国民法典〉婚姻家庭编的解释（一）》第五条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq14-5":{"costText":"分清钱的性质。","gainText":"花钱时心里有数，分手时少一些纠纷。","gainTrimmed":false,"remark":"对方以恋爱为名反复要钱、从未打算结婚的，可能涉嫌诈骗，见第 30 章。","source":"最高人民法院《关于审理涉彩礼纠纷案件适用法律若干问题的规定》第三条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq14-6":{"costText":"开口谈钱的尴尬。","gainText":"不在婚后才发现一笔「意外的债」。","gainTrimmed":false,"remark":"征信报告可在中国人民银行征信中心网站、手机银行等渠道查询。","source":"《中华人民共和国民法典》第一千零六十四条（夫妻共同债务）；《征信业管理条例》第十七条（个人每年两次免费获取本人信用报告）。","sourceTrimmed":false,"tip":"「结婚前咱们把各自的账摊开说说吧，有房贷车贷都没事，就怕有不知道的。」","links":[],"evType":"法条"},"rq14-7":{"costText":"可能请律师咨询一次。","gainText":"真走到离婚那一步，少一场没完没了的官司。","gainTrimmed":false,"remark":"具体情况差别很大，涉及大额房产的，结婚前咨询一次律师很值得。","source":"《中华人民共和国民法典》第一千零六十二条、第一千零六十三条、第一千零六十五条；最高人民法院婚姻家庭编司法解释（一）第二十九条及婚姻家庭编司法解释（二）（2025 年施行）关于父母出资购房的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq14-8":{"costText":"查一下官方说明。","gainText":"少跑冤枉路。","gainTrimmed":false,"remark":"只办酒席不领证，在法律上不是夫妻，财产和孩子的权益都缺乏保障。","source":"《婚姻登记条例》（2025 年修订）；各地民政部门婚姻登记办事指南。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-9":{"costText":"一次检查和一次坦白。","gainText":"对彼此负责，婚姻建立在真实的基础上。","gainTrimmed":false,"remark":"哪些属于「重大疾病」，法律没有逐一列举，拿不准的可以咨询医生和律师。","source":"《中华人民共和国民法典》第一千零五十三条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-10":{"costText":"放弃一部分「别人都有」的环节。","gainText":"婚礼体面，婚后生活不被债务压垮。","gainTrimmed":false,"remark":"婚礼的礼金归谁，各地习惯不同，两家提前约定可以避免误会。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-11":{"costText":"提前问清流程。","gainText":"婚礼上的长辈都觉得被尊重。","gainTrimmed":false,"remark":"改口费的金额，两家可以提前私下沟通，避免当众尴尬。","source":"经验共识，本书整理；各地婚俗差异见第 27 章。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-12":{"costText":"拒绝「你不信任我」的指责。","gainText":"不人财两空。","gainTrimmed":false,"remark":"杀猪盘的识别和被骗后的止损方法，见第 30 章。","source":"《中华人民共和国反电信网络诈骗法》（2022）；公安机关公开发布的婚恋交友类诈骗典型案例。","sourceTrimmed":false,"tip":"「钱的事我们都不碰，等我们稳定了再一起规划。」","links":[],"evType":"经验共识"},"rq14-13":{"costText":"可能面对一次争吵或分手。","gainText":"在陷得更深之前看清楚。","gainTrimmed":false,"remark":"识别 PUA、煤气灯效应等操控手法，见第 30 章。","source":"Stark, E. (2007). Coercive Control: How Men Entrap Women in Personal Life. Oxford University Press.（「强制控制」概念：通过孤立、监控、贬低剥夺对方的自主。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-14":{"costText":"结束一段关系的痛苦。","gainText":"保住自己的安全。","gainTrimmed":false,"remark":"保留伤情照片、就医记录、报警回执、聊天记录，见第 28 章。","source":"《中华人民共和国反家庭暴力法》第十六条（告诫书）、第二十三条（人身安全保护令）、第三十七条（家庭成员以外共同生活的人参照适用）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq14-15":{"costText":"一次坦诚的结束。","gainText":"好聚好散，不留后患。","gainTrimmed":false,"remark":"被前任威胁曝光私密照片的，保留证据并立即报警。","source":"《中华人民共和国民法典》第一千零三十二条、第一千零三十三条（隐私权）；《中华人民共和国治安管理处罚法》关于散布他人隐私的规定；《中华人民共和国刑法》关于侮辱罪、传播淫秽物品罪的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-16":{"costText":"一顿饭或一杯咖啡。","gainText":"给对方也给介绍人留面子。","gainTrimmed":false,"remark":"谁买单各地习惯不同，可以主动提出 AA 或下次你请。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「今天聊得挺开心的，不过我感觉我们更适合做朋友，祝你早点遇到合适的人。」","links":[],"evType":"经验共识"},"rq14-17":{"costText":"站在伴侣这边说话的压力。","gainText":"矛盾不扩大成两家人的对立。","gainTrimmed":false,"remark":"婚后同样适用，见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对自己父母）「这是我们俩商量好的，您要是有意见跟我说，别去为难她。」","links":[],"evType":"经验共识"},"rq14-18":{"costText":"在转账备注里多写几个字。","gainText":"感情归感情，钱的事说得清。","gainTrimmed":false,"remark":"同居期间共同购买的财产，按出资和约定处理，最好也留凭证。","source":"《中华人民共和国民法典》第六百五十七条（赠与合同）、第六百六十七条（借款合同）；最高人民法院关于民间借贷案件的司法解释。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-19":{"costText":"开口提议的勇气。","gainText":"感情里少一个隐患。","gainTrimmed":false,"remark":"约定内容复杂的，可以请律师起草或到公证机构公证。","source":"《中华人民共和国民法典》第一千零六十五条（夫妻财产约定应当采用书面形式）。","sourceTrimmed":false,"tip":"「我们把各自的东西写清楚，以后不管怎样，谁都不用担心被误会。」","links":[],"evType":"经验共识"},"rq14-20":{"costText":"车票钱和规划。","gainText":"距离不至于把关系耗尽。","gainTrimmed":false,"remark":"长期没有结束异地的计划、一方一再推迟的，要认真谈谈两个人是否还有共同的未来。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-21":{"costText":"足够的耐心。","gainText":"孩子有安全感，新家庭更稳。","gainTrimmed":false,"remark":"再婚前对各自的子女抚养、财产安排做好约定。","source":"《中华人民共和国民法典》第一千零七十二条（继父母与继子女间的权利义务）、第一千零八十六条（不直接抚养的父母一方有探望子女的权利）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq14-22":{"costText":"承受来自家庭和社会的压力。","gainText":"做一个自己愿意承担后果的决定。","gainTrimmed":false,"remark":"被家人逼婚、包办婚姻的，可以寻求妇联（12338）和法律援助（12348）的帮助。","source":"《中华人民共和国民法典》第一千零四十一条、第一千零四十六条（婚姻自由，结婚应当男女双方完全自愿，禁止任何一方对另一方加以强迫，禁止任何组织或者个人加以干涉）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-1":{"costText":"在父母和伴侣之间做选择的痛苦。","gainText":"小家庭稳住了，其他问题才好解决。","gainTrimmed":false,"remark":"站在一起不等于不孝顺，而是和父母沟通时，你说「我们决定」，而不是「她不同意」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-2":{"costText":"自己出面说难听的话。","gainText":"伴侣不被夹在中间，婆媳、翁婿关系也不至于撕破。","gainTrimmed":false,"remark":"沟通时先表达感谢和理解，再说边界。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（丈夫对母亲）「妈，孩子怎么带我们俩商量过了，您别跟她说了，有意见冲我来。」","links":[],"evType":"经验共识"},"rq15-3":{"costText":"可能多一份房租或房贷。","gainText":"亲近而不拥挤，少很多因小事引发的矛盾。","gainTrimmed":false,"remark":"老人身体不好需要照顾的，同住是必要的，那就更要提前说好规矩。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-4":{"costText":"放手一部分控制权。","gainText":"老人愿意帮，孩子也被照顾好。","gainTrimmed":false,"remark":"老人带孩子也需要休息日，周末尽量自己带。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-5":{"costText":"一次「谈钱」的谈话。","gainText":"少一些因钱产生的猜疑。","gainTrimmed":false,"remark":"一方隐藏、转移、挥霍共同财产的，离婚时可以少分或不分，见本节第 18 条。","source":"《中华人民共和国民法典》第一千零六十二条（夫妻对共同财产有平等的处理权）、第一千零六十五条（夫妻财产约定）。","sourceTrimmed":false,"tip":"「咱们定个规矩，超过五千的花销都提前说一声，好吗？」","links":[],"evType":"经验共识"},"rq15-6":{"costText":"一点公平心。","gainText":"不让孝心变成夫妻矛盾。","gainTrimmed":false,"remark":"双方父母经济条件差别大的，「平衡」可以按需要而不是按金额。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-7":{"costText":"把委屈留在小家庭里消化。","gainText":"伴侣和你父母的关系不被你的情绪破坏。","gainTrimmed":false,"remark":"遭受家暴、严重伤害的，一定要告诉家人并寻求帮助，不在此列。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-8":{"costText":"把火压到关上门以后。","gainText":"吵完还能和好，孩子不被波及。","gainTrimmed":false,"remark":"情绪太激动时，约定先暂停二十分钟，冷静后再谈。","source":"Gottman, J. M.（约翰·戈特曼）关于婚姻冲突的研究：批评、蔑视、防御和冷战四种互动方式是婚姻破裂的强预测因素。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-9":{"costText":"每天的时间。","gainText":"家里的活有人干，心里的委屈少一些。","gainTrimmed":false,"remark":"全职在家照顾家庭的一方，付出同样是家庭的贡献。","source":"《中华人民共和国民法典》第一千零五十五条（夫妻在婚姻家庭中地位平等）、第一千零八十八条（一方因抚育子女、照料老人等负担较多义务的，离婚时有权请求补偿）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-10":{"costText":"顶住长辈的催促。","gainText":"重大决定由真正承担后果的人来做。","gainTrimmed":false,"remark":"夫妻对生育意见长期严重不一致的，需要认真沟通，必要时寻求婚姻咨询。","source":"《中华人民共和国妇女权益保障法》（2022 年修订）关于妇女享有生育自由的规定；《中华人民共和国人口与计划生育法》第十七条。","sourceTrimmed":false,"tip":"「爸妈，这事我们俩有计划，等时机合适了一定告诉你们。」","links":[],"evType":"法条"},"rq15-11":{"costText":"放下「做客」的心态。","gainText":"伴侣的父母放心把孩子交给你。","gainTrimmed":false,"remark":"被长辈挑剔时，可以让伴侣帮你解围，事后两人再沟通。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-12":{"costText":"在日历里设个提醒。","gainText":"小心意积累成大信任。","gainTrimmed":false,"remark":"你自己父母的重要日子，也别忘了。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「妈，生日快乐！给您订了个蛋糕，晚上到。」","links":[],"evType":"经验共识"},"rq15-13":{"costText":"可能让一方的家人不满。","gainText":"家庭的钱袋子有共同的守门人。","gainTrimmed":false,"remark":"出于亲情帮父母兄弟是正常的，问题不在帮，而在瞒。","source":"《中华人民共和国民法典》第一千零六十二条（夫妻对共同财产有平等的处理权）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-14":{"costText":"收起评判。","gainText":"伴侣不必在你和家人之间左右为难。","gainTrimmed":false,"remark":"地域习惯的差异见第 27 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-15":{"costText":"承认问题的严重性。","gainText":"认清处境，知道有法律可以依靠。","gainTrimmed":false,"remark":"记录发生的时间、内容，保留录音、聊天记录、就医证明，可以求助妇联（12338）。","source":"《中华人民共和国反家庭暴力法》第二条、第二十三条；最高人民法院《关于办理人身安全保护令案件适用法律若干问题的规定》（2022）第三条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq15-16":{"costText":"多一道确认。","gainText":"不在不知情的情况下背上一笔债。","gainTrimmed":false,"remark":"超出家庭日常生活需要、债权人不能证明用于共同生活的，原则上不属于共同债务。","source":"《中华人民共和国民法典》第一千零六十四条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-17":{"costText":"时间和精力。","gainText":"困难时刻，关系反而更牢。","gainTrimmed":false,"remark":"探病的礼节见第 31 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-18":{"costText":"一次律师咨询。","gainText":"在最难的时候，不再因为不懂规则吃亏。","gainTrimmed":false,"remark":"离婚冷静期只适用于到民政部门协议离婚，起诉离婚不适用。存在家暴的，可以直接起诉，并同时申请人身安全保护令。","source":"《中华人民共和国民法典》第一千零七十六条、第一千零七十七条（离婚冷静期）、第一千零七十九条、第一千零九十二条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-19":{"costText":"咽下对前任的怨气。","gainText":"孩子在父母分开后，仍然有安全感。","gainTrimmed":false,"remark":"对方不付抚养费、阻挠探望的，可以向法院申请强制执行。","source":"《中华人民共和国民法典》第一千零八十四条（离婚后父母对子女仍有抚养、教育、保护的权利和义务）、第一千零八十五条（抚养费）、第一千零八十六条（探望权）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq15-20":{"costText":"咨询费和放下面子。","gainText":"给婚姻一个修复的机会。","gainTrimmed":false,"remark":"选择有资质的心理咨询师；存在家暴的，伴侣咨询不是首选，先保证安全。","source":"Christensen, A., et al. (2004). Traditional versus integrative behavioral couple therapy for significantly and chronically distressed married couples. Journal of Consulting and Cli…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq16-1":{"costText":"调整心里的预期。","gainText":"少一些「我把他当朋友，他却……」的委屈。","gainTrimmed":false,"remark":"朋友的层级会变化，有的玩伴会在某次危难中变成知己。","source":"Dunbar, R. I. M. (2018). The anatomy of friendship. Trends in Cognitive Sciences, 22(1), 32–51.（人的社会关系呈层级分布，最亲密的圈子通常只有几个人。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-2":{"costText":"控制额度、写借条的尴尬。","gainText":"钱和友谊，至少保住一样。","gainTrimmed":false,"remark":"朋友为还网贷、赌债、投资亏损借钱的，借出去基本是填窟窿。","source":"经验共识，本书整理；借条要素和法律规则见第 12 章。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-3":{"costText":"忍住分享的冲动。","gainText":"成为别人愿意交心的那个人。","gainTrimmed":false,"remark":"朋友透露有自伤、伤人的打算，或者有人正在遭受虐待，保护生命安全优先于保密。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-4":{"costText":"放下比较的心。","gainText":"友谊在好事和难事里都被加深。","gainTrimmed":false,"remark":"心里有点酸也正常，承认它，但别让它变成冷淡或挖苦。","source":"Gable, S. L., Reis, H. T., Impett, E. A., & Asher, E. R. (2004). What do you do when things go right? Journal of Personality and Social Psychology, 87(2), 228–245.（「积极主动式回应」与更高的关系满…","sourceTrimmed":true,"tip":"「太好了！你这一年真的太拼了，必须庆祝一下！」","links":[],"evType":"经验共识"},"rq16-5":{"costText":"留心一下账。","gainText":"聚会不会因为钱的事变味。","gainTrimmed":false,"remark":"朋友经济条件明显差的，可以多请几次，但方式要自然，别让人觉得被施舍。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次咱们 AA 吧，以后常聚，谁也别有负担。」","links":[],"evType":"经验共识"},"rq16-6":{"costText":"把建议往后放一放。","gainText":"朋友遇事愿意来找你。","gainTrimmed":false,"remark":"朋友的选择明显危害他自己（比如参与赌博、被骗投资），可以直接表达担心。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-7":{"costText":"可能得罪朋友。","gainText":"不因为一张卡背上刑事责任。","gainTrimmed":false,"remark":"已经借出去的，立即挂失、注销，并向银行和公安机关说明情况。","source":"《中华人民共和国反电信网络诈骗法》第三十一条；《中华人民共和国刑法》第二百八十七条之二（帮助信息网络犯罪活动罪）、第三百一十二条（掩饰、隐瞒犯罪所得罪）。","sourceTrimmed":false,"tip":"「卡和身份证这些我谁都不借，这个真不是针对你。」","links":[],"evType":"法条"},"rq16-8":{"costText":"可能被说「不讲义气」。","gainText":"帮朋友的方式有很多，不必把自己搭进去。","gainTrimmed":false,"remark":"你如实作证、说出知道的事实，是法定义务，也不算出卖朋友。","source":"《中华人民共和国刑法》第三百零五条（伪证罪）、第三百零七条（妨害作证罪；帮助毁灭、伪造证据罪）；《中华人民共和国民事诉讼法》关于妨害民事诉讼的强制措施的规定。","sourceTrimmed":false,"tip":"「你的事我能帮你找律师、陪你去，但让我说假话，我做不到，对你也没好处。」","links":[],"evType":"法条"},"rq16-9":{"costText":"放弃一部分「熟人生意」。","gainText":"生意做不成，朋友还在。","gainTrimmed":false,"remark":"需要拉人头、交入门费才能赚钱的项目，可能是传销，见第 30 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-10":{"costText":"迈出第一步的不好意思。","gainText":"值得的友谊被找回来，过去的友谊被好好放下。","gainTrimmed":false,"remark":"疏远是因为一次具体的矛盾，可以考虑先道个歉，见本节第 13 条。","source":"Liu, P. J., Rim, S., Min, L., & Min, K. E. (2023). The surprise of reaching out: Appreciated more than we think. Journal of Personality and Social Psychology, 124(4), 754–771.（人们会低…","sourceTrimmed":true,"tip":"「好久没见了，突然想起我们以前一起……最近怎么样？」","links":[],"evType":"经验共识"},"rq16-11":{"costText":"克制「你知道吗」的冲动。","gainText":"在朋友圈里成为安全、可靠的人。","gainTrimmed":false,"remark":"八卦涉及对某人的不实指控，传播可能构成侵犯名誉权。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-12":{"costText":"少一些单独相处。","gainText":"友情和爱情都不受伤。","gainTrimmed":false,"remark":"伴侣以此为由控制你所有的社交，见第 14 章关于控制的部分。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-13":{"costText":"放下面子。","gainText":"一段值得的友谊不因为一口气而断掉。","gainTrimmed":false,"remark":"对方触碰了你的底线（欺骗、背叛、伤害），不必为了和好而勉强自己。","source":"经验共识，本书整理；道歉的要素见第 2 章。","sourceTrimmed":false,"tip":"「那天是我说话太冲了，对不起。我挺在乎咱俩的，想把话说开。」","links":[],"evType":"经验共识"},"rq16-14":{"costText":"一段可能很沉重的陪伴。","gainText":"可能挽回一条生命。","gainTrimmed":false,"remark":"不要答应替他保守想自杀的秘密，保护生命安全优先。","source":"Dazzi, T., Gribble, R., Wessely, S., & Fear, N. T. (2014). Does asking about suicide and related behaviours induce suicidal ideation? Psychological Medicine, 44(16), 3361–3363；…","sourceTrimmed":true,"tip":"「你说的这些让我很担心。你是不是有想伤害自己的念头？我陪你一起想办法。」","links":[],"evType":"经验共识"},"rq16-15":{"costText":"一句感谢或一顿饭。","gainText":"朋友愿意继续为你张罗。","gainTrimmed":false,"remark":"介绍成了对象、工作，后续出现矛盾，别把朋友拉进来当裁判。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-16":{"costText":"记着时间，必要时赔偿。","gainText":"下次再借，朋友还愿意借。","gainTrimmed":false,"remark":"借车出了交通事故，责任和保险问题复杂，借车前先确认保险情况。","source":"《中华人民共和国民法典》第一千一百六十五条（因过错侵害他人财产，应当承担侵权责任）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-17":{"costText":"一点固定的投入。","gainText":"多年以后，身边还有几个老朋友。","gainTrimmed":false,"remark":"友情的深浅和共处时间密切相关，见面比文字联系更有效。","source":"Hall, J. A. (2019). How many hours does it take to make a friend? Journal of Social and Personal Relationships, 36(4), 1278–1296.（从熟人发展成好朋友，大约需要两百小时的共处时间。）","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq16-18":{"costText":"观察的时间。","gainText":"身边的朋友让你变好，而不是把你拉进坑里。","gainTrimmed":false,"remark":"判断别人之前，也看看自己是不是别人眼里值得交的朋友。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq17-1":{"costText":"多观察、多记录。","gainText":"很快从「新人」变成「自己人」。","gainTrimmed":false,"remark":"公司有入职手册、新人培训的，认真看，很多问题里面都有答案。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq17-2":{"costText":"先花十分钟自己找答案。","gainText":"显得认真，也节省别人的时间。","gainTrimmed":false,"remark":"涉及安全、合规、对外承诺的事，宁可多问一次，也别凭感觉做。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我看了上个月的报表模板，这个口径是按自然月还是按结算月？我理解是结算月，对吗？」","links":[],"evType":"经验共识"},"rq17-3":{"costText":"多问一两句。","gainText":"一次做对，少返工。","gainTrimmed":false,"remark":"任务之间有冲突时，请领导排优先级，见第 4 章第 6 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我确认一下：周三下班前给您一版竞品对比，重点看价格和功能，先出一页纸的结论，对吗？」","links":[],"evType":"经验共识"},"rq17-4":{"costText":"说坏消息的忐忑。","gainText":"领导信任你，不会在关键时刻被你「惊吓」。","gainTrimmed":false,"remark":"汇报时先说结论，再说原因和计划，见第 18 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个数据源周一接口改了，进度可能延后一天。我先用备份数据做了一版，您看能不能先用着？」","links":[],"evType":"经验共识"},"rq17-5":{"costText":"会后发一条消息。","gainText":"减少误解，必要时也有据可查。","gainTrimmed":false,"remark":"涉及违规、违法的口头要求，留下书面记录更加重要，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq17-6":{"costText":"承认错误的难堪。","gainText":"错误变成一次被信任的机会。","gainTrimmed":false,"remark":"同样的错误不要犯第二次，复盘原因并改进流程。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王经理，我刚发现给客户的报价单有个数字错了，我已经打电话说明并重新发了一版，想跟您报备一下。」","links":[],"evType":"经验共识"},"rq17-7":{"costText":"看懂合同里的几行字。","gainText":"新人也不吃哑巴亏。","gainTrimmed":false,"remark":"只约定试用期、不约定合同期限的，试用期不成立，该期限视为劳动合同期限。","source":"《中华人民共和国劳动合同法》第十九条、第二十条；《中华人民共和国社会保险法》第五十八条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq17-8":{"costText":"主动提醒人事一次。","gainText":"权益有书面保障，出了纠纷有凭证。","gainTrimmed":false,"remark":"二倍工资的仲裁时效等问题比较复杂，发生争议时咨询 12333 或劳动仲裁机构。","source":"《中华人民共和国劳动合同法》第十条、第十六条（劳动合同文本由用人单位和劳动者各执一份）、第八十二条。","sourceTrimmed":false,"tip":"「请问劳动合同什么时候签？我这边好准备一下材料。」","links":[],"evType":"法条"},"rq17-9":{"costText":"拒绝时承受压力。","gainText":"时间和健康有底线。","gainTrimmed":false,"remark":"实行不定时工作制、综合计算工时制的岗位，规则不同，以批准文件和合同约定为准。","source":"《中华人民共和国劳动法》第四十一条、第四十四条；《中华人民共和国劳动合同法》第三十一条；人力资源社会保障部、最高人民法院联合发布的超时加班劳动人事争议典型案例（2021）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq17-10":{"costText":"先忍住指出问题的冲动。","gainText":"建议更容易被采纳，也不会被认为是「刚来就指手画脚」。","gainTrimmed":false,"remark":"发现的是安全隐患或违规问题，不必等，及时报告。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我注意到这个流程每次要人工核对三遍，想了解一下当初这么设计的原因，有没有可能简化一下？」","links":[],"evType":"经验共识"},"rq17-11":{"costText":"发之前整理一下。","gainText":"别人愿意回你的消息，效率也高。","gainTrimmed":false,"remark":"工作群消息的规矩，见第 26 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王经理，周报已更新，本周销售额环比增长 8%，有两个风险点需要您决策，详见附件第 3 页，周五前回复即可。」","links":[],"evType":"经验共识"},"rq17-12":{"costText":"请教时的诚意和偶尔的一顿饭。","gainText":"成长更快，也多了一位职场上的支持者。","gainTrimmed":false,"remark":"别把请教变成让前辈替你干活。","source":"Allen, T. D., et al. (2004). Career benefits associated with mentoring for protégés: A meta-analysis. Journal of Applied Psychology, 89(1), 127–136.（有导师指导的员工在薪酬、晋升和职业满意度上表现更好。）","sourceTrimmed":false,"tip":"「上次您说的那个方法我试了，效率高了很多，太感谢了。」","links":[],"evType":"经验共识"},"rq17-13":{"costText":"忍住委屈。","gainText":"领导觉得你可塑，愿意继续给你机会。","gainTrimmed":false,"remark":"批评变成人身攻击、侮辱人格的，不必忍，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「好的，我记下了，今天下班前改好给您。」","links":[],"evType":"经验共识"},"rq17-14":{"costText":"管住好奇心。","gainText":"少一些办公室里的暗流。","gainTrimmed":false,"remark":"同工不同酬、性别歧视等问题，可以通过正式渠道反映或申请劳动仲裁。","source":"经验共识，本书整理；以所在单位的规章制度为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq17-15":{"costText":"判断一下轻重缓急。","gainText":"工作和生活之间留一条缝。","gainTrimmed":false,"remark":"有法院在判决中认定，下班后利用微信等工具安排实质性工作属于加班，可以作为主张加班费的参考。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（第二天）「昨晚看到您的消息了，我上午整理好发您。」","links":[],"evType":"经验共识"},"rq17-16":{"costText":"少发几条朋友圈。","gainText":"不因为一条动态丢了工作。","gainTrimmed":false,"remark":"公司有明确社交媒体使用规定的，入职时认真看一遍。","source":"《中华人民共和国反不正当竞争法》（2025 年修订）第十条（侵犯商业秘密的行为）；《中华人民共和国劳动合同法》第二十三条（保密义务）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq17-17":{"costText":"午休时间。","gainText":"快速融入，又不卷入是非。","gainTrimmed":false,"remark":"同事关系的处理见第 19 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq17-18":{"costText":"放弃包装过度的诱惑。","gainText":"入职以后不用天天担心被识破。","gainTrimmed":false,"remark":"学历可以在学信网上查验，单位核实很方便。","source":"《中华人民共和国劳动合同法》第八条（劳动者的如实说明义务）、第二十六条（以欺诈手段订立的劳动合同无效）、第三十九条；《中华人民共和国刑法》第二百八十条（伪造、变造、买卖国家机关公文、证件、印章罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq17-19":{"costText":"一点额外的时间。","gainText":"攒下人缘，又不被无限加活。","gainTrimmed":false,"remark":"被频繁指派与岗位无关的杂事，可以和直属领导沟通。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我手上的事今天要交，下午四点以后可以帮你看看，行吗？」","links":[],"evType":"经验共识"},"rq17-20":{"costText":"在小事上不打折。","gainText":"重要的机会会先想到你。","gainTrimmed":false,"remark":"可靠不等于逆来顺受，合法权益照样要维护。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-1":{"costText":"汇报前整理一下思路。","gainText":"领导愿意听你汇报，也更容易做决定。","gainTrimmed":false,"remark":"书面汇报同样适用，邮件第一段就写结论。","source":"Minto, B.《金字塔原理》（The Pyramid Principle）：先结论后论据的表达结构。","sourceTrimmed":false,"tip":"「王总，A 客户的合同签下来了，比预期少了 5%，主要让在了交付周期上。下一步我准备……需要您帮忙协调一下技术部。」","links":[],"evType":"经验共识"},"rq18-2":{"costText":"自己先多想一步。","gainText":"领导觉得你能独当一面。","gainTrimmed":false,"remark":"真想不出办法，也要说明你已经尝试了什么，而不是空手去问。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-3":{"costText":"观察一段时间。","gainText":"同样的内容，更容易被领导接收。","gainTrimmed":false,"remark":"拿不准，可以直接问：「这类事您希望我当面汇报还是发邮件？」","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-4":{"costText":"一条消息。","gainText":"领导觉得把事交给你很省心。","gainTrimmed":false,"remark":"同时给几位领导做事的，每件事都要单独闭环。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「您上午让联系的供应商已经确认了，下周一送样。」","links":[],"evType":"经验共识"},"rq18-5":{"costText":"多一层沟通。","gainText":"守住组织规矩，也守住自己的底线。","gainTrimmed":false,"remark":"通过正式渠道举报违法违规行为，受法律保护，单位不得打击报复。","source":"经验共识，本书整理；以所在单位的举报、合规制度为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-6":{"costText":"会上忍住反驳。","gainText":"意见被听到，领导也有面子。","gainTrimmed":false,"remark":"事关安全、合规的错误，需要当场指出时，语气平和、只说事实。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（会后）「王总，会上那个方案我有个顾虑想跟您单独汇报一下……」","links":[],"evType":"经验共识"},"rq18-7":{"costText":"把不认同的事做好，心里会别扭。","gainText":"既是可靠的执行者，也保住了自己的判断。","gainTrimmed":false,"remark":"「执行」不包括违法违规的要求，那种情况见本章第 10 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「方案按您定的推进。我把之前说的库存风险整理在邮件里了，供您参考，我们会提前做好预案。」","links":[],"evType":"经验共识"},"rq18-8":{"costText":"少说一点自己。","gainText":"同事愿意帮你，领导也放心把大事交给你。","gainTrimmed":false,"remark":"被别人抢了功，可以通过周报、邮件、项目文档留下自己的工作记录，见第 19 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-9":{"costText":"管住好奇心和嘴。","gainText":"赢得信任，也避开是非。","gainTrimmed":false,"remark":"如果领导的私事涉及违法违规（例如挪用公款），那就不是「私事」，见本章第 10 条和第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-10":{"costText":"顶住压力，可能影响和领导的关系。","gainText":"保住饭碗之外，更保住了自由和名声。","gainTrimmed":false,"remark":"因为拒绝违法要求被调岗、降薪、辞退的，保留证据去劳动仲裁，见第 21 章、第 28 章。","source":"《劳动合同法》第三十二条（劳动者拒绝违章指挥、强令冒险作业，不视为违反劳动合同）；《会计法》第五条（不得授意、指使、强令会计人员伪造会计资料，不得打击报复依法抵制的会计人员）。","sourceTrimmed":false,"tip":"「这个操作不符合财务制度，我签了字以后要担责任。您看能不能走一下正式审批，或者给我一个书面的说法？」","links":[],"evType":"法条"},"rq18-11":{"costText":"一次主动沟通，几周观察。","gainText":"在新领导心里留下「清楚、靠谱」的第一印象。","gainTrimmed":false,"remark":"前任领导的承诺（例如答应的晋升），新领导不一定认，要尽早书面确认。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，我简单跟您汇报一下我这边的三块工作。您刚来，有什么想先了解的、希望我怎么配合，您随时说。」","links":[],"evType":"经验共识"},"rq18-12":{"costText":"准备材料，承受被拒绝的尴尬。","gainText":"把「求情」变成「谈判」。","gainTrimmed":false,"remark":"别拿别家的 offer 当筹码去威胁，除非你真的准备走。","source":"Babcock, L. & Laschever, S. (2003). Women Don't Ask: Negotiation and the Gender Divide. Princeton University Press（不主动谈判会带来长期的收入差距）。","sourceTrimmed":false,"tip":"「今年我负责的渠道收入涨了 40%，同岗位的市场价大概在这个区间。我希望薪资能调到 X，您看需要我在哪些方面再做出成绩？」","links":[],"evType":"经验共识"},"rq18-13":{"costText":"提前规划。","gainText":"休得安心，回来也不被埋怨。","gainTrimmed":false,"remark":"病假、婚假、产假、陪产假的天数各地规定不同，以当地条例和公司制度为准。","source":"《职工带薪年休假条例》第三条（累计工作满 1 年不满 10 年的 5 天，满 10 年不满 20 年的 10 天，满 20 年的 15 天）、第五条（单位安排不了、经职工同意不休的，按日工资收入的 300% 支付年休假工资报酬）。","sourceTrimmed":false,"tip":"「我下周三到周五想休年假，手上的周报已经提前交了，客户那边有急事小张会对接，我每天晚上看一次消息。」","links":[],"evType":"法条"},"rq18-14":{"costText":"两边都不讨好的压力。","gainText":"哪边都挑不出你的错。","gainTrimmed":false,"remark":"长期被迫站队、两头受气的，考虑换岗位，见第 21 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「李总让我先做 A，张总让我先做 B，两件事时间冲突，我拉个三方会，请两位定一下优先级？」","links":[],"evType":"经验共识"},"rq18-15":{"costText":"忍住吐槽。","gainText":"问题被解决，你也不落「爱告状」的名声。","gainTrimmed":false,"remark":"先和同事本人沟通过、没解决再找领导，顺序别反了。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这周的接口已经延期两次了，影响了我们周五的上线。能不能请您帮忙协调一下资源？」","links":[],"evType":"经验共识"},"rq18-16":{"costText":"多问一句、多看一份文件。","gainText":"做的事被认可，资源也容易拿到。","gainTrimmed":false,"remark":"和领导目标一致不等于什么都听，违规的事见本章第 10 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「今年部门最重要的指标是什么？我这块工作怎么做能帮上忙？」","links":[],"evType":"经验共识"},"rq18-17":{"costText":"当场的难堪。","gainText":"错误变成一次被信任的机会。","gainTrimmed":false,"remark":"人格侮辱式的批评如何留证和维权，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次是我考虑不周，我今天下班前把补救方案发给您。」","links":[],"evType":"经验共识"},"rq18-18":{"costText":"克制住「我知道内幕」的冲动。","gainText":"领导愿意在你面前放松，也不会因此提防你。","gainTrimmed":false,"remark":"酒桌上的规矩见第 10 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq18-19":{"costText":"时间和精力，偶尔还要垫钱。","gainText":"守住工作边界，也避免卷进违规的事。","gainTrimmed":false,"remark":"公职人员让下属办私事、公车私用，属于违反纪律的行为，见第 23 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，这周我手上的投标材料比较赶，周末接孩子的事我可能顾不上，要不我帮您问问附近的托管？」","links":[],"evType":"经验共识"},"rq18-20":{"costText":"开口确认的尴尬。","gainText":"分清哪些是真机会，哪些只是激励话术。","gainTrimmed":false,"remark":"涉及工资、奖金、股权的，以劳动合同、正式文件为准，口头说的很难主张。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「谢谢王总！我确认一下：如果年底项目按时上线，明年一季度晋升到 P6，对吗？我记一下，按这个目标努力。」","links":[],"evType":"经验共识"},"rq18-21":{"costText":"几十到一两百元的心意。","gainText":"表达了心意，又不给双方添麻烦。","gainTrimmed":false,"remark":"送礼的一般分寸见第 7 章。","source":"经验共识，本书整理；以所在单位的廉洁制度为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq19-1":{"costText":"放下「要被所有人喜欢」的执念。","gainText":"关系稳定，不容易卷进是非。","gainTrimmed":false,"remark":"同事变成好朋友后，工作上的分歧也要按工作的方式处理，别混在一起。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq19-2":{"costText":"少一点谈资，偶尔显得不合群。","gainText":"不得罪人，也让人觉得你嘴严、可信。","gainTrimmed":false,"remark":"朋友之间的八卦见第 16 章第 11 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这事我不太了解，不好说。对了，下午那个会要准备什么？」","links":[],"evType":"经验共识"},"rq19-3":{"costText":"忍住吐槽的冲动。","gainText":"保住名声，也不给别人留把柄。","gainTrimmed":false,"remark":"对事情的正当意见，通过正式渠道提，见第 18 章第 15 条。","source":"Skowronski, J. J., Carlston, D. E., Mae, L., & Crawford, M. T. (1998). Spontaneous trait transference: Communicators take on the qualities they describe in others. Journal of Perso…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq19-4":{"costText":"把请求想清楚再开口。","gainText":"别人更愿意帮你，下次也帮得更痛快。","gainTrimmed":false,"remark":"同一个人别总麻烦，别人帮了你，有机会也要还回去，见第 6 章。","source":"Grant, A. M., & Gino, F. (2010). A little thanks goes a long way: Explaining why gratitude expressions motivate prosocial behavior. Journal of Personality and Social Psychology, 98…","sourceTrimmed":true,"tip":"「张哥，客户周四要报价，里面的运费我拿不准，您之前做过华南线，能不能帮我看下第三页的测算？明天中午前给我就行，谢谢！」","links":[],"evType":"经验共识"},"rq19-5":{"costText":"时间，或者拒绝的尴尬。","gainText":"既帮了人，又守住了自己的节奏。","gainTrimmed":false,"remark":"拒绝的具体方法见第 4 章；被一点点加码的，见第 4 章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我今天要赶完投标书，明天上午可以帮你看一小时，你看来得及吗？」","links":[],"evType":"经验共识"},"rq19-6":{"costText":"会后多写几行字。","gainText":"出了问题能说清楚责任，也少了很多误会。","gainTrimmed":false,"remark":"领导的口头指令也可以这样确认，见第 17 章第 5 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「同步一下今天的结论：1. 方案用 B 版；2. 小王周三前出设计稿；3. 我周五对接客户。有出入的请回复，谢谢。」","links":[],"evType":"经验共识"},"rq19-7":{"costText":"当面说「不是我」的压力。","gainText":"责任分清了，也让人知道你不是可以随便推锅的人。","gainTrimmed":false,"remark":"确实有你一部分责任的，先认下自己的那部分，再说清其余部分，可信度更高。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我补充一下：上周三的会上，这一块定的是由运营组跟进，我负责的是数据部分，纪要我会后发给大家。」","links":[],"evType":"经验共识"},"rq19-8":{"costText":"养成记录的习惯。","gainText":"你的付出被看见，也不伤和气。","gainTrimmed":false,"remark":"反过来，自己汇报时也要主动提到别人的贡献，见第 18 章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，上次汇报的那版分析，数据模型是我搭的，我把过程文档发您一份，后续优化我也可以继续跟。」","links":[],"evType":"经验共识"},"rq19-9":{"costText":"咽下失落。","gainText":"保住风度，也拿到了下一次的路线图。","gainTrimmed":false,"remark":"确实存在不公平的评定，可以按公司的申诉流程走。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「恭喜啊，实至名归！」（对领导）「这次晋升我没赶上，想听听您的看法，我接下来重点补哪些？」","links":[],"evType":"经验共识"},"rq19-10":{"costText":"主动开口的别扭。","gainText":"冲突变成了磨合，关系可能比以前更好。","gainTrimmed":false,"remark":"对方涉及辱骂、威胁、骚扰的，不属于普通冲突，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「昨天在会上我语气有点冲，不好意思。我主要是担心上线时间，我们一起看看怎么排更合适？」","links":[],"evType":"经验共识"},"rq19-11":{"costText":"半小时和一顿午饭。","gainText":"多一个信任你的同事。","gainTrimmed":false,"remark":"介绍情况只说事，不要借机给他讲别人的是非。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq19-12":{"costText":"一顿饭或一句祝福。","gainText":"职业圈子里多了一份好口碑。","gainTrimmed":false,"remark":"自己离职时的做法，见第 21 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这几年跟你学了很多，新地方加油，常联系！」","links":[],"evType":"经验共识"},"rq19-13":{"costText":"可能要不回来的钱，或者拒绝的尴尬。","gainText":"不因为钱坏了每天要相处的关系。","gainTrimmed":false,"remark":"拒绝借钱的说法见第 4 章第 4 条；朋友借钱见第 16 章第 2 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次真不太方便，家里刚交了房租。你要是急，可以看看公司有没有员工互助金。」","links":[],"evType":"经验共识"},"rq19-14":{"costText":"几十到一两百元。","gainText":"既合群，又不被份子钱绑架。","gainTrimmed":false,"remark":"随份子的一般分寸见第 8 章，同事份子钱随多少见第 8 章第 12 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（组织者）「给小王的结婚礼物，每人 50 元，买了一套餐具共 680 元，剩下的 20 元下次团建用，明细在这里。」","links":[],"evType":"经验共识"},"rq19-15":{"costText":"时刻要注意分寸。","gainText":"感情和工作都不被对方拖累。","gainTrimmed":false,"remark":"对方不愿意还反复追求，或者利用职权施压，就不是恋爱而是骚扰，见本章第 18 条。","source":"经验共识，本书整理；以所在单位的员工手册为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq19-16":{"costText":"守住嘴。","gainText":"成为别人信得过的人。","gainTrimmed":false,"remark":"负责人事、行政等工作的人，接触员工的健康、家庭信息，还要遵守《个人信息保护法》的相关要求。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（别人打听时）「他请假的原因我不清楚，工作上有需要找我就行。」","links":[],"evType":"经验共识"},"rq19-17":{"costText":"心理上的煎熬，主动开口的勇气。","gainText":"把模糊的委屈变成可以处理的问题。","gainTrimmed":false,"remark":"长期被霸凌影响身心健康的，及时寻求心理帮助，必要时考虑换环境，见第 21 章、第 28 章。","source":"Williams, K. D. (2007). Ostracism. Annual Review of Psychology, 58, 425–452（被排斥带来的心理痛苦及其影响）。","sourceTrimmed":false,"tip":"「这三次项目会我都没有收到通知，导致我负责的部分没能同步，我想请您帮忙看看是哪里出了问题。」","links":[],"evType":"经验共识"},"rq19-18":{"costText":"说出来的勇气，可能面对的流言。","gainText":"及时制止，也为后续维权保留证据。","gainTrimmed":false,"remark":"留证、报警和起诉的具体办法见第 28 章。男性同样可能遭受性骚扰，法律同样保护。","source":"《民法典》第一千零一十条（违背他人意愿实施性骚扰的，受害人有权请求行为人承担民事责任；机关、企业、学校等单位应当采取合理的预防、受理投诉、调查处置等措施）。","sourceTrimmed":false,"tip":"「你刚才的话让我很不舒服，请以后不要再这样。」","links":[],"evType":"经验共识"},"rq19-19":{"costText":"多发一条私聊。","gainText":"对方记你的情。","gainTrimmed":false,"remark":"同样的错误反复出现、影响到你的工作，再按第 18 章第 15 条反映。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「小王，表格第 12 行的合计好像少算了一项，你看下？我没在群里说。」","links":[],"evType":"经验共识"},"rq19-20":{"costText":"放弃一些「小聪明」。","gainText":"赢得光明正大，输了也不丢人。","gainTrimmed":false,"remark":"对方使绊子的，按本章第 6、7 条留痕、澄清，不必以牙还牙。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq19-21":{"costText":"多一点耐心。","gainText":"下次找他们，事情办得更快。","gainTrimmed":false,"remark":"对方一直拖着不办，请双方领导协调，而不是在群里施压。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次活动能按时上线，多亏技术部小刘加班支持，特别感谢！」（抄送对方领导）","links":[],"evType":"经验共识"},"rq19-22":{"costText":"一点时间和耐心。","gainText":"做一个让人信任的倾听者，又不卷进是非。","gainTrimmed":false,"remark":"同事流露出轻生念头的，认真对待，帮他联系家人或专业帮助，见第 16 章第 14 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「确实挺憋屈的，你打算怎么处理？需要我帮什么忙吗？」","links":[],"evType":"经验共识"},"rq20-1":{"costText":"放下「我自己做更快」的习惯。","gainText":"团队能力上来了，你也才有下一步。","gainTrimmed":false,"remark":"刚上任的头几个月，可以保留一小块自己擅长的业务，但要逐步交出去。","source":"Grove, A. S. (1983). High Output Management. Random House（管理者的产出等于其所管理和影响的团队的产出）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq20-2":{"costText":"布置前多想五分钟。","gainText":"少返工，下属也少挨冤枉骂。","gainTrimmed":false,"remark":"下属接任务时也应当确认这些，见第 17 章第 3 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次要做的是三家竞品的价格对比，目的是给下周定价会做参考。一页纸结论加附表，周三下班前给我。数据可以找市场部的小林要。你说一下你的理解？」","links":[],"evType":"经验共识"},"rq20-3":{"costText":"留意下属做的好事。","gainText":"下属知道什么是对的，也愿意继续这样做。","gainTrimmed":false,"remark":"批评的场合和分寸，也可参考第 2 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次客户投诉，小张当天就把退款流程理清楚了，还写了一份排查清单，以后大家都可以用。」","links":[],"evType":"经验共识"},"rq20-4":{"costText":"每人每两周半小时到一小时。","gainText":"问题早发现，人心不走散。","gainTrimmed":false,"remark":"一对一不是用来催进度的，进度在例会上同步。","source":"Grove, A. S. (1983). High Output Management. Random House（一对一会议的做法与价值）。","sourceTrimmed":false,"tip":"「这半小时是你的，最近有什么想聊的？工作上、团队里的事都行。」","links":[],"evType":"经验共识"},"rq20-5":{"costText":"放弃「照顾自己人」的便利。","gainText":"团队信规则，而不是信关系。","gainTrimmed":false,"remark":"和某些下属私交好没关系，但工作安排上要经得起问。","source":"Colquitt, J. A., Conlon, D. E., Wesson, M. J., Porter, C. O. L. H., & Ng, K. Y. (2001). Justice at the millennium: A meta-analytic review of 25 years of organizational justice rese…","sourceTrimmed":true,"tip":"","links":[],"evType":"经验共识"},"rq20-6":{"costText":"在上级面前少一点个人光环。","gainText":"下属愿意跟你，上级也看到你带团队的能力。","gainTrimmed":false,"remark":"替团队扛责任，不等于包庇违规，违法违规的事要按规定处理。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对上级）「这次延误主要是我在排期上估计不足，我们已经定了补救方案。」","links":[],"evType":"经验共识"},"rq20-7":{"costText":"推辞时的一点尴尬。","gainText":"保住公平，也保住自己。","gainTrimmed":false,"remark":"利用职务便利收受财物，在企业可能构成非国家工作人员受贿罪，在机关和国企后果更重，见第 29 章。","source":"经验共识，本书整理；以所在单位的廉洁制度为准。","sourceTrimmed":false,"tip":"「心意我领了，东西你拿回去。以后不用这样，工作做好就是对我最大的支持。」","links":[],"evType":"经验共识"},"rq20-8":{"costText":"压住火气。","gainText":"同样的错误不再犯，团队也敢暴露问题。","gainTrimmed":false,"remark":"对外，例如对客户和上级，管理者先担起责任，见本章第 6 条。","source":"Beyer, B., Jones, C., Petoff, J., & Murphy, N. R. (Eds.) (2016). Site Reliability Engineering: How Google Runs Production Systems. O'Reilly Media（「事后复盘文化」一章：对事不对人的复盘）。","sourceTrimmed":false,"tip":"「先别急着追责，我们一起把时间线理一遍，看看是哪个环节没拦住，下次怎么防。」","links":[],"evType":"经验共识"},"rq20-9":{"costText":"听到不中听的话时，忍住不发火。","gainText":"问题在小的时候就被发现。","gainTrimmed":false,"remark":"心理安全不等于没有标准，该达成的目标照样要达成。","source":"Edmondson, A. (1999). Psychological safety and learning behavior in work teams. Administrative Science Quarterly, 44(2), 350–383.","sourceTrimmed":false,"tip":"「这个风险你提得很及时，谢谢。我们一起看看怎么处理。」","links":[],"evType":"经验共识"},"rq20-10":{"costText":"忍受别人用和你不同的方法做事。","gainText":"下属成长得快，你也省心。","gainTrimmed":false,"remark":"新人和能力还不够的，授权范围小一点、检查频率高一点，逐步放开。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个活动你全权负责，预算 5 万以内你自己定，超过的找我。每周五同步一次进度就行。」","links":[],"evType":"经验共识"},"rq20-11":{"costText":"处理别人情绪的耐心。","gainText":"矛盾止于萌芽，团队不分裂。","gainTrimmed":false,"remark":"涉及骚扰、霸凌的，不是普通矛盾，要按制度调查处理，见第 19 章第 17、18 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「你们俩的出发点都是为了项目好，我们把分歧摆出来，按上线时间优先的原则来定。」","links":[],"evType":"经验共识"},"rq20-12":{"costText":"艰难的谈话，可能的补偿金。","gainText":"给了人机会，处理起来也合法合规。","gainTrimmed":false,"remark":"辞退流程有瑕疵，可能被认定为违法解除，要支付双倍经济补偿，见第 21 章。","source":"《劳动合同法》第四十条第二项（不能胜任工作，经过培训或者调整工作岗位仍不能胜任的，提前三十日书面通知或者额外支付一个月工资后可以解除）、第四十六条（此种情形应支付经济补偿）；最高人民法院指导案例 18 号（考核居于末位等次不等同于不能胜任工作）。","sourceTrimmed":false,"tip":"「这两个月的交付有三次延期，标准是按时率 90% 以上。接下来六周我们每周对一次进度，你看需要什么支持？」","links":[],"evType":"法条"},"rq20-13":{"costText":"说话前多想一想。","gainText":"下属信你的话，关键时候才跟你走。","gainTrimmed":false,"remark":"站在下属角度如何确认领导的承诺，见第 18 章第 20 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「之前说的调薪，今年公司冻结了，我很抱歉没能兑现。我已经帮你申请了年底的专项奖，明年调薪窗口一开我第一个提。」","links":[],"evType":"经验共识"},"rq20-14":{"costText":"认真设计面试问题。","gainText":"招到合适的人，也避免歧视纠纷。","gainTrimmed":false,"remark":"女职工怀孕、产假、哺乳期间，单位不得因此降薪、辞退，见《妇女权益保障法》第四十八条。","source":"《就业促进法》第三条（劳动者就业不因民族、种族、性别、宗教信仰等不同而受歧视）；《妇女权益保障法》第四十三条（招聘中不得限定男性或男性优先，不得询问调查女性求职者婚育情况，不得把妊娠测试作为入职体检项目）。","sourceTrimmed":false,"tip":"「请讲讲你上一个项目里最难的一个环节，你具体做了什么？」","links":[],"evType":"法条"},"rq20-15":{"costText":"一次坦诚的谈话。","gainText":"团队看到你怎么对待离开的人，留下的人更安心。","gainTrimmed":false,"remark":"劳动者提前三十日书面通知即可解除劳动合同，不需要单位批准，见第 21 章。","source":"《劳动合同法》第五十条（解除或终止劳动合同时应出具证明，并在十五日内办理档案和社会保险关系转移手续）、第八十九条（未出具书面证明造成损害的，应当承担赔偿责任）。","sourceTrimmed":false,"tip":"「很遗憾，但我尊重你的选择。交接我们一起排一下，有什么需要我帮忙的你说。」","links":[],"evType":"法条"},"rq20-16":{"costText":"少一点「哥们儿」式的痛快。","gainText":"既有人情味，又能把事管住。","gainTrimmed":false,"remark":"对公司决策有意见，向上反映，对团队要讲清楚决策的道理和执行要求。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq20-17":{"costText":"活动预算和一点组织心思。","gainText":"团建真的起到让大家放松、熟悉的作用。","gainTrimmed":false,"remark":"酒桌上的规矩见第 10 章；不得以团建为名劝酒、灌酒。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这次团建定在周四下午，不喝酒，有事来不了的跟我说一声就行。」","links":[],"evType":"经验共识"},"rq20-18":{"costText":"放下「我是领导」的架子。","gainText":"把可能的阻力变成团队的支柱。","gainTrimmed":false,"remark":"对方当众不配合、拆台的，私下直接谈，说清楚角色和要求。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这块业务您比我熟，这次方案想先听听您的意见，再定分工。」","links":[],"evType":"经验共识"},"rq20-19":{"costText":"当着下属的面承认错误。","gainText":"团队也学会坦然面对错误。","gainTrimmed":false,"remark":"认错之后要有改正的动作，光认错不改，等于没认。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「上周我坚持先做 A 功能，现在看判断错了，耽误了大家两周。我们调整一下，从今天起优先做 B。」","links":[],"evType":"经验共识"},"rq20-20":{"costText":"和上级、其他部门讨价还价。","gainText":"团队愿意为你冲，因为知道你会护着他们。","gainTrimmed":false,"remark":"争资源要讲道理，不要为了面子硬抗上级的合理要求。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这个需求我们可以接，但要么把上线时间推一周，要么从测试组借两个人，您看哪种合适？」","links":[],"evType":"经验共识"},"rq20-21":{"costText":"加班成本，或者更合理的排期。","gainText":"团队有干劲，也不出法律问题。","gainTrimmed":false,"remark":"实行综合计算工时或不定时工作制的岗位，需经劳动行政部门批准，规则有所不同。","source":"《劳动法》第四十一条（延长工作时间一般每日不超过一小时，特殊原因每日不超过三小时，每月不超过三十六小时）、第四十四条（延长工作时间、休息日加班不能补休、法定休假日加班，分别支付不低于工资 150%、200%、300% 的报酬）。","sourceTrimmed":false,"tip":"「这周五上线，周四晚上可能要加班到九点，周一大家可以晚到半天调休。」","links":[],"evType":"法条"},"rq20-22":{"costText":"临时调整工作安排。","gainText":"赢得真正的人心。","gainTrimmed":false,"remark":"各地对生育奖励假、陪产假另有规定，以当地人口与计划生育条例为准。","source":"《女职工劳动保护特别规定》第七条（女职工生育享受 98 天产假，其中产前可以休假 15 天；难产、多胞胎的相应增加）；《妇女权益保障法》第四十八条（不得因结婚、怀孕、产假、哺乳等情形降低待遇、辞退）。","sourceTrimmed":false,"tip":"「你先去医院，手上的事交给小李，有需要随时说，不用着急回来。」","links":[],"evType":"法条"},"rq21-1":{"costText":"克制住当场爆发的冲动。","gainText":"多数问题在内部就能解决；解决不了，也有据可查。","gainTrimmed":false,"remark":"沟通时可以录音，见第 28 章关于录音证据的说明。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「关于 9 月绩效工资少发 2000 元的问题，我已在 10 月 8 日口头反映过，现书面申请核查，请在 10 月 20 日前答复。」","links":[],"evType":"经验共识"},"rq21-2":{"costText":"一边上班一边面试的辛苦。","gainText":"进可攻、退可守。","gainTrimmed":false,"remark":"裸辞之前要算的账，见本章第 21 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq21-3":{"costText":"管住嘴、管住手。","gainText":"给新东家留下成熟、可信的印象。","gainTrimmed":false,"remark":"哪些算商业秘密、哪些只是通用技能，见本章第 12 条。","source":"《反不正当竞争法》（2025 年修订）第十条（禁止违反保密义务披露、使用商业秘密，经营者以外的个人实施的视为侵犯商业秘密）；《劳动合同法》第二十三条（保密义务）。","sourceTrimmed":false,"tip":"「在上家公司我把渠道从零做到了一千万，现在想找一个能做全国市场的平台。」","links":[],"evType":"法条"},"rq21-4":{"costText":"多问几个问题。","gainText":"入职后不会发现「和说好的不一样」。","gainTrimmed":false,"remark":"入职一个月内要签书面劳动合同，见第 17 章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「想跟您确认一下：月薪 3 万是税前固定工资，还是包含绩效？年终奖是几个月，有没有发放条件？」","links":[],"evType":"经验共识"},"rq21-5":{"costText":"一封辞职信，和面对挽留时的坚持。","gainText":"主动权在自己手里。","gainTrimmed":false,"remark":"如果公司有欠薪、不交社保等过错，不要写「个人原因」，见本章第 6 条。","source":"《劳动合同法》第三十七条。","sourceTrimmed":false,"tip":"「本人因个人发展原因，申请于 2026 年 11 月 30 日解除劳动合同，最后工作日为当日。感谢公司的培养，交接工作我会全力配合。」","links":[],"evType":"法条"},"rq21-6":{"costText":"收集证据，可能要走仲裁。","gainText":"不用白白放弃应得的补偿。","gainTrimmed":false,"remark":"被暴力、威胁强迫劳动，或者违章指挥危及人身安全的，可以立即解除，不需要事先告知。","source":"《劳动合同法》第三十八条（单位过错时劳动者可以解除）、第四十六条第一项（此时单位应当支付经济补偿）。","sourceTrimmed":false,"tip":"「因公司自 2026 年 7 月起未足额支付工资，根据《劳动合同法》第三十八条，本人即日起解除劳动合同，并要求支付经济补偿。」","links":[],"evType":"法条"},"rq21-7":{"costText":"顶住当场签字的压力。","gainText":"避免一时慌乱签掉自己的权利。","gainTrimmed":false,"remark":"签了「个人原因辞职」或者「自愿放弃补偿」，事后想推翻非常难。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这份协议我需要回去仔细看一下，请把解除理由和补偿方案发我邮箱，我三天内答复。」","links":[],"evType":"经验共识"},"rq21-8":{"costText":"花十分钟弄懂规则。","gainText":"谈判时心里有数，不被一句「公司规定就这么多」打发。","gainTrimmed":false,"remark":"员工严重违纪、试用期不符合录用条件等被辞退的，单位不需要支付经济补偿，见该法第三十九条。","source":"《劳动合同法》第四十条（提前三十日书面通知或额外支付一个月工资）、第四十六条（应支付经济补偿的情形）、第四十七条（经济补偿的计算标准）、第八十七条（违法解除按经济补偿标准的二倍支付赔偿金）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-9":{"costText":"一段难熬的日子。","gainText":"保住谈判筹码。","gainTrimmed":false,"remark":"合同里约定了「公司可根据经营需要调整岗位」的，也要看调整是否合理，以仲裁和法院的认定为准。","source":"《劳动合同法》第三十五条（变更劳动合同约定的内容，应当协商一致并采用书面形式）、第三十八条。","sourceTrimmed":false,"tip":"「本人不同意公司单方调整岗位和降低工资，请按原劳动合同履行。」（书面发给人事）","links":[],"evType":"法条"},"rq21-10":{"costText":"几天的整理。","gainText":"离开后不会被追着要东西、背锅。","gainTrimmed":false,"remark":"个人的私人文件、照片，提前从公司设备里转走。","source":"《劳动合同法》第五十条第二款（劳动者应当按照约定办理工作交接；应付经济补偿的，在办结工作交接时支付）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-11":{"costText":"催几次的耐心。","gainText":"顺利入职下一家。","gainTrimmed":false,"remark":"新公司入职时一般会要离职证明，提前要好。","source":"《劳动合同法》第五十条、第八十九条；《劳动合同法实施条例》第二十四条（离职证明应写明的内容）。","sourceTrimmed":false,"tip":"「我的最后工作日是 11 月 30 日，请在当天出具离职证明，并在 15 日内办理社保转移，谢谢。」","links":[],"evType":"法条"},"rq21-12":{"costText":"认真看合同条款。","gainText":"分清哪些限制是合法的，哪些是在「绑人」。","gainTrimmed":false,"remark":"签了竞业又真去了竞争对手那里，要按约定支付违约金。拿不准的，入职新公司前先咨询律师。","source":"《劳动合同法》第二十三条、第二十四条；人力资源社会保障部办公厅《企业实施竞业限制合规指引》（人社厅发〔2025〕40 号）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-13":{"costText":"读一遍合同。","gainText":"不被吓住，该走就走。","gainTrimmed":false,"remark":"真给公司造成了实际损失的，例如故意泄密、损坏设备，单位仍然可以要求赔偿，这和违约金是两回事。","source":"《劳动合同法》第二十二条（服务期与违约金上限）、第二十五条（除服务期和竞业限制外，不得约定由劳动者承担违约金）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-14":{"costText":"准备材料、开庭的时间和精力。","gainText":"以很低的成本拿回应得的钱。","gainTrimmed":false,"remark":"证据要提前准备：劳动合同、工资流水、考勤记录、聊天记录、社保缴纳记录。","source":"《劳动争议调解仲裁法》第二十七条（仲裁时效）、第五十三条（劳动争议仲裁不收费）、第四十七条（小额追索劳动报酬等争议实行一裁终局）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-15":{"costText":"可能面对领导的不满。","gainText":"保住身体，也保住加班费。","gainTrimmed":false,"remark":"抢险救灾等特殊情况，法律允许不受上述限制延长工作时间。","source":"《劳动法》第四十一条、第四十四条；人力资源社会保障部、最高人民法院联合发布的超时加班劳动人事争议典型案例（2021 年 8 月）。","sourceTrimmed":false,"tip":"「这周已经连续三天加班到十点了，今晚家里有事，明早我提前一小时到把剩下的做完。」","links":[],"evType":"法条"},"rq21-16":{"costText":"一次次催要的时间。","gainText":"用正式渠道给公司施压，比私下哀求有效得多。","gainTrimmed":false,"remark":"农民工被欠薪的，还可以拨打 12333 或通过「全国根治欠薪线索反映平台」反映。","source":"《劳动合同法》第三十条第二款（拖欠劳动报酬的，劳动者可以向法院申请支付令）、第八十五条（劳动行政部门责令限期支付，逾期不支付的加付应付金额 50% 至 100% 的赔偿金）。","sourceTrimmed":false,"tip":"「本人 2026 年 8 月、9 月工资合计 26000 元至今未发放，请于 10 月 31 日前足额支付，否则我将依法投诉和申请仲裁。」","links":[],"evType":"法条"},"rq21-17":{"costText":"咽下当场的那口气。","gainText":"不因一时意气，丢掉补偿和职业口碑。","gainTrimmed":false,"remark":"如果是对方先有暴力、威胁等行为，先保护自己，保留证据并报警，见第 28 章。","source":"《劳动合同法》第三十九条第二项（劳动者严重违反用人单位规章制度的，用人单位可以解除劳动合同）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-18":{"costText":"把不满咽回去一部分。","gainText":"走得体面，日后还能回头。","gainTrimmed":false,"remark":"如果确实遭遇了违法违规行为，通过仲裁、投诉等正式渠道解决，而不是在面谈里发泄。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「在这里学到很多，主要是想往产品方向发展。如果说建议的话，新人培训可以更系统一些。」","links":[],"evType":"经验共识"},"rq21-19":{"costText":"逢年过节的一条消息。","gainText":"职业生涯里最可靠的推荐人和信息来源。","gainTrimmed":false,"remark":"对老东家有正当的维权诉求，照常通过法律渠道解决，和「不说坏话」并不矛盾。","source":"Granovetter, M. S. (1973). The strength of weak ties. American Journal of Sociology, 78(6), 1360–1380（求职信息常常来自联系不那么紧密的「弱关系」）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq21-20":{"costText":"放下「好马不吃回头草」的面子。","gainText":"多了一条可靠的退路。","gainTrimmed":false,"remark":"重新入职要重新签劳动合同，工作年限如何连续计算，以合同约定和当地规定为准。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，这一年在外面看了看，觉得还是咱们这边的方向更适合我。如果有合适的岗位，我很想回来，具体条件我们可以聊聊。」","links":[],"evType":"经验共识"},"rq21-21":{"costText":"认真算一次账。","gainText":"不因为一时冲动，让自己陷入被动。","gainTrimmed":false,"remark":"身心已经被工作压垮的，先保住健康，钱的问题可以慢慢想办法；必要时寻求心理援助。","source":"《失业保险条例》第十四条（领取失业保险金的条件）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq21-22":{"costText":"一次坦诚但别扭的谈话。","gainText":"转得成，也不会落下「吃里爬外」的名声。","gainTrimmed":false,"remark":"被公司单方调岗、而你不同意的，见本章第 9 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，我想跟您聊聊我的职业规划。我对数据分析一直很感兴趣，看到数据部在招人，想先听听您的意见。手上的工作我一定交接好。」","links":[],"evType":"经验共识"},"rq22-1":{"costText":"甲方放下架子，乙方挺起腰杆。","gainText":"合作得长久，口碑也好。","gainTrimmed":false,"remark":"甲方以「下次合作」为名长期压价、拖款的，要及时止损，见本章第 19 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（乙方）「这个新增功能不在原合同范围内，我们可以做，我先出一份补充报价和排期您看看。」","links":[],"evType":"经验共识"},"rq22-2":{"costText":"谈判前的准备时间。","gainText":"不在情面和压力下做出后悔的让步。","gainTrimmed":false,"remark":"底线是自己心里的，不要轻易告诉对方。","source":"Fisher, R., & Ury, W. (1981). Getting to Yes: Negotiating Agreement Without Giving In. Houghton Mifflin（「谈判协议的最佳替代方案」BATNA 的概念）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq22-3":{"costText":"做好市场调研。","gainText":"价格谈得更合理。","gainTrimmed":false,"remark":"开价离谱到没有依据，会让对方觉得你没有诚意，反而谈崩。","source":"Tversky, A., & Kahneman, D. (1974). Judgment under uncertainty: Heuristics and biases. Science, 185(4157), 1124–1131；…","sourceTrimmed":true,"tip":"「您报的价格比市场上同类服务高了 40%，按我们了解的行情和这次的工作量，我们的预算在 X 左右。」","links":[],"evType":"经验共识"},"rq22-4":{"costText":"顶住「再便宜点吧」的软磨硬泡。","gainText":"既给了对方面子，也守住了利润。","gainTrimmed":false,"remark":"人情可以体现在服务和态度上，不一定体现在价格上。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「价格可以再降 3%，但需要预付 50%，并且合同期签两年，您看可以吗？」","links":[],"evType":"经验共识"},"rq22-5":{"costText":"酒后多一次确认。","gainText":"避免空欢喜，也避免被别人拿你的醉话来追责。","gainTrimmed":false,"remark":"酒桌规矩见第 10 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「昨天跟您聊得很愉快，我把我们沟通的几点合作意向整理了一下，您看有没有出入？没问题的话我们推进合同。」","links":[],"evType":"经验共识"},"rq22-6":{"costText":"逐条阅读的耐心。","gainText":"把可能的纠纷提前堵住。","gainTrimmed":false,"remark":"大额、复杂的合同，花点钱请律师审一遍，比出了纠纷再打官司便宜得多。","source":"《民法典》第四百七十条（合同一般包括的条款：当事人、标的、数量、质量、价款或者报酬、履行期限地点和方式、违约责任、解决争议的方法）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq22-7":{"costText":"半小时的查询。","gainText":"避开皮包公司和老赖。","gainTrimmed":false,"remark":"对方不愿意提供营业执照、不让你核实身份的，本身就是危险信号。","source":"经验共识，本书整理；查询渠道为国家企业信用信息公示系统、中国执行信息公开网等官方平台。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq22-8":{"costText":"签约时多看几眼。","gainText":"合同真实有效，出了问题能找到人。","gainTrimmed":false,"remark":"一方已经履行了主要义务、对方也接受了的，即使没签字盖章，合同也可能成立。","source":"《民法典》第四百九十条（采用合同书形式订立合同的，自当事人均签名、盖章或者按指印时合同成立）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq22-9":{"costText":"签字前看清是哪个字。","gainText":"买房、装修、订婚宴、做生意时少吃亏。","gainTrimmed":false,"remark":"合同里同时约定了定金和违约金的，一方违约时，对方只能选择其中一种，见《民法典》第五百八十八条。","source":"《民法典》第五百八十六条（定金不得超过主合同标的额的 20%）、第五百八十七条（定金罚则）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq22-10":{"costText":"认真谈一谈违约条款。","gainText":"违约条款真正能执行。","gainTrimmed":false,"remark":"司法实践中常以「超过实际损失的 30%」作为是否过分高于损失的参考，具体以法院认定为准。","source":"《民法典》第五百八十五条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq22-11":{"costText":"可能少拿一些单子。","gainText":"生意做得干净，不给自己和公司埋雷。","gainTrimmed":false,"remark":"数额较大的，可能构成刑法上的对非国家工作人员行贿罪、非国家工作人员受贿罪，见第 29 章。","source":"《反不正当竞争法》（2025 年修订）第八条（禁止贿赂交易相对方工作人员等；可以明示支付折扣、佣金并如实入账）、第二十四条（罚款、没收违法所得等法律责任）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq22-12":{"costText":"可能失去这单生意。","gainText":"守住底线，也可能因此赢得对方公司的信任。","gainTrimmed":false,"remark":"对方是国家机关、国企工作人员的，向纪检监察机关反映，见第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我们公司有严格的合规要求，所有优惠都写在报价单里，您看价格上还有什么需要我们调整的？」","links":[],"evType":"经验共识"},"rq22-13":{"costText":"一份有心意的礼物。","gainText":"维护了关系，又不让对方为难。","gainTrimmed":false,"remark":"对方是公职人员的，按中央八项规定精神，基本不要送，见第 23 章、第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「一点家乡的特产，是我们公司给各位合作伙伴准备的，感谢一年来的支持，大家分一分。」","links":[],"evType":"经验共识"},"rq22-14":{"costText":"一顿饭的预算。","gainText":"关系建立在合作上，而不是把柄上。","gainTrimmed":false,"remark":"饭局的座次和点菜见第 9 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「今天就不去那边了，我知道附近有家茶馆挺安静的，我们换个地方再聊聊。」","links":[],"evType":"经验共识"},"rq22-15":{"costText":"几次「伤感情」的谈话和律师费。","gainText":"分歧出现时有规矩可依，兄弟也做得长久。","gainTrimmed":false,"remark":"股东协议里的约定和公司章程冲突的，可能引发纠纷，最好请律师统一起草。","source":"《公司法》（2023 年修订）第五条（设立公司应当依法制定公司章程）、第四十七条（有限责任公司认缴出资五年内缴足）、第二百一十条（利润一般按实缴出资比例分配，全体股东另有约定的除外）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq22-16":{"costText":"开口谈钱的不好意思。","gainText":"生意做成，交情也没伤。","gainTrimmed":false,"remark":"熟人帮忙涉及钱的，也可参考第 6 章第 9 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「咱们是自己人，我给你按成本价加 10%，比外面便宜两成。我们简单写个单子，你我都放心。」","links":[],"evType":"经验共识"},"rq22-17":{"costText":"拒绝朋友、合作方的尴尬。","gainText":"不因为别人的债务拖垮自己的家庭。","gainTrimmed":false,"remark":"夫妻一方对外担保的债务，是否属于夫妻共同债务，要看具体情况；亲戚之间的担保见第 12 章第 5 条。","source":"《民法典》第六百八十六条（保证方式没有约定或者约定不明确的，按照一般保证承担责任）、第六百八十八条（连带责任保证）。","sourceTrimmed":false,"tip":"「担保这件事我家里定过规矩，谁都不做，真不是针对你。你看看我能不能在别的方面帮上忙？」","links":[],"evType":"经验共识"},"rq22-18":{"costText":"多发一封邮件、多存一份记录。","gainText":"发生纠纷时有据可查。","gainTrimmed":false,"remark":"用聊天记录作为证据时，要能证明对方账号的真实身份，必要时可以做公证。","source":"《民法典》第四百六十九条（以电子数据交换、电子邮件等方式能够有形地表现所载内容，并可以随时调取查用的数据电文，视为书面形式）。","sourceTrimmed":false,"tip":"「刚才语音说的，我用文字确认一下：单价调整为 85 元，数量 2000 件，11 月 15 日前交货。没问题请回个『确认』。」","links":[],"evType":"经验共识"},"rq22-19":{"costText":"撕破脸的风险。","gainText":"钱要得回来，官司也打得赢。","gainTrimmed":false,"remark":"对方账上没钱、准备转移财产的，可以在起诉时申请财产保全。","source":"《民法典》第一百八十八条（诉讼时效期间为三年）、第一百九十五条（权利人向义务人提出履行请求、义务人同意履行等情形，诉讼时效中断）。","sourceTrimmed":false,"tip":"「按照合同约定，第二期款项 15 万元应于 9 月 30 日支付，至今未到账。请于 10 月 31 日前支付，逾期我方将按合同约定追究违约责任。」","links":[],"evType":"经验共识"},"rq22-20":{"costText":"可能得罪「圈子里的朋友」。","gainText":"远离一旦案发就会被一起查处的风险。","gainTrimmed":false,"remark":"《招标投标法》正在修订，具体条文以最新公布的版本为准。","source":"现行《招标投标法》第三十二条（禁止投标人相互串通或与招标人串通投标）；《刑法》第二百二十三条（串通投标罪）。","sourceTrimmed":false,"tip":"「这个项目我们评估了一下，不太适合参与，就不凑这个热闹了，谢谢你想着我们。」","links":[],"evType":"法条"},"rq22-21":{"costText":"收尾的耐心。","gainText":"不留后患，也不堵死后路。","gainTrimmed":false,"remark":"保密义务一般在合作结束后继续有效，按合同约定执行。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「合作期间感谢各位的支持。这是双方的对账单，确认无误后我们签一份终止确认书，以后有合适的机会再合作。」","links":[],"evType":"经验共识"},"rq22-22":{"costText":"听抱怨的耐心，可能的补偿。","gainText":"把一次危机变成一次信任。","gainTrimmed":false,"remark":"对方无理取闹、辱骂威胁的，保留记录，必要时报警，不必一味退让。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「给您添麻烦了，确实是我们的发货出了问题。今天下午我们重新补发，明天上午能到，运费我们承担，您看这样可以吗？」","links":[],"evType":"经验共识"},"rq23-1":{"costText":"花时间读制度、问前辈。","gainText":"少犯低级错误，也少被别人拿来当挡箭牌。","gainTrimmed":false,"remark":"党员干部还要学习《中国共产党纪律处分条例》（2023 年修订）等党内法规。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-2":{"costText":"留心观察。","gainText":"显得懂规矩、有分寸。","gainTrimmed":false,"remark":"称呼的一般规矩见第 3 章。","source":"《关于新形势下党内政治生活的若干准则》（2016 年）：党内一律称同志。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-3":{"costText":"写之前想清楚目的。","gainText":"上级好批，事情不卡。","gainTrimmed":false,"remark":"公文格式以国家标准《党政机关公文格式》（GB/T 9704）为准。","source":"《党政机关公文处理工作条例》（2012 年）关于向上级机关行文的规则：请示应当一文一事，不得在报告等非请示性公文中夹带请示事项。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-4":{"costText":"多走流程，多存档。","gainText":"干事有依据，追责有边界。","gainTrimmed":false,"remark":"程序是为了把事办好，不是为了推诿；该担当的事不能借程序拖着不办。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王局，您刚才交代的这件事，我拟个签报，您签一下字，我好按程序办。」","links":[],"evType":"经验共识"},"rq23-5":{"costText":"等待批复的时间。","gainText":"组织信任，自己安全。","gainTrimmed":false,"remark":"哪些人需要报告个人有关事项、报告哪些内容，以组织部门的具体要求为准。","source":"《中国共产党重大事项请示报告条例》（2019 年）；《领导干部报告个人有关事项规定》（2017 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-6":{"costText":"一点自律。","gainText":"给领导和同事留下稳重、可靠的印象。","gainTrimmed":false,"remark":"会议内容涉密的，不得录音、拍照，不得外传。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-7":{"costText":"查资料、反复修改的功夫。","gainText":"材料一次过，领导放心。","gainTrimmed":false,"remark":"材料可以借鉴，但不能整篇照抄其他单位的，被通报「抄袭」的案例并不少见。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-8":{"costText":"拒绝人情的尴尬。","gainText":"守住饭碗，也守住名声。","gainTrimmed":false,"remark":"收受财物数额较大、为他人谋取利益的，可能构成受贿罪，见第 29 章；送礼一方的风险见第 7 章第 9 条。","source":"《中国共产党纪律处分条例》（2023 年修订）第九十七条（收受可能影响公正执行公务的礼品、礼金、消费卡等财物）、第九十八条（向从事公务的人员及其亲属赠送礼品、礼金等）。","sourceTrimmed":false,"tip":"「谢谢您的心意，但我们有纪律，东西您一定得带回去。事情我会按规定尽快给您办好。」","links":[],"evType":"法条"},"rq23-9":{"costText":"推掉一些饭局。","gainText":"远离「吃人嘴软」的陷阱。","gainTrimmed":false,"remark":"各地对「违规吃喝」的认定口径不断细化，以当地纪委监委的通报和规定为准。","source":"《中国共产党纪律处分条例》（2023 年修订）第一百零一条（接受、提供可能影响公正执行公务的宴请或者旅游、健身、娱乐等活动安排）、第一百一十三条（用公款宴请、送礼）、第一百一十六条（超标准、超范围接待）；中央八项规定精神。","sourceTrimmed":false,"tip":"「饭就不吃了，有纪律要求。有什么问题，明天到办公室我们当面说。」","links":[],"evType":"法条"},"rq23-10":{"costText":"办得低调一些。","gainText":"喜事办得体面，也不留后患。","gainTrimmed":false,"remark":"具体的报告时限和规模标准，以本地区、本单位的规定为准；随礼一方的注意事项见第 8 章第 14 条。","source":"《中国共产党纪律处分条例》（2023 年修订）第一百条（利用职权或者职务上的影响操办婚丧喜庆事宜，借机敛财的从重处分）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq23-11":{"costText":"放弃一些「副业收入」。","gainText":"避免因为一点小钱丢了身份。","gainTrimmed":false,"remark":"事业单位、国有企业人员的兼职规定有所不同，以所在单位和主管部门的规定为准。","source":"《公务员法》第四十四条（机关外兼职须经批准，不得领取兼职报酬）、第五十九条（公务员不得违反有关规定从事或者参与营利性活动）；《中国共产党纪律处分条例》（2023 年修订）第一百零三条（违规从事营利活动）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq23-12":{"costText":"放弃经手一些事情。","gainText":"避免说不清的嫌疑。","gainTrimmed":false,"remark":"利用职权为亲属谋利，见《中国共产党纪律处分条例》（2023 年修订）第一百零四条。","source":"《公务员法》第七十四条（任职回避）、第七十六条（公务回避）、第七十七条（本人应当申请回避）。","sourceTrimmed":false,"tip":"「这家企业的负责人是我表哥，按规定我需要回避，这个项目请安排其他同志审核。」","links":[],"evType":"法条"},"rq23-13":{"costText":"放弃一些便利。","gainText":"不欠不该欠的人情。","gainTrimmed":false,"remark":"长期「借用」不还，可能被认定为受贿。","source":"《中国共产党纪律处分条例》（2023 年修订）第九十九条（借用管理和服务对象的钱款、住房、车辆等，可能影响公正执行公务的）。","sourceTrimmed":false,"tip":"「谢谢您，这个真不行，我们有规定。我自己想办法。」","links":[],"evType":"法条"},"rq23-14":{"costText":"自己掏钱打车。","gainText":"不因小失大。","gainTrimmed":false,"remark":"车辆使用以本单位公务用车管理制度为准。","source":"《中国共产党纪律处分条例》（2023 年修订）第一百一十二条（违规占用公物归个人使用）、第一百一十七条（违反公务交通工具管理规定）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-15":{"costText":"工作上的一些不便。","gainText":"避免一不小心就犯下严重错误。","gainTrimmed":false,"remark":"具体的定密、传递和存储要求，以本单位保密部门的规定为准。","source":"《保守国家秘密法》（2024 年修订）关于禁止通过互联网及其他公共信息网络传递国家秘密等规定；《公务员法》第五十九条第十一项（不得泄露国家秘密或者工作秘密）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq23-16":{"costText":"少一些表达的痛快。","gainText":"不让自己成为舆情的主角。","gainTrimmed":false,"remark":"网络社交的一般规矩见第 26 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-17":{"costText":"可能得罪托你的人。","gainText":"既帮了能帮的，又没碰不能碰的。","gainTrimmed":false,"remark":"托关系办事给好处的，见第 29 章。","source":"《领导干部干预司法活动、插手具体案件处理的记录、通报和责任追究规定》《司法机关内部人员过问案件的记录和责任追究规定》（2015 年）等。","sourceTrimmed":false,"tip":"「这个事我不方便过问，您按正常程序去申请，有什么不清楚的流程我可以帮您问问。」","links":[],"evType":"经验共识"},"rq23-18":{"costText":"等待和耐心。","gainText":"提拔得踏实，坐得也稳。","gainTrimmed":false,"remark":"有人声称「能帮忙运作提拔」并索要钱财的，多半是诈骗，见第 30 章。","source":"《公务员法》第四十六条（晋升领导职务的程序）；《党政领导干部选拔任用工作条例》（2019 年修订）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq23-19":{"costText":"放弃一部分「旋转门」的机会。","gainText":"离开得干净，不留尾巴。","gainTrimmed":false,"remark":"事业单位、国有企业人员的从业限制，以相关规定为准。","source":"《公务员法》第一百零七条；《中国共产党纪律处分条例》（2023 年修订）第一百零五条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq23-20":{"costText":"多一点耐心。","gainText":"群众满意，自己也少惹麻烦。","gainTrimmed":false,"remark":"从群众的角度如何去政府部门办事，见第 24 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq23-21":{"costText":"走程序的时间和勇气。","gainText":"用制度保护自己。","gainTrimmed":false,"remark":"事业单位工作人员、国有企业职工适用不同的救济渠道，前者见《事业单位人事管理条例》，后者一般适用劳动争议仲裁。","source":"《公务员法》第九十五条（复核与申诉）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq24-1":{"costText":"出门前半小时的准备。","gainText":"争取「一次办成」。","gainTrimmed":false,"remark":"同一件事各地要求可能不同，以当地的办事指南为准。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq24-2":{"costText":"一点耐心。","gainText":"事半功倍。","gainTrimmed":false,"remark":"工作人员态度恶劣、故意刁难的，见本章第 4 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「您好，我来办新生儿落户，出生证明、户口本、父母身份证和结婚证都带了，麻烦您看看还缺什么。」","links":[],"evType":"经验共识"},"rq24-3":{"costText":"开口要求一次说清。","gainText":"少跑冤枉路。","gainTrimmed":false,"remark":"多次补材料仍然不受理的，可以投诉，见本章第 4 条。","source":"《行政许可法》第三十二条第一款第四项。","sourceTrimmed":false,"tip":"「麻烦您把需要补充的材料一次性给我列一下，我回去一起准备，免得再跑一趟。」","links":[],"evType":"法条"},"rq24-4":{"costText":"投诉的勇气和时间。","gainText":"用正规渠道解决问题，而不是吵一架。","gainTrimmed":false,"remark":"工作人员索要好处费的，向当地纪委监委举报。","source":"《国务院办公厅关于建立政务服务「好差评」制度提高政务服务水平的意见》（2019 年）；各地 12345 政务服务便民热线。","sourceTrimmed":false,"tip":"「我理解您的难处。能不能告诉我这是依据哪个文件，或者我应该去哪个部门办？」","links":[],"evType":"官方文件"},"rq24-5":{"costText":"放下「找个熟人更快」的念头。","gainText":"既办了事，又不欠不必要的人情。","gainTrimmed":false,"remark":"托关系办事给好处的风险，见第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我不是要你帮忙走后门，就是想问问这个事该找哪个部门、要准备哪些材料。」","links":[],"evType":"经验共识"},"rq24-6":{"costText":"准备材料和等待的时间。","gainText":"用法律手段纠正错误的决定。","gainTrimmed":false,"remark":"行政复议不收费，可以通过网上平台申请；也可以找法律援助（12348）咨询。","source":"《行政复议法》（2023 年修订）关于申请期限的规定；《行政诉讼法》第四十六条（直接起诉的，自知道或者应当知道作出行政行为之日起六个月内提出）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq24-7":{"costText":"漫长的等待。","gainText":"诉求被正式受理，而不是被当成「闹事」。","gainTrimmed":false,"remark":"可以通过国家信访局网站和各地网上信访平台提交，方便查询办理进度。","source":"《信访工作条例》（2022 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq24-8":{"costText":"写一份申请。","gainText":"用公开的规则保护自己的权益。","gainTrimmed":false,"remark":"涉及国家秘密、商业秘密、个人隐私的信息，依法可以不公开或者部分公开。","source":"《政府信息公开条例》（2019 年修订）关于依申请公开的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq24-9":{"costText":"保留凭证、多跑几步。","gainText":"花出去的钱有保障。","gainTrimmed":false,"remark":"经营者有欺诈行为的，消费者可以要求增加赔偿，增加的金额为价款的三倍，不足五百元的为五百元，见该法第五十五条。","source":"《消费者权益保护法》第二十五条（网购七日无理由退货）、第三十九条（消费争议的解决途径）。","sourceTrimmed":false,"tip":"「这件商品和页面描述的材质不符，我要求退货退款，否则我将向 12315 投诉。」","links":[],"evType":"法条"},"rq24-10":{"costText":"出门前的十分钟。","gainText":"一次看明白，少走弯路。","gainTrimmed":false,"remark":"陪父母看病，事先帮他们整理好这些信息。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「医生，我最想弄清楚两件事：这个病要不要做手术？这个药要吃多久？」","links":[],"evType":"经验共识"},"rq24-11":{"costText":"放下「不送不放心」的焦虑。","gainText":"省钱，也不让医生为难。","gainTrimmed":false,"remark":"医务人员索要红包的，可以向医院纪检监察部门或者卫生健康部门举报；感谢医生的方式见第 7 章第 11 条。","source":"《医疗机构工作人员廉洁从业九项准则》（2021 年）：不收受患者及其亲友的礼品、礼金、消费卡等财物。","sourceTrimmed":false,"tip":"「谢谢您这些天的照顾，这是我们一家人写的感谢信。」","links":[],"evType":"经验共识"},"rq24-12":{"costText":"冷静下来的克制，和漫长的程序。","gainText":"证据在手，才谈得上维权。","gainTrimmed":false,"remark":"疑似输液、用药引起不良后果的，医患双方应当共同封存现场实物，见该条例第二十五条。","source":"《医疗纠纷预防和处理条例》（2018 年）第十六条（查阅、复制病历）、第二十二条（解决途径）、第二十四条（封存病历）。","sourceTrimmed":false,"tip":"「我们要求复印全部病历，并在双方在场的情况下封存病历原件。」","links":[],"evType":"法条"},"rq24-13":{"costText":"咽下悲痛和愤怒。","gainText":"既不让自己陷入法律麻烦，又不耽误维权。","gainTrimmed":false,"remark":"医疗纠纷的正确处理方法见本章第 12 条。","source":"《刑法》第二百九十条第一款（聚众扰乱社会秩序，致使医疗无法进行，造成严重损失的，构成犯罪）；《基本医疗卫生与健康促进法》关于医疗卫生机构执业场所秩序受法律保护的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq24-14":{"costText":"一点耐心和克制。","gainText":"家校一条心，孩子受益。","gainTrimmed":false,"remark":"老师有体罚、侮辱学生等行为的，可以向学校和教育行政部门反映。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师，孩子回家说今天课间和同学有点矛盾，我想跟您了解一下情况，看看我们在家怎么配合。」","links":[],"evType":"经验共识"},"rq24-15":{"costText":"放下「别人都送了」的焦虑。","gainText":"不攀比，也不给老师添麻烦。","gainTrimmed":false,"remark":"高校、幼儿园教师也有相应的职业行为准则；感谢老师的方式也可参考第 7 章第 10 条。","source":"《新时代中小学教师职业行为十项准则》（2018 年）：不得索要、收受学生及家长财物。","sourceTrimmed":false,"tip":"「我们家就让孩子写张卡片给老师了，礼物就不参与了，谢谢您组织。」","links":[],"evType":"经验共识"},"rq24-16":{"costText":"管住手。","gainText":"群里清净，大家都舒服。","gainTrimmed":false,"remark":"微信群的一般规矩见第 26 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq24-17":{"costText":"处理的时间和心力。","gainText":"及时制止伤害，保护孩子。","gainTrimmed":false,"remark":"孩子被欺凌后情绪低落、不愿上学的，要重视心理疏导，必要时寻求专业帮助。","source":"《未成年人保护法》（2020 年修订）关于学校建立学生欺凌防控工作制度的规定。","sourceTrimmed":false,"tip":"「孩子这两周三次被同班同学推倒，这是就医记录。我们请学校按欺凌防控制度调查处理，并书面告知处理结果。」","links":[],"evType":"经验共识"},"rq24-18":{"costText":"压住护犊子的冲动。","gainText":"孩子学会处理冲突，家长也不结仇。","gainTrimmed":false,"remark":"如果是持续的欺凌，见本章第 17 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对孩子）「你慢慢说，当时发生了什么？他为什么推你？你那时候在做什么？」","links":[],"evType":"经验共识"},"rq24-19":{"costText":"冷静地说几分钟。","gainText":"案件能被及时受理、跟进。","gainTrimmed":false,"remark":"遭遇电信网络诈骗的，同时拨打 96110 并联系银行止付，见第 30 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我要报案，今天下午三点左右，我在某某小区门口被人抢了手机，对方是一名穿黑色外套的男子，往东边跑了。」","links":[],"evType":"经验共识"},"rq24-20":{"costText":"诉讼费和时间。","gainText":"用法律手段解决纠纷。","gainTrimmed":false,"remark":"经济困难的，可以申请缓交、减交、免交诉讼费，或者申请法律援助（12348）。","source":"《最高人民法院关于人民法院登记立案若干问题的规定》（2015 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq24-21":{"costText":"一条评价或一封感谢信。","gainText":"善意被看见，下一个人也会被善待。","gainTrimmed":false,"remark":"表扬要具体，写清楚时间、窗口号或者姓名，以及具体做了什么。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-1":{"costText":"一点小礼物和几分钟寒暄。","gainText":"为以后的相处打下基础。","gainTrimmed":false,"remark":"不想深交也没关系，见面点头打招呼就够了。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「您好，我们是新搬来 1202 的，接下来装修可能会有点吵，给您添麻烦了。这是我的电话，有什么问题随时找我。」","links":[],"evType":"经验共识"},"rq25-2":{"costText":"工期可能长一点。","gainText":"邻居体谅，装修顺利。","gainTrimmed":false,"remark":"具体的施工时间以当地规定和小区管理规约为准。","source":"《民法典》第九百四十五条（业主装修应当事先告知物业服务人）；《噪声污染防治法》第六十六条（室内装修应当按照规定限定作业时间）。","sourceTrimmed":false,"tip":"（告示）「1202 室将于 3 月 1 日至 5 月 30 日装修，施工时间为工作日 8:30—12:00、14:00—18:00，给大家带来不便，敬请谅解。…","links":[],"evType":"法条"},"rq25-3":{"costText":"改变一些生活习惯。","gainText":"不被投诉，邻里和睦。","gainTrimmed":false,"remark":"老房子隔音差，即使正常生活也可能影响邻居，互相体谅很重要。","source":"《噪声污染防治法》第六十五条（家庭及其成员应当减少噪声，控制音量）、第八十八条（夜间是指晚上十点至次日早晨六点）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq25-4":{"costText":"敲门的勇气，和反复沟通的耐心。","gainText":"问题解决，关系还在。","gainTrimmed":false,"remark":"可以用手机录下噪声的时间和分贝，作为反映问题的依据。","source":"《噪声污染防治法》第六十九条（通过管理规约约定噪声防治要求）、第八十七条（经劝阻、调解和处理未能制止、持续干扰他人的，由公安机关依法给予治安管理处罚）。","sourceTrimmed":false,"tip":"「不好意思打扰您，最近晚上十一点以后楼上经常有拖椅子的声音，孩子总被吵醒，能不能麻烦您晚上注意一下？」","links":[],"evType":"法条"},"rq25-5":{"costText":"维修费和赔偿款。","gainText":"把一件可能结仇的事，变成一次信任。","gainTrimmed":false,"remark":"买了家庭财产保险或者房屋责任险的，及时报案理赔。","source":"《民法典》第二百八十八条（处理相邻关系的原则）。","sourceTrimmed":false,"tip":"「真对不起，物业查了是我们家卫生间防水的问题，我们这周就修。您家天花板的损失我们来承担，您看是我们找人修，还是折算成钱给您？」","links":[],"evType":"经验共识"},"rq25-6":{"costText":"遛狗时多一份责任心。","gainText":"既不伤人，也不被伤。","gainTrimmed":false,"remark":"各地养犬管理条例对登记、免疫、禁养犬种有具体规定，以当地为准。","source":"《民法典》第一千二百四十五条至第一千二百四十七条（饲养动物损害责任）、第一千二百五十一条（饲养动物不得妨碍他人生活）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-7":{"costText":"家里少放点东西，或者多花点心思收纳。","gainText":"保住全楼人的逃生通道。","gainTrimmed":false,"remark":"物业有义务对违反消防法规的行为及时制止并报告，见《民法典》第九百四十二条。","source":"《消防法》第二十八条（不得占用、堵塞、封闭疏散通道、安全出口、消防车通道）。","sourceTrimmed":false,"tip":"「王阿姨，楼道里这几个箱子放着不太安全，万一着火了大家都不好跑，要不我帮您搬回家里？」","links":[],"evType":"法条"},"rq25-8":{"costText":"去集中充电点充电的麻烦。","gainText":"远离最常见的居民楼火灾隐患。","gainTrimmed":false,"remark":"各地对电动自行车停放充电另有规定，以当地为准。","source":"应急管理部《高层民用建筑消防安全管理规定》（2021 年）关于禁止在公共门厅、疏散走道、楼梯间、安全出口停放电动自行车或为其充电的规定。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-9":{"costText":"多绕几圈找车位。","gainText":"不为一个车位结下梁子。","gainTrimmed":false,"remark":"小区停车的具体管理办法，由业主共同决定或者按管理规约执行。","source":"《民法典》第二百七十五条（车位、车库的归属由当事人约定；占用业主共有道路停车的车位属于业主共有）。","sourceTrimmed":false,"tip":"（留言条）「您好，这是我的固定车位，麻烦您下次停到访客车位，谢谢！电话：138xxxx。」","links":[],"evType":"经验共识"},"rq25-10":{"costText":"多走几步扔垃圾。","gainText":"不伤人，也不让自己和邻居一起「连坐」。","gainTrimmed":false,"remark":"物业服务企业应当采取必要的安全保障措施防止高空抛物，未采取的要承担相应责任。","source":"《民法典》第一千二百五十四条（禁止从建筑物中抛掷物品）；《刑法》第二百九十一条之二（高空抛物罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-11":{"costText":"调整一下安装角度。","gainText":"防盗不变成「防邻居」。","gainTrimmed":false,"remark":"已经有法院判决认定，正对邻居家门的摄像头侵犯了邻居的隐私权，要求拆除或调整。","source":"《民法典》第一千零三十三条（未经同意不得拍摄、窥视他人的住宅等私密空间）。","sourceTrimmed":false,"tip":"「您家装的摄像头好像正对着我们家门，能不能麻烦您调一下角度？」","links":[],"evType":"经验共识"},"rq25-12":{"costText":"每月的物业费。","gainText":"既不吃亏，也不被告上法庭。","gainTrimmed":false,"remark":"物业确实没有按合同提供服务、造成损失的，可以要求减免或赔偿，留好证据。","source":"《民法典》第九百四十四条（业主应当支付物业费；物业不得以停止供水供电等方式催交）、第二百七十七条（业主可以设立业主大会，选举业主委员会）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-13":{"costText":"说服邻居的时间，或者放弃一部分收益。","gainText":"避免被邻居起诉、被责令停业。","gainTrimmed":false,"remark":"各地对民宿、短租、群租另有管理规定，以当地为准。","source":"《民法典》第二百七十九条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-14":{"costText":"记得归还的细心。","gainText":"邻里之间有来有往。","gainTrimmed":false,"remark":"借朋友东西的规矩见第 16 章第 16 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「上次借您的电钻用完了，充好电了，谢谢啊！」","links":[],"evType":"经验共识"},"rq25-15":{"costText":"一点麻烦。","gainText":"帮了忙，也不惹麻烦。","gainTrimmed":false,"remark":"不要私自拆开邻居的快递。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「你的快递我帮你收了，外包装是好的，放在我家门口了，你回来记得拿哈。」","links":[],"evType":"经验共识"},"rq25-16":{"costText":"一份小礼，或者一句问候。","gainText":"远亲不如近邻，人情就在这些时候。","gainTrimmed":false,"remark":"随礼的一般分寸见第 8 章；各地丧葬习俗见第 27 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「听说您家孩子考上大学了，真替你们高兴！一点心意，给孩子买本书。」","links":[],"evType":"经验共识"},"rq25-17":{"costText":"放下面子，请第三方来调解。","gainText":"既有人主持公道，又不至于对簿公堂。","gainTrimmed":false,"remark":"对方有人身威胁、故意损坏财物的，直接报警。","source":"《人民调解法》第四条（人民调解不收取任何费用）、第三十三条（调解协议的司法确认）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq25-18":{"costText":"一点留心。","gainText":"一份小小的善意，可能救一条命。","gainTrimmed":false,"remark":"发现老人可能出事又联系不上家属的，及时报警或者联系社区。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「李奶奶，这是我的电话，家里有什么事、身体不舒服，随时给我打。」","links":[],"evType":"经验共识"},"rq25-19":{"costText":"一点小心。","gainText":"少一些背后的抱怨。","gainTrimmed":false,"remark":"被楼上滴水、烟味持续影响的，可以参考本章第 4 条的步骤处理。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq25-20":{"costText":"互相让一步。","gainText":"几代人的邻居关系不至于毁于一堵墙。","gainTrimmed":false,"remark":"宅基地的使用权纠纷，可以先申请乡镇人民政府处理。","source":"《民法典》第二百九十条（用水、排水的便利）、第二百九十一条（通行的便利）、第二百九十三条（不得妨碍相邻建筑物的通风、采光和日照）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq25-21":{"costText":"咽下想「曝光」的那口气。","gainText":"不让小矛盾变成官司。","gainTrimmed":false,"remark":"小区群里的言论规矩见第 26 章。","source":"《民法典》第一千零二十四条（任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-1":{"costText":"多打一行字。","gainText":"对方愿意通过，也知道怎么回应你。","gainTrimmed":false,"remark":"通过好友后，不要马上发广告或者转发投票链接。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师您好，我是某某公司的小李，张总介绍我向您请教一下数据合规的问题。」","links":[],"evType":"经验共识"},"rq26-2":{"costText":"把事情一次讲清楚。","gainText":"省去来回的猜测。","gainTrimmed":false,"remark":"工作消息的写法见第 17 章第 11 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「李姐，想问一下上次那家装修公司的联系方式，你方便的时候发我就行，不急。」","links":[],"evType":"经验共识"},"rq26-3":{"costText":"多花一点时间打字。","gainText":"对方方便，信息也不容易出错。","gainTrimmed":false,"remark":"长辈不方便打字的，可以用语音转文字功能，给他们发消息时也可以配一段语音。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-4":{"costText":"一个个写的时间。","gainText":"一条用心的祝福，胜过一百条群发。","gainTrimmed":false,"remark":"收到群发的祝福，简单回复一句「同乐」即可，不必纠结；拜年消息的写法见第 11 章第 9 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「张老师，春节快乐！去年您推荐的那本书我读完了，受益很大。祝您和师母新年身体健康！」","links":[],"evType":"经验共识"},"rq26-5":{"costText":"随手一条回复。","gainText":"显得靠谱，事情也有闭环。","gainTrimmed":false,"remark":"工作群里没有 @ 你的通知类消息，按单位习惯处理，不一定都要回复。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「收到，今天下午五点前把修改后的版本发群里。」","links":[],"evType":"经验共识"},"rq26-6":{"costText":"管住手。","gainText":"群里的信息不被淹没，大家都省心。","gainTrimmed":false,"remark":"工作群里讨论的内部信息，不要截图外传，见第 17 章第 16 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-7":{"costText":"克制住「想到就发」的习惯。","gainText":"尊重别人的休息时间，别人也会尊重你。","gainTrimmed":false,"remark":"下班后收到工作消息怎么回，见第 17 章第 15 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（真紧急时）「抱歉这么晚打扰，客户那边系统崩了，需要你帮忙看一下。」","links":[],"evType":"经验共识"},"rq26-8":{"costText":"多发一条私信。","gainText":"别人不反感，群也好管理。","gainTrimmed":false,"remark":"不想待的群，可以安静地退出，不必在群里宣布。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我们准备建个同学聚会的筹备群，就讨论时间地点，聚完就解散，拉你进来可以吗？」","links":[],"evType":"经验共识"},"rq26-9":{"costText":"一点管理的精力。","gainText":"群不变成违法信息的集散地，自己也少担风险。","gainTrimmed":false,"remark":"在群里写好群规并置顶，处理起来有据可依。","source":"国家互联网信息办公室《互联网群组信息服务管理规定》（2017 年）第九条（群组建立者、管理者应当履行群组管理责任）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq26-10":{"costText":"多写一行备注。","gainText":"账目清楚，也避开「转错账」类的骗局。","gainTrimmed":false,"remark":"大额借款还是要写借条，见第 28 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（转账备注）「借款 5000 元，约定 2026 年 12 月 31 日前归还。」","links":[],"evType":"经验共识"},"rq26-11":{"costText":"克制住分享的冲动。","gainText":"做一个让人敢说真话的人。","gainTrimmed":false,"remark":"自己说的话也要按「可能被截图」来把握分寸。","source":"《民法典》第一千零三十二条（自然人享有隐私权，任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-12":{"costText":"发之前多看一眼。","gainText":"分享生活，也守住安全。","gainTrimmed":false,"remark":"晒别人的孩子和照片，先征得家长或本人同意。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-13":{"costText":"评论前想一想。","gainText":"不在公开场合闹出尴尬。","gainTrimmed":false,"remark":"长辈转发的谣言怎么劝，见第 13 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-14":{"costText":"放弃「隔空喊话」的快感。","gainText":"保住体面，也给关系留余地。","gainTrimmed":false,"remark":"内容指向明确、带有侮辱诽谤的，可能构成侵权，见本章第 16 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-15":{"costText":"转发前搜一搜。","gainText":"不当谣言的二传手。","gainTrimmed":false,"remark":"可以通过中国互联网联合辟谣平台等渠道核实信息。","source":"《治安管理处罚法》（2025 年修订）第二十九条（故意散布谣言，谎报险情、疫情、灾情、警情或者以其他方法故意扰乱公共秩序的处罚）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq26-16":{"costText":"管住情绪。","gainText":"不因一时口快惹上官司。","gainTrimmed":false,"remark":"基于事实的批评和正当的舆论监督，不属于侵权。","source":"《民法典》第一千零二十四条（名誉权）；《治安管理处罚法》（2025 年修订）第五十条第一款第二项；最高人民法院、最高人民检察院《关于办理利用信息网络实施诽谤等刑事案件适用法律若干问题的解释》（2013 年）第二条；《刑法》第二百四十六条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq26-17":{"costText":"面对恶意的心理压力。","gainText":"止住伤害，让施暴者付出代价。","gainTrimmed":false,"remark":"心理上撑不住的，及时寻求心理咨询或拨打心理援助热线。","source":"国家网信办等《网络暴力信息治理规定》（2024 年 8 月 1 日起施行）第二十三条（防护选项）、第二十五条（快捷取证）、第二十六条（投诉举报入口）；《民法典》第一千一百九十五条（权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq26-18":{"costText":"放下「替天行道」的冲动。","gainText":"不变成网暴的一部分。","gainTrimmed":false,"remark":"自己的个人信息被泄露的，可以要求平台删除，并向网信部门投诉。","source":"《治安管理处罚法》（2025 年修订）第五十六条（向他人出售或者提供个人信息的处罚）；《刑法》第二百五十三条之一（侵犯公民个人信息罪）；《个人信息保护法》。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq26-19":{"costText":"可能被说「不够意思」。","gainText":"保护个人信息，也不消耗人情。","gainTrimmed":false,"remark":"要求先付钱才能「领取奖品」的，基本都是诈骗，见第 30 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我手机设置了不点外部链接，这次就不帮你砍了哈，祝你砍成功！」","links":[],"evType":"经验共识"},"rq26-20":{"costText":"放下「要让他知道」的执念。","gainText":"保护自己，也不制造新的冲突。","gainTrimmed":false,"remark":"对方有骚扰、威胁行为的，拉黑之前先保存好聊天记录。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-21":{"costText":"多一份防范。","gainText":"网友见面不变成危险经历。","gainTrimmed":false,"remark":"杀猪盘和婚恋诈骗的识别见第 30 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq26-22":{"costText":"花十分钟做一次设置。","gainText":"账号不被盗用，也不被别人拿去干坏事。","gainTrimmed":false,"remark":"出借账号、银行卡可能构成帮助信息网络犯罪活动罪，见第 30 章第 22 条。","source":"《反电信网络诈骗法》第三十一条（不得非法买卖、出租、出借互联网账号、支付账户等，不得提供实名核验帮助）。","sourceTrimmed":false,"tip":"「验证码是登录我账号用的，谁问都不能给，你直接找客服吧。」","links":[],"evType":"法条"},"rq27-1":{"costText":"放下「怕显得不懂」的面子。","gainText":"少犯错，还显得有心。","gainTrimmed":false,"remark":"同一个省里不同县市的习俗也可能差别很大，不要以偏概全。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我第一次参加你们这边的婚礼，不太懂规矩，礼金一般随多少？有什么要注意的吗？」","links":[],"evType":"经验共识"},"rq27-2":{"costText":"点菜和送礼时多留意。","gainText":"对方感受到被尊重。","gainTrimmed":false,"remark":"不要因为对方的民族就预设他一定有什么习惯，问一句最稳妥。","source":"《宪法》第四条（各民族都有保持或者改革自己的风俗习惯的自由）。","sourceTrimmed":false,"tip":"「我们订了一家清真餐厅，你看可以吗？」","links":[],"evType":"法条"},"rq27-3":{"costText":"认真准备的心思。","gainText":"第一印象稳稳的。","gainTrimmed":false,"remark":"见家长的更多细节见第 14 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（问伴侣）「你爸妈喜欢什么？你们那边第一次上门有没有什么讲究，比如要不要包红包？」","links":[],"evType":"经验共识"},"rq27-4":{"costText":"艰难的谈判。","gainText":"习俗不变成婚姻的绊脚石。","gainTrimmed":false,"remark":"彩礼的具体处理见第 14 章。","source":"《民法典》第一千零四十二条（禁止借婚姻索取财物）；《最高人民法院关于审理涉彩礼纠纷案件适用法律若干问题的规定》（2024 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-5":{"costText":"可能被说「玩不起」。","gainText":"喜事办得开心，也不留遗憾。","gainTrimmed":false,"remark":"闹婚中对他人实施猥亵、伤害的，同样要承担法律责任。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（新人提前说）「我们这次婚礼不搞闹伴娘那一套，大家吃好喝好，玩点轻松的游戏就行。」","links":[],"evType":"经验共识"},"rq27-6":{"costText":"一身合适的衣服。","gainText":"对逝者和家属表达尊重。","gainTrimmed":false,"remark":"有宗教信仰的家庭，可能按宗教仪式办理，遵从其仪式。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-7":{"costText":"克制住好奇和想安慰的冲动。","gainText":"真正的安慰，是陪伴而不是说教。","gainTrimmed":false,"remark":"白事礼金的分寸见本章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「阿姨，您节哀。叔叔的事我们都很难过，这几天有什么需要跑腿的，您随时叫我。」","links":[],"evType":"经验共识"},"rq27-8":{"costText":"问一问当地的规矩。","gainText":"不在别人最难的时候添堵。","gainTrimmed":false,"remark":"随份子的一般原则见第 8 章，红白事礼金单双数的讲究见第 8 章第 2 条。","source":"经验共识，本书整理；以当地习俗为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-9":{"costText":"一点留心。","gainText":"尊重别人的信仰，也不让自己尴尬。","gainTrimmed":false,"remark":"烧香、捐功德不是必须的，警惕景区里诱导高价请香、算命的骗局。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-10":{"costText":"先听当地人怎么叫。","gainText":"一开口就不失礼。","gainTrimmed":false,"remark":"称呼的一般规矩见第 3 章；送礼的谐音忌讳见第 7 章第 4 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「您好，请问怎么称呼您比较合适？」","links":[],"evType":"经验共识"},"rq27-11":{"costText":"一次提前的沟通。","gainText":"过年不再成为吵架的导火索。","gainTrimmed":false,"remark":"过年的其他人情见第 11 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「今年我们先在你家过年三十，初二回我家，你看你爸妈能接受吗？」","links":[],"evType":"经验共识"},"rq27-12":{"costText":"和长辈沟通的耐心。","gainText":"既保住健康，又不伤长辈的心。","gainTrimmed":false,"remark":"和父母意见不同时的沟通方法，见第 13 章。","source":"经验共识，本书整理；产后保健以医生建议为准。","sourceTrimmed":false,"tip":"「妈，谢谢您这么用心照顾我。医生说可以用温水擦身、保持通风，我们就按医生说的来，您帮我盯着别着凉就行。」","links":[],"evType":"经验共识"},"rq27-13":{"costText":"改一改习惯。","gainText":"缅怀亲人，也不留安全隐患。","gainTrimmed":false,"remark":"因为祭祀用火引发火灾的，要承担法律责任。","source":"经验共识，本书整理；以当地森林防火和殡葬管理规定为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-14":{"costText":"放下一些「段子」。","gainText":"不在无意中得罪人。","gainTrimmed":false,"remark":"被别人地域黑时，可以平静地表示「我不太喜欢这种说法」。","source":"Allport, G. W. (1954). The Nature of Prejudice. Addison-Wesley（刻板印象与偏见的形成及其对人际关系的影响）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-15":{"costText":"一两天的时间和力气。","gainText":"在老家的人情网里有一席之地。","gainTrimmed":false,"remark":"人情账的一般规律见第 6 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「叔，我今天没什么事，帮您看着点礼账吧，有什么要搬的也叫我。」","links":[],"evType":"经验共识"},"rq27-16":{"costText":"适应的过程。","gainText":"更快地融入，少一些「外地人」的隔阂。","gainTrimmed":false,"remark":"被本地人排斥或歧视的，见本章第 14 条，不必忍气吞声。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-17":{"costText":"留心观察。","gainText":"吃得舒服，也不失礼。","gainTrimmed":false,"remark":"饭局和酒桌的一般规矩见第 9 章、第 10 章。","source":"经验共识，本书整理；以当地习俗为准。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq27-18":{"costText":"顶住「老规矩」的压力。","gainText":"不因为「随大流」而触犯法律。","gainTrimmed":false,"remark":"遇到逼婚、包办婚姻的，可以向妇联（12338）、民政部门求助。","source":"《民法典》第一千零四十二条（禁止包办、买卖婚姻，禁止借婚姻索取财物）、第一千零四十七条（法定婚龄）；《刑法》第三百零二条（盗窃、侮辱、故意毁坏尸体、尸骨、骨灰罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq27-19":{"costText":"做两边的「翻译官」。","gainText":"减少误会，让两边都感到被尊重。","gainTrimmed":false,"remark":"跨文化婚恋中的分歧，夫妻双方要站在一起解决，见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对父母）「她那边过年不兴给红包，她要是没准备，你们别多想，她心意都在礼物里了。」","links":[],"evType":"经验共识"},"rq27-20":{"costText":"在新旧之间找平衡。","gainText":"既守住了人情，又不被旧俗绑架。","gainTrimmed":false,"remark":"民政部门近年在多地推动婚俗改革，倡导简约适度的婚礼。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「爸，我们这次婚礼想办得简单一点，省下的钱给你们换个好点的空调，您看亲戚那边您帮我们解释解释？」","links":[],"evType":"经验共识"},"rq28-1":{"costText":"在慌乱中保持冷静。","gainText":"既保护了自己，又不丢掉维权的机会。","gainTrimmed":false,"remark":"紧急情况下可以使用手机的紧急呼叫功能，或者向身边的人大声求助。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-2":{"costText":"养成记录的习惯。","gainText":"报警、投诉、打官司时，事实一目了然。","gainTrimmed":false,"remark":"时间线可以写在手机备忘录里，定期发到自己的邮箱备份。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-3":{"costText":"一部手机。","gainText":"口头说过的话也有据可查。","gainTrimmed":false,"remark":"录音的合法性最终由法院认定；录下的内容不要随意公开传播，以免侵犯隐私。","source":"《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百零六条。","sourceTrimmed":false,"tip":"（录音中自然地确认）「王总，你说的意思是，上个月的提成这个月也不发了，对吗？」","links":[],"evType":"法条"},"rq28-4":{"costText":"一点存储空间，可能的公证费。","gainText":"证据经得起质疑。","gainTrimmed":false,"remark":"用聊天记录作证时，要能证明对方账号的身份，例如截图中包含对方的个人资料页。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-5":{"costText":"去医院和派出所的时间。","gainText":"伤害有人担责，赔偿也有依据。","gainTrimmed":false,"remark":"在公安机关主持下调解达成协议的，要写清赔偿金额和履行时间。","source":"《治安管理处罚法》（2025 年修订）第五十一条（殴打他人或者故意伤害他人身体的处罚）；《刑法》第二百三十四条（故意伤害罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-6":{"costText":"在危急时刻保持判断。","gainText":"保护自己，也不让自己从受害者变成被告。","gainTrimmed":false,"remark":"是否构成正当防卫，由司法机关综合全案认定。","source":"《刑法》第二十条；最高人民法院、最高人民检察院、公安部《关于依法适用正当防卫制度的指导意见》（2020 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-7":{"costText":"报警和取证的精力。","gainText":"让对方知道你不是好欺负的。","gainTrimmed":false,"remark":"对方的行为升级为暴力、非法拘禁的，可能构成犯罪，立即报警。","source":"《治安管理处罚法》（2025 年修订，2026 年 1 月 1 日起施行）第五十条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-8":{"costText":"彻底断开的决心。","gainText":"用法律划出一条对方不能越过的线。","gainTrimmed":false,"remark":"男性遭受前任纠缠骚扰的，同样可以报警，并依据民法典申请禁令。","source":"《妇女权益保障法》第二十九条（禁止在终止恋爱关系、离婚之后纠缠、骚扰，可以申请人身安全保护令）；《民法典》第九百九十七条（人格权侵害禁令）；《治安管理处罚法》（2025 年修订）第五十条。","sourceTrimmed":false,"tip":"（最后一条消息）「我们已经分手了，我不会复合。请不要再联系我和我的家人，否则我会报警并申请保护令。」","links":[],"evType":"法条"},"rq28-9":{"costText":"迈出第一步的勇气。","gainText":"打破「忍一忍就过去了」的循环。","gainTrimmed":false,"remark":"妇女维权公益服务热线 12338；违反保护令的，可能被罚款、拘留，构成犯罪的追究刑事责任。","source":"《反家庭暴力法》第十六条（告诫书）、第二十三条（申请人身安全保护令）、第二十八条（72 小时、紧急情况 24 小时内作出）、第二十九条（保护令的措施）、第三十条（有效期不超过六个月，可以延长）、第三十七条（家庭成员以外共同生活的人之间的暴力参照执行）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-10":{"costText":"说出来的勇气。","gainText":"保护自己，也阻止对方伤害下一个人。","gainTrimmed":false,"remark":"职场中的性骚扰见第 19 章第 18 条。","source":"《民法典》第一千零一十条；《妇女权益保障法》第二十三条、第二十五条；《治安管理处罚法》（2025 年修订）第五十二条（猥亵他人的处罚）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-11":{"costText":"多一份警惕。","gainText":"把风险挡在发生之前。","gainTrimmed":false,"remark":"受到性侵害后，除了报警，也要及时就医，必要时进行紧急避孕和传染病阻断。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-12":{"costText":"当面揭穿的勇气。","gainText":"保护隐私，也让偷拍者受到处罚。","gainTrimmed":false,"remark":"入住酒店、民宿时，可以用手机手电筒检查一下烟感、插座、电视等位置有没有异常的小孔反光。","source":"《治安管理处罚法》（2025 年修订）第五十条第一款第六项（偷窥、偷拍、窃听、散布他人隐私）；《民法典》第一千零三十三条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq28-13":{"costText":"站出来的风险。","gainText":"守住做人的尊严。","gainTrimmed":false,"remark":"正常的工作批评怎么接，见第 18 章第 17 条。","source":"《民法典》第一百零九条（自然人的人格尊严受法律保护）；《劳动合同法》第八十八条第三项（用人单位侮辱、体罚、殴打劳动者的，依法给予行政处罚，造成损害的承担赔偿责任）。","sourceTrimmed":false,"tip":"「王总，这件事是我做得不好，我接受批评。但请您不要说我家人。」","links":[],"evType":"法条"},"rq28-14":{"costText":"一条措辞小心的消息。","gainText":"没有借条，也能把借款关系说清楚。","gainTrimmed":false,"remark":"借条应写明的内容和利息上限，见第 12 章第 3 条、第 4 条。","source":"《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》（2020 年第二次修正）关于仅凭转账凭证起诉时双方举证责任的规定；《民法典》第一百九十五条（义务人同意履行的，诉讼时效中断）。","sourceTrimmed":false,"tip":"「上次三月份借你的两万块，你看什么时候方便还我？我这边下个月要交房租。」","links":[],"evType":"经验共识"},"rq28-15":{"costText":"时间、诉讼费和撕破脸的决心。","gainText":"用法律手段把钱要回来。","gainTrimmed":false,"remark":"小额诉讼的标的额上限为各省上年度就业人员年平均工资的百分之五十，具体数额各地不同。","source":"《民法典》第一百八十八条（诉讼时效三年）、第一百九十五条（时效中断）；《民事诉讼法》（2023 年修正）第二百二十五条至第二百二十七条（支付令）、第一百六十五条（小额诉讼）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-16":{"costText":"顶住压力的勇气。","gainText":"清白不被一时的慌乱葬送。","gainTrimmed":false,"remark":"被冤枉后名誉受损的，可以要求对方赔礼道歉、消除影响，见本章第 19 条。","source":"《消费者权益保护法》第二十七条（经营者不得搜查消费者的身体及其携带的物品，不得侵犯消费者的人身自由）；《治安管理处罚法》（2025 年修订）第五十条第一款第三项；《刑法》第二百四十三条（诬告陷害罪）。","sourceTrimmed":false,"tip":"「我没有拿。您如果有怀疑，我们报警，让警察来处理，但您没有权利搜我的包。」","links":[],"evType":"法条"},"rq28-17":{"costText":"面对羞耻感的勇气。","gainText":"止损，也让对方受到法律制裁。","gainTrimmed":false,"remark":"被骗下载的「聊天软件」往往会窃取通讯录，及时卸载并修改相关账号密码。","source":"《刑法》第二百七十四条（敲诈勒索罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-18":{"costText":"一分钟存进通讯录。","gainText":"遇事不慌，找对门路。","gainTrimmed":false,"remark":"各地热线的服务时间和范围可能不同，以当地公布的为准。","source":"经验共识，本书整理；号码为有关部门公布的服务热线。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-19":{"costText":"诉讼的时间和精力。","gainText":"让对方为伤害付出代价，也恢复你的名声。","gainTrimmed":false,"remark":"网络上的侵权内容，可以同时通知平台删除，见第 26 章第 17 条。","source":"《民法典》第九百九十五条（人格权受到侵害的民事责任，部分请求权不适用诉讼时效）、第一千一百八十三条（严重精神损害的赔偿）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-20":{"costText":"咽下「以牙还牙」的冲动。","gainText":"讨回公道，自己也干干净净。","gainTrimmed":false,"remark":"合法的催收方式见本章第 15 条。","source":"《刑法》第二百三十八条（非法拘禁罪）、第二百九十三条之一（催收非法债务罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-21":{"costText":"准备申请材料。","gainText":"没钱也能维权。","gainTrimmed":false,"remark":"法律咨询服务一般不审查经济状况，任何人都可以咨询。","source":"《法律援助法》（2022 年 1 月 1 日起施行）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq28-22":{"costText":"承认自己需要帮助。","gainText":"伤害终会过去，人要好好地走出来。","gainTrimmed":false,"remark":"朋友向你求助时怎么做，见第 16 章第 14 条。","source":"国家卫生健康委关于应用「12356」全国统一心理援助热线电话的通知（2024 年 12 月）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-1":{"costText":"多想一层。","gainText":"遇到「好意」时心里有一杆秤。","gainTrimmed":false,"remark":"纪律的标准比刑法严格得多，没有构成犯罪，也可能受到党纪政务处分。","source":"《刑法》第三百八十五条（受贿罪）、第三百八十九条（行贿罪）；《中国共产党纪律处分条例》（2023 年修订）第九十七条（收受明显超出正常礼尚往来的财物）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-2":{"costText":"放弃「花钱买捷径」的念头。","gainText":"别让一次「打点」毁掉一生。","gainTrimmed":false,"remark":"未达到刑事标准的行贿，也可能受到行政处罚和纪律处分，并被列入行贿人信息库。","source":"《刑法》第三百八十九条、第三百九十条；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释》（2016 年）第七条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-3":{"costText":"了解一下新规。","gainText":"知道哪些行为风险最大。","gainTrimmed":false,"remark":"同一修正案还加重了对单位行贿、对单位行贿罪的处罚。","source":"《刑法修正案（十二）》（2024 年 3 月 1 日起施行）修改后的《刑法》第三百九十条第二款。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-4":{"costText":"顶住对方的刁难。","gainText":"保护自己，也让索贿者受到追究。","gainTrimmed":false,"remark":"索贿的，对受贿人从重处罚，见《刑法》第三百八十六条。","source":"《刑法》第三百八十九条第三款。","sourceTrimmed":false,"tip":"「这件事我是按正常程序申请的，材料都齐全。如果有什么问题，请您书面告诉我依据。」","links":[],"evType":"经验共识"},"rq29-5":{"costText":"面对后果的勇气。","gainText":"把损失控制在最小。","gainTrimmed":false,"remark":"对非国家工作人员行贿的，被追诉前主动交待，可以减轻或者免除处罚，见《刑法》第一百六十四条第四款。","source":"《刑法》第三百九十条第三款（刑法修正案（十二）修改后）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-6":{"costText":"放弃「平时多烧香」的想法。","gainText":"不在「没有请托」的错觉中越过红线。","gainTrimmed":false,"remark":"党纪对下属、管理对象送礼的限制更严，见第 23 章第 8 条。","source":"最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释》（2016 年）第十三条第二款、第十五条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-7":{"costText":"学会识别「换了包装」的好处。","gainText":"不被换了名目的贿赂套住。","gainTrimmed":false,"remark":"收受贵重财物没有办理过户等权属变更的，不影响受贿的认定。","source":"最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释》（2016 年）第十二条；最高人民法院、最高人民检察院《关于办理受贿刑事案件适用法律若干问题的意见》（2007 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-8":{"costText":"一次严肃的家庭谈话。","gainText":"堵住「家门口」的漏洞。","gainTrimmed":false,"remark":"纪律上对领导干部配偶、子女经商办企业也有专门规定，见《中国共产党纪律处分条例》（2023 年修订）第一百零七条。","source":"最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释》（2016 年）第十六条第二款；《刑法》第三百八十八条之一（利用影响力受贿罪）。","sourceTrimmed":false,"tip":"「以后不管谁送东西、托你办事，你都说『家里有规矩，不收不管』，然后告诉我。」","links":[],"evType":"法条"},"rq29-9":{"costText":"拒绝熟人的请托。","gainText":"别为了「顺手」的人情踩进刑法。","gainTrimmed":false,"remark":"打招呼、干预他人办事本身也违反纪律，见第 23 章第 17 条。","source":"《刑法》第三百八十八条；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释（二）》（法释〔2026〕6 号，2026 年 5 月 1 日起施行）第十三条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-10":{"costText":"拒绝「牵线搭桥」的请求。","gainText":"不替别人背上刑事责任。","gainTrimmed":false,"remark":"介绍贿赂人在被追诉前主动交待的，可以减轻或者免除处罚。","source":"《刑法》第三百九十二条（介绍贿赂罪）、第三百九十条之一（对有影响力的人行贿罪）；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释（二）》（2026 年）第十七条。","sourceTrimmed":false,"tip":"「这种事我真帮不了，也劝你别这么办，按正常程序走最稳妥。」","links":[],"evType":"法条"},"rq29-11":{"costText":"放弃走捷径的幻想。","gainText":"保住钱，也保住前途。","gainTrimmed":false,"remark":"常见诈骗套路的识别见第 30 章。","source":"《公务员法》第二十三条（录用采取公开考试、严格考察、平等竞争、择优录取的办法）；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释（二）》（2026 年）第十七条第四款（虚构与国家工作人员关系密切的事实骗取财物的，以诈骗罪定罪处罚）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-12":{"costText":"放弃「行业惯例」里的灰色收入。","gainText":"不因为「大家都这样」而丢掉工作、背上案底。","gainTrimmed":false,"remark":"商业贿赂的行政责任见第 22 章第 11 条。","source":"《刑法》第一百六十三条、第一百六十四条；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释（二）》（2026 年）第八条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-13":{"costText":"守住每一张票据。","gainText":"干干净净拿工资。","gainTrimmed":false,"remark":"领导要求你帮忙做假报销的，按第 18 章第 10 条处理。","source":"《刑法》第二百七十一条；最高人民法院、最高人民检察院《关于办理贪污贿赂刑事案件适用法律若干问题的解释（二）》（2026 年）第八条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-14":{"costText":"顶住「过几天就还」的诱惑。","gainText":"不因为一次周转毁掉职业生涯。","gainTrimmed":false,"remark":"在提起公诉前将挪用的资金退还的，可以从轻或者减轻处罚。","source":"《刑法》第二百七十二条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-15":{"costText":"主动申报利益冲突、回避。","gainText":"不让「照顾亲戚」变成刑事风险。","gainTrimmed":false,"remark":"公司董事、高管还有《公司法》规定的忠实义务，关联交易要依法报告。","source":"《刑法》第一百六十六条（为亲友非法牟利罪，刑法修正案（十二）增加第二款）；同修正案对第一百六十五条（非法经营同类营业罪）的修改。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-16":{"costText":"一次登记、一次退还。","gainText":"把被动变主动，清清白白。","gainTrimmed":false,"remark":"企业员工收到供应商的礼品，按公司的礼品申报制度处理。","source":"最高人民法院、最高人民检察院《关于办理受贿刑事案件适用法律若干问题的意见》（2007 年）第九条。","sourceTrimmed":false,"tip":"「东西我已经让快递原样退回了，单号是 SF123……，请您查收。以后真的不用这样。」","links":[],"evType":"法条"},"rq29-17":{"costText":"守住「事后」的诱惑。","gainText":"不留「定时炸弹」。","gainTrimmed":false,"remark":"离职后利用原职权影响为请托人谋利、收受财物的，还可能构成利用影响力受贿罪。","source":"最高人民法院、最高人民检察院《关于办理受贿刑事案件适用法律若干问题的意见》（2007 年）第十条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq29-18":{"costText":"放弃「花钱买单子」的捷径。","gainText":"企业的长期信用比一单生意值钱。","gainTrimmed":false,"remark":"具体的惩戒措施以各地各部门的规定为准。","source":"中央纪委国家监委、中央组织部、中央统战部、中央政法委、最高人民法院、最高人民检察院《关于进一步推进受贿行贿一起查的意见》（2021 年）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-19":{"costText":"站出来的勇气。","gainText":"让违法者付出代价，也保护自己。","gainTrimmed":false,"remark":"举报要实事求是，捏造事实诬告他人的，要承担法律责任，见第 28 章第 16 条。","source":"《监察法》关于任何单位和个人有权检举、控告，监察机关应当保护举报人的规定；中央纪委国家监委举报网站与 12388 举报电话。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-20":{"costText":"把握分寸的心思。","gainText":"企业走得稳，官员也不被你连累。","gainTrimmed":false,"remark":"正常的工作接待、调研座谈，按规定的标准和程序办。","source":"经验共识，本书整理；「亲」「清」新型政商关系的提法见 2016 年全国政协会议期间习近平看望民建、工商联委员时的讲话。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq29-21":{"costText":"可能被说「不懂行」「太死板」。","gainText":"不被「惯例」带进坑里。","gainTrimmed":false,"remark":"医生、老师的「红包」问题见第 24 章第 11 条、第 15 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「这块我们公司有明确的合规要求，我做不了主。按正常流程走，结果怎样我都接受。」","links":[],"evType":"经验共识"},"rq29-22":{"costText":"可能少办成一些事，少交一些「朋友」。","gainText":"一辈子睡得安稳。","gainTrimmed":false,"remark":"人情账的正常往来见第 6 章，送礼的分寸见第 7 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-1":{"costText":"诚实地审视一段关系。","gainText":"在陷得更深之前看清楚。","gainTrimmed":false,"remark":"可以把这一条发给信任的朋友，请他从旁观者的角度看看你的处境。","source":"Stark, E. (2007). Coercive Control: How Men Entrap Women in Personal Life. Oxford University Press（强制控制的概念与特征；该模式同样可能发生在任何性别之间）。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-2":{"costText":"承认自己可能被操控了。","gainText":"认出套路，及时抽身。","gainTrimmed":false,"remark":"对方以自伤、自杀相威胁时，不要独自承担，联系他的家人或报警，同时保护好自己。","source":"经验共识，本书整理；参考亲密关系暴力与强制控制的相关研究。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-3":{"costText":"开始记录、相信自己。","gainText":"重新找回对自己的信任。","gainTrimmed":false,"remark":"「煤气灯」一词来自 20 世纪 40 年代的同名电影，片中丈夫通过调暗煤气灯等手段让妻子怀疑自己的神智。","source":"Sweet, P. L. (2019). The sociology of gaslighting. American Sociological Review, 84(5), 851–875.","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-4":{"costText":"承受对方的失望和指责。","gainText":"不再被别人的情绪绑架人生。","gainTrimmed":false,"remark":"家人之间的情感勒索最难拒绝，可以参考第 13 章与父母相处的方法。","source":"Forward, S., & Frazier, D. (1997). Emotional Blackmail: When the People in Your Life Use Fear, Obligation, and Guilt to Manipulate You. HarperCollins.","sourceTrimmed":false,"tip":"「我知道你很失望，但这件事我想清楚了，答案还是不行。我们可以聊别的办法。」","links":[],"evType":"经验共识"},"rq30-5":{"costText":"被说「冷漠」「不近人情」。","gainText":"守住自己的边界和钱包。","gainTrimmed":false,"remark":"拒绝的具体方法见第 4 章，尤其是第 5 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我理解你的难处，但这件事我帮不上。这和我们的关系好不好没有关系。」","links":[],"evType":"经验共识"},"rq30-6":{"costText":"认清现实、准备退路的勇气。","gainText":"保住自信，也保住职业发展。","gainTrimmed":false,"remark":"领导「画饼」怎么应对见第 18 章第 20 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-7":{"costText":"一段艰难的过渡期。","gainText":"一步步把生活拿回自己手里。","gainTrimmed":false,"remark":"前任纠缠骚扰的处理见第 28 章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-8":{"costText":"把私事交给法律的决心。","gainText":"知道法律可以站在你这一边。","gainTrimmed":false,"remark":"家庭暴力的应对见第 28 章第 9 条。","source":"《反家庭暴力法》第二条（家庭暴力包括经常性谩骂、恐吓等方式实施的精神侵害）；《刑法》第二百六十条（虐待罪）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq30-9":{"costText":"多给自己一晚上冷静期。","gainText":"花钱由自己决定，而不是被情绪推着走。","gainTrimmed":false,"remark":"被诱导签了预付卡、贷款合同的，及时向 12315 投诉，必要时咨询律师。","source":"Cialdini, R. B. (1984). Influence: The Psychology of Persuasion. William Morrow.","sourceTrimmed":false,"tip":"「东西我先不要了，谢谢你的小礼物，我回去想想。」","links":[],"evType":"经验共识"},"rq30-10":{"costText":"一遍遍地提醒父母。","gainText":"守住父母一辈子的积蓄。","gainTrimmed":false,"remark":"已经被骗的，不要责怪父母，帮他们一起报警和维权。","source":"经验共识，本书整理；参考 2022 年起全国开展的打击整治养老诈骗专项行动公布的典型案例。","sourceTrimmed":false,"tip":"（对父母）「妈，那些天天送东西、叫您妈的年轻人，图的是您的退休金。买什么之前跟我说一声，我帮您查查。」","links":[],"evType":"经验共识"},"rq30-11":{"costText":"拒绝亲友「带你发财」的邀请。","gainText":"不被骗走钱，也不把亲友拖下水。","gainTrimmed":false,"remark":"被骗进传销窝点、人身自由受限的，想办法报警或向外界传递位置信息。","source":"《禁止传销条例》第二条、第七条（传销的定义与行为类型）；《刑法》第二百二十四条之一（组织、领导传销活动罪）。","sourceTrimmed":false,"tip":"「这种要交钱拉人的项目，我一律不参加，你也小心点。」","links":[],"evType":"法条"},"rq30-12":{"costText":"放弃「稳赚不赔」的诱惑。","gainText":"守住血汗钱。","gainTrimmed":false,"remark":"参与非法集资受到的损失，由参与人自行承担，见该条例第二十五条，所以宁可错过，不要冒险。","source":"《防范和处置非法集资条例》（2021 年施行）第二条（非法集资的定义）、第十九条（涉嫌非法集资的常见行为类型）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq30-13":{"costText":"养成「先停一停」的习惯。","gainText":"挡住绝大多数骗局。","gainTrimmed":false,"remark":"不确定的，拨打 110 或 96110 咨询。","source":"经验共识，本书整理；参考公安机关反诈宣传。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-14":{"costText":"顶住恐惧，挂掉电话。","gainText":"不被恐吓骗走积蓄。","gainTrimmed":false,"remark":"被要求开启屏幕共享、下载「会议软件」的，立刻停止并挂断。","source":"经验共识，本书整理；参考公安机关反诈宣传。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-15":{"costText":"放弃「动动手指就赚钱」的幻想。","gainText":"不在「小钱」上栽大跟头。","gainTrimmed":false,"remark":"学生和宝妈是刷单诈骗的高发人群，家人之间要互相提醒。","source":"《反不正当竞争法》（2025 年修订）第九条第二款（不得通过组织虚假交易、虚假评价等方式帮助其他经营者进行虚假或者引人误解的商业宣传）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq30-16":{"costText":"在感情最甜的时候保持清醒。","gainText":"保住钱，也及早止住感情上的伤害。","gainTrimmed":false,"remark":"已经投了钱的，立刻停止追加，不要相信「再交一笔保证金就能提现」，马上报警。","source":"经验共识，本书整理；参考公安机关公布的典型案例。","sourceTrimmed":false,"tip":"「我不做任何投资，也不在别人推荐的平台上充钱。」","links":[],"evType":"经验共识"},"rq30-17":{"costText":"挂掉电话，自己去官方渠道核实。","gainText":"不为一个根本不存在的问题买单。","gainTrimmed":false,"remark":"查询个人信用报告，可以通过中国人民银行征信中心的官方渠道或商业银行的网银、手机银行。","source":"《征信业管理条例》第十六条（不良信息保存五年）、第十七条（每年两次免费获取本人信用报告）、第二十五条（异议与更正）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq30-18":{"costText":"一个电话的时间。","gainText":"一个电话，挡住一次损失。","gainTrimmed":false,"remark":"工作中涉及付款的，坚持按财务流程办理，不接受「先转后补」。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王总，我打您电话确认一下转账的事，您方便接一下吗？」","links":[],"evType":"经验共识"},"rq30-19":{"costText":"和家人约定一个暗号。","gainText":"技术再逼真，也骗不过一个回拨电话。","gainTrimmed":false,"remark":"发现自己的照片、声音被用于合成诈骗内容的，及时报警并告知亲友。","source":"经验共识，本书整理；参考公安机关反诈宣传。","sourceTrimmed":false,"tip":"（视频中）「你先挂了，我用你的手机号打给你。」","links":[],"evType":"经验共识"},"rq30-20":{"costText":"放弃「暴富」的念头。","gainText":"不把积蓄交给骗子。","gainTrimmed":false,"remark":"可以在中国证监会、国家金融监督管理总局的官网查询机构是否持牌。","source":"经验共识，本书整理；参考公安机关反诈宣传。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-21":{"costText":"放弃「月入几万、包吃包住」的诱惑。","gainText":"避开可能改变一生的危险。","gainTrimmed":false,"remark":"家人疑似被骗出境、失联的，立即报警，并联系中国驻当地使领馆。","source":"经验共识，本书整理；参考公安机关、外交部发布的安全提醒。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-22":{"costText":"拒绝「轻松赚佣金」的诱惑。","gainText":"不为一点佣金搭上前途。","gainTrimmed":false,"remark":"已经借出的，立即挂失、注销，并主动向公安机关说明情况。","source":"《刑法》第二百八十七条之二（帮助信息网络犯罪活动罪）、第三百一十二条（掩饰、隐瞒犯罪所得、犯罪所得收益罪）；《反电信网络诈骗法》第三十一条。","sourceTrimmed":false,"tip":"「我的卡只有我自己用，多少钱都不借。」","links":[],"evType":"法条"},"rq30-23":{"costText":"放下羞愧，立刻行动。","gainText":"争取把损失降到最低。","gainTrimmed":false,"remark":"被骗不丢人，不要因为怕被责怪而拖延报警，家人也不要一味埋怨。","source":"经验共识，本书整理；参考公安机关反诈宣传。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq30-24":{"costText":"一个周末的设置和平时的陪伴。","gainText":"给家人的钱袋子上一道锁。","gainTrimmed":false,"remark":"孩子玩游戏时遇到「免费领皮肤」「解冻账号」的，同样是常见的诈骗套路。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（对父母）「以后谁让您转账，不管说得多急，您都先给我打个电话，我们一起看看。」","links":[],"evType":"经验共识"},"rq31-1":{"costText":"投入时间和真心。","gainText":"一辈子的朋友，和最早的口碑。","gainTrimmed":false,"remark":"宿舍矛盾的处理可以参考第 25 章邻里相处的思路：先当面沟通，再找辅导员协调。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-2":{"costText":"几封邮件和一份整理好的材料。","gainText":"别人愿意帮你，也愿意下次再帮。","gainTrimmed":false,"remark":"被拒绝也不要介意，老师可能确实太忙或者不够了解你。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「王老师，我想申请某某大学的硕士项目，截止日期是 12 月 15 日。附件是我的简历和个人陈述，如果您方便的话，能否请您为我写一封推荐信？」","links":[],"evType":"经验共识"},"rq31-3":{"costText":"在小事上较真。","gainText":"职业生涯的地基打得牢。","gainTrimmed":false,"remark":"具体做法见第 17 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-4":{"costText":"多一份心思。","gainText":"为将来组建家庭打下基础。","gainTrimmed":false,"remark":"见家长、彩礼等见第 14 章，地域习俗差异见第 27 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-5":{"costText":"在原生家庭和小家庭之间找平衡。","gainText":"小家庭稳固，大家庭和睦。","gainTrimmed":false,"remark":"婚后家庭边界见第 15 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-6":{"costText":"一份答谢的心思。","gainText":"喜事办得体面，人情账也清楚。","gainTrimmed":false,"remark":"去看望别人家的产妇和新生儿，见第 8 章第 7 条；满月酒、抓周等习俗见第 27 章第 12 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「谢谢大家的祝福！宝宝和妈妈都挺好，这段时间先让她好好休息，满月后请大家吃饭。」","links":[],"evType":"经验共识"},"rq31-7":{"costText":"在孩子面前管住自己的言行。","gainText":"孩子长大后既懂礼数，又能保护自己。","gainTrimmed":false,"remark":"和老师、其他家长打交道见第 24 章。","source":"Bandura, A. (1977). Social Learning Theory. Prentice-Hall（儿童通过观察和模仿习得社会行为）。","sourceTrimmed":false,"tip":"（亲戚要孩子表演时）「孩子今天不太想表演，我们下次再说，来，先吃饭。」","links":[],"evType":"经验共识"},"rq31-8":{"costText":"接受有些关系会慢慢变淡。","gainText":"关系少了，幸福感反而更高。","gainTrimmed":false,"remark":"缩减随礼范围的方法见第 6 章第 15 条。","source":"Carstensen, L. L., Isaacowitz, D. M., & Charles, S. T. (1999). Taking time seriously: A theory of socioemotional selectivity. American Psychologist, 54(3), 165–181.","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-9":{"costText":"时间、金钱和耐心。","gainText":"尽孝不留遗憾。","gainTrimmed":false,"remark":"和父母相处的具体方法见第 13 章；兄弟姐妹之间赡养的分工，可以签订书面协议。","source":"《老年人权益保障法》第十八条（关心老年人精神需求，经常看望问候）、第二十一条（老年人婚姻自由受法律保护）、第二十二条（老年人对个人财产依法享有处分权）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq31-10":{"costText":"一份合适的礼物，和管住嘴的克制。","gainText":"探望是安慰，而不是打扰。","gainTrimmed":false,"remark":"探望传染病人、重症监护病人，要遵守医院的探视规定；探病礼物的选择见第 7 章第 13 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「看你气色还不错，安心养着，单位的事别操心。我就不多打扰了，有事随时叫我。」","links":[],"evType":"经验共识"},"rq31-11":{"costText":"一点时间和行动。","gainText":"在最难的时候，被记住的是那个出现的人。","gainTrimmed":false,"remark":"众筹治病的，捐款量力而行，不捐也不必有负担。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我这周三下午有空，可以帮你去医院拿报告，你看行吗？」","links":[],"evType":"经验共识"},"rq31-12":{"costText":"时刻提醒自己。","gainText":"走得高，也走得稳。","gainTrimmed":false,"remark":"体制内的纪律要求见第 23 章，利益输送的红线见第 29 章。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-13":{"costText":"放下面子。","gainText":"熬过低谷，也看清了谁值得深交。","gainTrimmed":false,"remark":"情绪长期低落的，及时寻求专业帮助，可以拨打 12356 心理援助热线。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我最近工作没了，正在找新的机会。你那边要是听说有合适的岗位，帮我留意一下，谢谢。」","links":[],"evType":"经验共识"},"rq31-14":{"costText":"咽下想倾诉、想「讨公道」的冲动。","gainText":"体面地翻篇，也少一些流言。","gainTrimmed":false,"remark":"离婚后和孩子相处、探望安排，见第 15 章第 19 条；前任纠缠骚扰的，见第 28 章第 8 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"「我们已经和平分开了，现在各自都挺好，谢谢关心。」","links":[],"evType":"经验共识"},"rq31-15":{"costText":"漫长的磨合。","gainText":"新家庭少一些猜疑，多一些信任。","gainTrimmed":false,"remark":"夫妻财产约定见第 15 章；带孩子再婚时怎么让孩子慢慢接受，见第 14 章第 21 条。","source":"《民法典》第一千零七十二条。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-16":{"costText":"放下权力和习惯。","gainText":"退得体面，过得自在。","gainTrimmed":false,"remark":"公务员、国企人员退休后的从业限制见第 23 章第 19 条。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-17":{"costText":"时间、体力和忍耐。","gainText":"三代人都过得舒心。","gainTrimmed":false,"remark":"老人带孩子是情分不是义务，子女要尊重父母的选择。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"（子女对父母）「妈，您带孩子太辛苦了。吃糖这件事我们想控制一下，您帮我们盯着点，有什么不方便的跟我说。」","links":[],"evType":"经验共识"},"rq31-18":{"costText":"说服子女的耐心，或者说服自己接受。","gainText":"老人有伴，子女安心。","gainTrimmed":false,"remark":"老人的个人财产由其本人处分，子女不得干涉，见该法第二十二条。","source":"《老年人权益保障法》第二十一条。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq31-19":{"costText":"面对「不吉利」话题的勇气。","gainText":"减少家人的猜疑和争执。","gainTrimmed":false,"remark":"可以同时整理好银行账户、保险、房产和重要数字账号的清单，告诉信任的家人存放位置。","source":"《民法典》第三十三条（意定监护）、第一千一百三十四条至第一千一百三十七条（遗嘱形式）、第一千一百四十二条（以最后的遗嘱为准）。","sourceTrimmed":false,"tip":"","links":[],"evType":"法条"},"rq31-20":{"costText":"放下一些计较。","gainText":"既分得清，也不伤情。","gainTrimmed":false,"remark":"房产继承过户一般需要继承权公证或者继承人共同到不动产登记机构办理；分遗产的其他注意事项见第 12 章第 12 条。","source":"《民法典》第一千一百二十七条（法定继承顺序）、第一千一百三十条（同一顺序继承人一般均等，可以多分少分的情形）、第一千一百三十二条（协商处理继承问题）。","sourceTrimmed":false,"tip":"「爸妈辛苦一辈子，我们别为这个吵。按法律的份额，老三照顾得最多，多分一些，大家看行吗？」","links":[],"evType":"经验共识"},"rq31-21":{"costText":"一份清醒。","gainText":"人情始终是生活的帮手，而不是负担。","gainTrimmed":false,"remark":"缩减人情往来，从关系最远的那一圈开始，见第 1 章「差序格局」的说法。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"},"rq31-22":{"costText":"一辈子的修炼。","gainText":"走到哪里都有人愿意帮你，自己也活得坦荡。","gainTrimmed":false,"remark":"全书的总纲见 docs/人情世故的大道理.md。","source":"经验共识，本书整理。","sourceTrimmed":false,"tip":"","links":[],"evType":"经验共识"}};
